const d=JSON.parse(`[{"id":"en-s-sh-001","text":"She sells seashells by the seashore.","sound":"s/sh","difficulty":1,"source":"traditional","hint":"Keep the sh rounded and the s hissing, and do not rush the shore.","free":true},{"id":"en-s-sh-002","text":"I saw Susie sitting in a shoeshine shop.","sound":"s/sh","difficulty":2,"source":"traditional","hint":"Six shining shoes, then a clean stop. Smile on the sh.","free":true},{"id":"en-s-sh-003","text":"Six sleek swans swam swiftly south.","sound":"s/sh","difficulty":2,"source":"traditional","hint":"Let the s stay light. Do not turn sw into a swallow.","free":true},{"id":"en-s-sh-004","text":"The sixth sick sheikh's sixth sheep is sick.","sound":"s/sh","difficulty":3,"source":"traditional","hint":"A classic cluster. Slow first. Clarity before speed.","free":false},{"id":"en-s-sh-005","text":"Sarah's seaside summary was sharp, short, and sincere.","sound":"s/sh","difficulty":2,"source":"original","hint":"Leadership diction: finish each s without a hiss that lingers.","free":true},{"id":"en-s-sh-006","text":"Should she ship the shiny slides, or shelve the shaky ones?","sound":"s/sh","difficulty":3,"source":"original","hint":"Alternate sh and s. The meaning is the decision, not the speed.","free":false},{"id":"en-s-sh-007","text":"A cautious speaker chooses a precise sentence, then stops.","sound":"s/sh","difficulty":3,"source":"original","hint":"Soft s at the end of sentence. Do not add an extra hiss.","free":false},{"id":"en-s-sh-008","text":"The session starts at six, so set the status aside.","sound":"s/sh","difficulty":2,"source":"original","hint":"Boardroom s sounds. Keep starts and six distinct.","free":false},{"id":"en-s-sh-009","text":"Specific suggestions still seem slightly soft to the CFO.","sound":"s/sh","difficulty":4,"source":"original","hint":"sp, st, sl. Touch each consonant, then release.","free":false},{"id":"en-s-sh-010","text":"Fresh fish, freshly sliced, shipped before sunrise.","sound":"s/sh","difficulty":3,"source":"original","hint":"f and sh share air. Do not let fish become pish.","free":false},{"id":"en-s-sh-011","text":"Please pass a concise status, not a seaside story.","sound":"s/sh","difficulty":2,"source":"original","hint":"Practice the ask you will actually use in a stand-up.","free":true},{"id":"en-s-sh-012","text":"She insisted the decision was simple: ship it, then support it.","sound":"s/sh","difficulty":4,"source":"original","hint":"Two sh words, then a clean s in simple and support.","free":false},{"id":"en-s-sh-013","text":"The sales chief shared a single sentence, then sat.","sound":"s/sh","difficulty":3,"source":"original","hint":"Share and sat. Silence after sat is part of the drill.","free":false},{"id":"en-s-sh-014","text":"Suspicious estimates shrink trust. State the source, then the sum.","sound":"s/sh","difficulty":4,"source":"original","hint":"s clusters in suspicious, estimates, shrink, state, source, sum.","free":false},{"id":"en-s-sh-015","text":"Swiss wristwatches shine, yet the strap still slips.","sound":"s/sh","difficulty":2,"source":"original","hint":"s and sh with a wrist cluster. Slow the middle.","free":false},{"id":"en-s-sh-016","text":"The specialist's spreadsheet shows a shortfall in shipments.","sound":"s/sh","difficulty":5,"source":"original","hint":"Office diction. Hit specialist, spreadsheet, shortfall, shipments.","free":false},{"id":"en-th-017","text":"I thought a thought, but the thought I thought was not the thought I thought I thought.","sound":"th","difficulty":1,"source":"traditional","hint":"Classic th. Tongue lightly on the teeth, not pushed.","free":true},{"id":"en-th-018","text":"The thirty-three thieves thought that they thrilled the throne.","sound":"th","difficulty":2,"source":"traditional","hint":"th versus t. Thirty stays soft. Throne starts with a breath.","free":true},{"id":"en-th-019","text":"Whether the weather is warm, or whether the weather is not.","sound":"th","difficulty":2,"source":"traditional","hint":"th and w. A meeting-room warm-up for English weather small talk.","free":true},{"id":"en-th-020","text":"Both paths are ethical. This one is faster. That one is safer.","sound":"th","difficulty":3,"source":"original","hint":"Both, ethical, this, that. Use them in a real recommendation.","free":false},{"id":"en-th-021","text":"Thank you. Three things. Then the ask.","sound":"th","difficulty":2,"source":"original","hint":"A leader's opening. th at the start of thank, three, then.","free":true},{"id":"en-th-022","text":"I think the theory is thin. The evidence is thicker.","sound":"th","difficulty":3,"source":"original","hint":"Think and thin are soft th. Theory too. Do not say tink.","free":false},{"id":"en-th-023","text":"They gathered the authors, the athletes, and the mathematicians.","sound":"th","difficulty":4,"source":"original","hint":"th inside longer words. Keep the tongue lazy, not tense.","free":false},{"id":"en-th-024","text":"Nothing worth doing is finished on Thursday without a thesis.","sound":"th","difficulty":3,"source":"original","hint":"Thursday and thesis. Two th's, then a stop.","free":false},{"id":"en-th-025","text":"This is the thing. That is the noise around it.","sound":"th","difficulty":2,"source":"original","hint":"A clarity frame. This and that must not collapse into dis and dat.","free":false},{"id":"en-th-026","text":"The fourth booth threw three themes through the thread.","sound":"th","difficulty":4,"source":"original","hint":"Throw, three, through, thread. Breath, then tongue.","free":false},{"id":"en-th-027","text":"Breathe, then speak. The breath is the thought's first half.","sound":"th","difficulty":3,"source":"original","hint":"Breath and breathe. Feel the difference.","free":false},{"id":"en-th-028","text":"North, south, both truthful. Say which you choose.","sound":"th","difficulty":2,"source":"original","hint":"A decision sentence. th at the ends of north and south.","free":true},{"id":"en-th-029","text":"The wealthy author authored three thousand thoughtful theses.","sound":"th","difficulty":5,"source":"original","hint":"th in a chain. Wealthy is a w plus th.","free":false},{"id":"en-th-030","text":"Without the numbers, the theory is theatre.","sound":"th","difficulty":3,"source":"original","hint":"Theory and theatre. Same start, different ending.","free":false},{"id":"en-th-031","text":"They thank the team that stayed through the thunderstorm.","sound":"th","difficulty":4,"source":"original","hint":"A recognition line you can actually say on a Friday.","free":false},{"id":"en-r-l-032","text":"Red lorry, yellow lorry.","sound":"r/l","difficulty":1,"source":"traditional","hint":"The classic. Keep r back and l at the ridge behind the teeth.","free":true},{"id":"en-r-l-033","text":"Really rural. A rural juror.","sound":"r/l","difficulty":2,"source":"traditional","hint":"r stacked. Do not let rural become woo-ul.","free":true},{"id":"en-r-l-034","text":"Clearly, the real risk is delay, not the label.","sound":"r/l","difficulty":2,"source":"original","hint":"A leader line. clearly, real, risk, delay, label.","free":true},{"id":"en-r-l-035","text":"Larry rarely relies on a long relay of words.","sound":"r/l","difficulty":3,"source":"original","hint":"l and r alternating. Rely and relay are the trap.","free":false},{"id":"en-r-l-036","text":"The role is real. The title is irrelevant.","sound":"r/l","difficulty":3,"source":"original","hint":"role, real, irrelevant. Stress the r, lighten the l.","free":false},{"id":"en-r-l-037","text":"Please look, listen, and let her lead.","sound":"r/l","difficulty":2,"source":"original","hint":"Look and listen start with l. Let her lead is the point.","free":true},{"id":"en-r-l-038","text":"A brilliant brief still fails if the last line is blurry.","sound":"r/l","difficulty":4,"source":"original","hint":"brilliant, brief, fails, last, line, blurry.","free":false},{"id":"en-r-l-039","text":"Roll the plan left, or leave it right where it is.","sound":"r/l","difficulty":3,"source":"original","hint":"roll, left, leave, right. A decision fork.","free":false},{"id":"en-r-l-040","text":"The regional lead will relay the rule, not rewrite it.","sound":"r/l","difficulty":4,"source":"original","hint":"regional, lead, relay, rule, rewrite.","free":false},{"id":"en-r-l-041","text":"Earlier is clearer. Later is louder, and less trusted.","sound":"r/l","difficulty":3,"source":"original","hint":"earlier, clearer, later, louder.","free":false},{"id":"en-r-l-042","text":"Library, laboratory, laboratory library.","sound":"r/l","difficulty":2,"source":"original","hint":"l clusters. Used by coaches for a reason. Keep them separate.","free":false},{"id":"en-r-l-043","text":"Rarely will a ruler rule fairly if the rule is rarely read.","sound":"r/l","difficulty":5,"source":"original","hint":"r all the way. Fairly brings in an l.","free":false},{"id":"en-r-l-044","text":"The floor leader clarified the referral before lunch.","sound":"r/l","difficulty":3,"source":"original","hint":"floor, leader, clarified, referral.","free":false},{"id":"en-r-l-045","text":"Really, literally, regularly. Drop the filler, keep the r.","sound":"r/l","difficulty":4,"source":"original","hint":"Say the three words, then say the clean version: regularly.","free":false},{"id":"en-r-l-046","text":"All real leaders leave room for a reply.","sound":"r/l","difficulty":2,"source":"original","hint":"l and r in a sentence you might say in a one-to-one.","free":false},{"id":"en-p-b-047","text":"Peter Piper picked a peck of pickled peppers.","sound":"p/b","difficulty":1,"source":"traditional","hint":"Traditional and public. Pop the p, do not swallow it.","free":true},{"id":"en-p-b-048","text":"Betty Botter bought some butter, but the butter was bitter.","sound":"p/b","difficulty":2,"source":"traditional","hint":"b against t. Keep Betty and butter crisp.","free":true},{"id":"en-p-b-049","text":"A proper copper coffee pot.","sound":"p/b","difficulty":2,"source":"traditional","hint":"p and the vowel. Four stresses, equal weight.","free":true},{"id":"en-p-b-050","text":"The public brief is better when the point comes before the background.","sound":"p/b","difficulty":3,"source":"original","hint":"A BLUF sentence. public, brief, better, point, before, background.","free":false},{"id":"en-p-b-051","text":"Be brief. Be plain. Be done.","sound":"p/b","difficulty":2,"source":"original","hint":"Three beats. A power-pause drill between them.","free":true},{"id":"en-p-b-052","text":"Bob's budget proposal bumped the backup plan.","sound":"p/b","difficulty":3,"source":"original","hint":"b in a finance sentence. Do not let bump become mump.","free":false},{"id":"en-p-b-053","text":"Please publish the paper before the board breakfast.","sound":"p/b","difficulty":4,"source":"original","hint":"p chain. Publish, paper, before, board, breakfast.","free":false},{"id":"en-p-b-054","text":"A capable captain keeps the cabin calm.","sound":"p/b","difficulty":3,"source":"original","hint":"c and p. Capable, captain, cabin, calm.","free":false},{"id":"en-p-b-055","text":"Stop. Breathe. Begin the point.","sound":"p/b","difficulty":2,"source":"original","hint":"p and b with pauses. The pauses are the exercise.","free":false},{"id":"en-p-b-056","text":"The probe found a broken pump beside the backup pipe.","sound":"p/b","difficulty":4,"source":"original","hint":"Plant-floor diction. probe, broken, pump, beside, backup, pipe.","free":false},{"id":"en-p-b-057","text":"People buy the plan when the benefit is visible.","sound":"p/b","difficulty":3,"source":"original","hint":"People, buy, plan, benefit, visible.","free":false},{"id":"en-p-b-058","text":"Poppy's purple paperclip popped off the printed proposal.","sound":"p/b","difficulty":5,"source":"original","hint":"Playful on purpose. Then say a clean one-line proposal.","free":false},{"id":"en-p-b-059","text":"Big promise, small proof, broken trust.","sound":"p/b","difficulty":2,"source":"original","hint":"Three beats for credibility. Pause after each.","free":true},{"id":"en-p-b-060","text":"The best brief has one number and one verb.","sound":"p/b","difficulty":3,"source":"original","hint":"best, brief, number, verb. End on the verb.","free":false},{"id":"en-p-b-061","text":"Bring the problem, the options, and the recommendation.","sound":"p/b","difficulty":4,"source":"original","hint":"A meeting habit. b and p and the shape of a good update.","free":false},{"id":"en-w-v-062","text":"Which wristwatches are Swiss wristwatches?","sound":"w/v","difficulty":1,"source":"traditional","hint":"w and the r cluster. Whisper-level first, then full voice.","free":true},{"id":"en-w-v-063","text":"How much wood would a woodchuck chuck if a woodchuck could chuck wood?","sound":"w/v","difficulty":2,"source":"traditional","hint":"Traditional. would and wood must not smear together.","free":true},{"id":"en-w-v-064","text":"We value the work. We will not widen the scope.","sound":"w/v","difficulty":2,"source":"original","hint":"A boundary sentence. v and w distinct.","free":true},{"id":"en-w-v-065","text":"Eleven benevolent elephants.","sound":"w/v","difficulty":3,"source":"original","hint":"The classic vowel-and-v drill. Keep eleven even.","free":false},{"id":"en-w-v-066","text":"Victor reviewed the vendor's very vague warranty.","sound":"w/v","difficulty":3,"source":"original","hint":"v chain. Vague is the word you are learning to avoid, said clearly.","free":false},{"id":"en-w-v-067","text":"What we know. What we assume. What we will verify.","sound":"w/v","difficulty":2,"source":"original","hint":"Three lines. w at the start. Pause between them.","free":true},{"id":"en-w-v-068","text":"A vivid voice survives a noisy room when the vowels are open.","sound":"w/v","difficulty":4,"source":"original","hint":"vivid, voice, survives, vowels.","free":false},{"id":"en-w-v-069","text":"We were waiting while the valve was revised.","sound":"w/v","difficulty":3,"source":"original","hint":"Plant floor. waiting, while, valve, revised.","free":false},{"id":"en-w-v-070","text":"Avoid the waffle. Give the verdict.","sound":"w/v","difficulty":2,"source":"original","hint":"Avoid and waffle and verdict. Then do it in your next answer.","free":false},{"id":"en-w-v-071","text":"Whether we waive the fee depends on the value, not the volume.","sound":"w/v","difficulty":4,"source":"original","hint":"whether, waive, value, volume.","free":false},{"id":"en-w-v-072","text":"Every advisor advised a different avenue.","sound":"w/v","difficulty":3,"source":"original","hint":"v inside words. advisor, advised, avenue.","free":false},{"id":"en-w-v-073","text":"The warehouse wave overwhelmed the overnight shift.","sound":"w/v","difficulty":5,"source":"original","hint":"w and v in a long image. warehouse, wave, overwhelmed, overnight.","free":false},{"id":"en-w-v-074","text":"One voice. One version. One owner.","sound":"w/v","difficulty":2,"source":"original","hint":"A closing line. v and w and the rule of three.","free":false},{"id":"en-w-v-075","text":"We reviewed five wives of the same slide and kept one.","sound":"w/v","difficulty":3,"source":"original","hint":"A joke you can survive. reviewed, five, wives.","free":false},{"id":"en-w-v-076","text":"Move the vowel forward. The word will arrive with it.","sound":"w/v","difficulty":4,"source":"original","hint":"A coaching cue. vowel, forward, word, arrive, with.","free":false},{"id":"en-k-g-077","text":"Greek grapes, Greek grapes, Greek grapes.","sound":"k/g","difficulty":1,"source":"traditional","hint":"k and g. The back of the tongue taps, it does not grind.","free":true},{"id":"en-k-g-078","text":"Unique New York. Unique New York. You know you need unique New York.","sound":"k/g","difficulty":2,"source":"traditional","hint":"k and y. A classic. Keep unique from becoming a mumble.","free":true},{"id":"en-k-g-079","text":"Good. Clear. Kind. In that order when you correct someone.","sound":"k/g","difficulty":2,"source":"original","hint":"g, k, k. A feedback stance, said out loud.","free":true},{"id":"en-k-g-080","text":"The quick briefing cracked the gridlock.","sound":"k/g","difficulty":3,"source":"original","hint":"quick, briefing, cracked, gridlock.","free":false},{"id":"en-k-g-081","text":"Can you keep the critique about the work, not the person?","sound":"k/g","difficulty":3,"source":"original","hint":"A hard sentence worth practising. keep, critique, work.","free":false},{"id":"en-k-g-082","text":"Clock the cost. Cut the clutter. Keep the core.","sound":"k/g","difficulty":2,"source":"original","hint":"Three k beats. A decision filter.","free":false},{"id":"en-k-g-083","text":"The technical glitch clogged the gateway at the cog line.","sound":"k/g","difficulty":4,"source":"original","hint":"Industrial. glitch, clogged, gateway, cog.","free":false},{"id":"en-k-g-084","text":"Craig's colleague questioned the quota quietly.","sound":"k/g","difficulty":3,"source":"original","hint":"k and kw. colleague, questioned, quota, quietly.","free":false},{"id":"en-k-g-085","text":"A concrete example beats a grand claim.","sound":"k/g","difficulty":4,"source":"original","hint":"concrete, example, grand, claim. g and k.","free":false},{"id":"en-k-g-086","text":"Ask. Then go quiet. The quiet is part of the question.","sound":"k/g","difficulty":2,"source":"original","hint":"ask, go, quiet, question.","free":true},{"id":"en-k-g-087","text":"The executive committee could not connect the recommendation to the goal.","sound":"k/g","difficulty":5,"source":"original","hint":"A long k line. Say it as a critique of a slide, slowly.","free":false},{"id":"en-k-g-088","text":"Great work, specific gap, clear next step.","sound":"k/g","difficulty":3,"source":"original","hint":"Recognition shape. great, specific, gap, clear.","free":false},{"id":"en-k-g-089","text":"The cargo crane creaked, and the crew kept the gate clear.","sound":"k/g","difficulty":4,"source":"original","hint":"cargo, crane, creaked, crew, kept, gate, clear.","free":false},{"id":"en-k-g-090","text":"Begin again. Begin cleaner.","sound":"k/g","difficulty":2,"source":"original","hint":"g and k. Two tries, the second more articulate.","free":false},{"id":"en-vowels-091","text":"Toy boat. Toy boat. Toy boat.","sound":"vowels","difficulty":1,"source":"traditional","hint":"The mouth has to change shape. Do not let it become toy boy.","free":true},{"id":"en-vowels-092","text":"Red leather, yellow leather.","sound":"vowels","difficulty":2,"source":"traditional","hint":"Vowels plus l. leather must keep both syllables.","free":true},{"id":"en-vowels-093","text":"I own the outcome. I do not own the applause.","sound":"vowels","difficulty":2,"source":"original","hint":"Open oh and own. A composure line.","free":true},{"id":"en-vowels-094","text":"The idea is old. The opening is ours.","sound":"vowels","difficulty":3,"source":"original","hint":"idea, old, opening, ours. Diphthongs.","free":false},{"id":"en-vowels-095","text":"Please say the name slowly: Ane, Iker, Lucía, James, Priya.","sound":"vowels","difficulty":3,"source":"original","hint":"Practice the actual names you will say in two languages.","free":false},{"id":"en-vowels-096","text":"No, I do not know yet. I will know on Friday.","sound":"vowels","difficulty":2,"source":"original","hint":"The honest sentence. oh and ow. No filler after no.","free":false},{"id":"en-vowels-097","text":"Our hourly outage outline ought to be one page.","sound":"vowels","difficulty":4,"source":"original","hint":"ou and ow. hourly, outage, outline, ought, our.","free":false},{"id":"en-vowels-098","text":"A calm vowel carries further than a clenched jaw.","sound":"vowels","difficulty":3,"source":"original","hint":"The point of the drill, said as the drill.","free":false},{"id":"en-vowels-099","text":"Open. Offer. Ask.","sound":"vowels","difficulty":2,"source":"original","hint":"Three vowels, three moves in a negotiation.","free":false},{"id":"en-vowels-100","text":"The audio of your idea fails if the vowels collapse.","sound":"vowels","difficulty":4,"source":"original","hint":"audio, idea, fails, vowels.","free":false},{"id":"en-vowels-101","text":"I owe you a decision, not a tour of my doubts.","sound":"vowels","difficulty":3,"source":"original","hint":"owe, you, decision. A leader's promise.","free":false},{"id":"en-vowels-102","text":"Around the hour, our own account outgrew the old outlook.","sound":"vowels","difficulty":5,"source":"original","hint":"A chain of ow and ow. Slow, exaggerated, then normal.","free":false},{"id":"en-vowels-103","text":"Say it as if the back row paid to hear the vowels.","sound":"vowels","difficulty":2,"source":"original","hint":"A projection cue hidden in a sentence.","free":false},{"id":"en-vowels-104","text":"Either we agree the aim, or we are only busy.","sound":"vowels","difficulty":3,"source":"original","hint":"either, agree, aim. ee and ay.","free":false},{"id":"en-clusters-105","text":"Six thick thistle sticks.","sound":"clusters","difficulty":1,"source":"traditional","hint":"A traditional cluster. s, th, st. Slow.","free":false},{"id":"en-clusters-106","text":"The seething sea ceaseth and thus the seething sea sufficeth us.","sound":"clusters","difficulty":2,"source":"traditional","hint":"Traditional and dense. Clarity first.","free":false},{"id":"en-clusters-107","text":"Three free throws.","sound":"clusters","difficulty":2,"source":"original","hint":"th and fr. A sports classic used as a cluster drill.","free":false},{"id":"en-clusters-108","text":"Split the risk. Spring the decision. Stop the drift.","sound":"clusters","difficulty":3,"source":"original","hint":"spl, spr, st. A strategy sentence.","free":false},{"id":"en-clusters-109","text":"The strict script stripped the story to one strong line.","sound":"clusters","difficulty":3,"source":"original","hint":"str cluster repeated. Then use the line.","free":false},{"id":"en-clusters-110","text":"Ask for the next step, the owner, and the date.","sound":"clusters","difficulty":2,"source":"original","hint":"A closing cluster of meaning, with st and sp lightly touched.","free":false},{"id":"en-clusters-111","text":"Twelfth street's streetlamps flickered through the frost.","sound":"clusters","difficulty":4,"source":"original","hint":"tw, str, fl, fr. A hard one. Stay slow.","free":false},{"id":"en-clusters-112","text":"The plant director wants the downtime, the cause, and the restart.","sound":"clusters","difficulty":3,"source":"original","hint":"A real industrial sentence. Practice it cold.","free":false},{"id":"en-clusters-113","text":"Strengthen the strand. Stretch the story. Strike the surplus.","sound":"clusters","difficulty":4,"source":"original","hint":"str three times, with a different verb.","free":false},{"id":"en-clusters-114","text":"First the fact. Then the meaning. Then the move.","sound":"clusters","difficulty":2,"source":"original","hint":"Clusters are light. The structure is the point.","free":false},{"id":"en-clusters-115","text":"A scrambled spreadsheet obscured the straightforward trend.","sound":"clusters","difficulty":5,"source":"original","hint":"scr, spr, str. Office diction under pressure.","free":false},{"id":"en-clusters-116","text":"Trust is built in small, strict promises.","sound":"clusters","difficulty":3,"source":"original","hint":"tr and str. Say promises as three clear syllables.","free":false},{"id":"en-clusters-117","text":"The French press strategy impressed the board, briefly.","sound":"clusters","difficulty":4,"source":"original","hint":"pr, str, br. End cleanly on briefly.","free":false},{"id":"en-clusters-118","text":"Speak the consonant. Then the vowel. Then the word.","sound":"clusters","difficulty":2,"source":"original","hint":"The method, said as a twister of its own.","free":false},{"id":"en-clusters-119","text":"Glen's glass glimmered as the glad group gathered.","sound":"clusters","difficulty":3,"source":"original","hint":"gl cluster. Traditional shape, original line.","free":false},{"id":"en-s-sh-120","text":"A crisp close: what, who, and by when.","sound":"s/sh","difficulty":3,"source":"original","hint":"s and wh. The sentence you will use to end meetings.","free":false},{"id":"en-th-121","text":"There are three options. I recommend the third.","sound":"th","difficulty":2,"source":"original","hint":"th and a recommendation. The shape matters as much as the sound.","free":false},{"id":"en-r-l-122","text":"Clarify the role before you clarify the person.","sound":"r/l","difficulty":3,"source":"original","hint":"A leadership line with l and r in balance.","free":false},{"id":"en-p-b-123","text":"Bring proof, not a bigger promise.","sound":"p/b","difficulty":3,"source":"original","hint":"b and p. Credibility in eight words.","free":false},{"id":"en-w-v-124","text":"We will revisit the verdict when the evidence moves.","sound":"w/v","difficulty":3,"source":"original","hint":"A composed delay. v and w.","free":false},{"id":"en-k-g-125","text":"Keep the goal in the first sentence, not the fifth.","sound":"k/g","difficulty":3,"source":"original","hint":"k and g. BLUF, spoken.","free":false},{"id":"en-vowels-126","text":"I am accountable for the outcome, including the part that failed.","sound":"vowels","difficulty":3,"source":"original","hint":"Open vowels in a hard sentence. Practise without shrinking.","free":false},{"id":"en-clusters-127","text":"State the constraint. Then the choice it forces.","sound":"clusters","difficulty":3,"source":"original","hint":"st and the logic of a good recommendation.","free":false}]`),u=JSON.parse('[{"id":"es-r-rr-001","text":"Tres tristes tigres tragaban trigo en un trigal.","sound":"r/rr","difficulty":1,"source":"traditional","hint":"La r suave y la rr. La lengua toca una vez, o vibra. No empujes la mandíbula.","free":true},{"id":"es-r-rr-002","text":"Erre con erre cigarro, erre con erre barril. Rápido ruedan los carros cargados de azúcar del ferrocarril.","sound":"r/rr","difficulty":1,"source":"traditional","hint":"El trabalenguas clásico de la rr. Primero lento y exagerado.","free":true},{"id":"es-r-rr-003","text":"El perro de San Roque no tiene rabo porque Ramón Ramírez se lo ha robado.","sound":"r/rr","difficulty":2,"source":"traditional","hint":"r y rr en nombres. Ramón no es Lamón.","free":true},{"id":"es-r-rr-004","text":"Un burro comía berros y el perro se los robó. El burro lanzó un rebuzno y el perro soltó un ladrido.","sound":"r/rr","difficulty":2,"source":"traditional","hint":"Folclore. r entre vocales y rr en grupos.","free":false},{"id":"es-r-rr-005","text":"La reunión arranca con el riesgo, no con el relato.","sound":"r/rr","difficulty":3,"source":"original","hint":"Una frase de líder. reunión, arranca, riesgo, relato.","free":false},{"id":"es-r-rr-006","text":"Quiero un sí claro, no un rodeo.","sound":"r/rr","difficulty":2,"source":"original","hint":"r suave. Una frase para negociar.","free":true},{"id":"es-r-rr-007","text":"El ferrocarril recorre el barrio y el barro retrasa el carro.","sound":"r/rr","difficulty":4,"source":"original","hint":"rr y r en cadena. ferrocarril, recorre, barrio, barro, retrasa, carro.","free":false},{"id":"es-r-rr-008","text":"Rosa resumió el error, propuso el arreglo y cerró.","sound":"r/rr","difficulty":3,"source":"original","hint":"Tres verbos. error lleva rr. No te comas la vibración.","free":false},{"id":"es-r-rr-009","text":"Corrige el rumor antes de que corra por el correo.","sound":"r/rr","difficulty":3,"source":"original","hint":"corrige, rumor, corra, correo.","free":false},{"id":"es-r-rr-010","text":"Primero el criterio. Luego el ritmo.","sound":"r/rr","difficulty":2,"source":"original","hint":"r al inicio. Una regla de reunión.","free":true},{"id":"es-r-rr-011","text":"El director requiere un reporte breve, no un recorrido.","sound":"r/rr","difficulty":4,"source":"original","hint":"requiere, reporte, breve, recorrido.","free":false},{"id":"es-r-rr-012","text":"Rara vez un recurso raro resuelve un error recurrente.","sound":"r/rr","difficulty":5,"source":"original","hint":"r y rr seguidas. Hazlo lento.","free":false},{"id":"es-r-rr-013","text":"Abre la puerta al desacuerdo y cierra con un responsable.","sound":"r/rr","difficulty":3,"source":"original","hint":"Una frase de quien preside. desacuerdo, cierra, responsable.","free":false},{"id":"es-r-rr-014","text":"Herrero, hierro, herramienta. Tres golpes, tres sílabas claras.","sound":"r/rr","difficulty":2,"source":"original","hint":"rr y h muda. La h no se pronuncia. El hierro sí vibra.","free":false},{"id":"es-r-rr-015","text":"El paro de la línea tres duró cuarenta minutos por un rodamiento.","sound":"r/rr","difficulty":4,"source":"original","hint":"Frase de planta. paro, duró, rodamiento.","free":false},{"id":"es-s-z-c-016","text":"Compadre, cómpreme un coco. Compadre, no compro coco, porque como poco coco como, poco coco compro.","sound":"s/z/c","difficulty":1,"source":"traditional","hint":"c fuerte. En España la z y la c suave son distintas. El seseo también vale: la app lo acepta.","free":true},{"id":"es-s-z-c-017","text":"Cuando cuentes cuentos, cuenta cuántos cuentos cuentas.","sound":"s/z/c","difficulty":2,"source":"traditional","hint":"c fuerte. No conviertas cuenta en guenta.","free":true},{"id":"es-s-z-c-018","text":"La decisión es simple: cerramos el alcance o crece el plazo.","sound":"s/z/c","difficulty":2,"source":"original","hint":"c y s. Una frase de proyecto.","free":true},{"id":"es-s-z-c-019","text":"Necesito la cifra, la causa y el siguiente paso.","sound":"s/z/c","difficulty":3,"source":"original","hint":"c suave o s según tu acento. Las dos se aceptan al puntuar.","free":false},{"id":"es-s-z-c-020","text":"En Zaragoza se caza la zeta. En Sevilla se sesea. Las dos caben.","sound":"s/z/c","difficulty":3,"source":"original","hint":"Nota de distinción y seseo, dicha en voz alta.","free":false},{"id":"es-s-z-c-021","text":"Cero adornos. Una sola cifra. Un sentido.","sound":"s/z/c","difficulty":2,"source":"original","hint":"Una regla para contar datos.","free":false},{"id":"es-s-z-c-022","text":"La sucesión de excusas oscurece la solución.","sound":"s/z/c","difficulty":4,"source":"original","hint":"s y c. sucesión, excusas, oscurece, solución.","free":false},{"id":"es-s-z-c-023","text":"Si el precio sube, decimos el precio. No lo escondemos en la frase.","sound":"s/z/c","difficulty":3,"source":"original","hint":"s y p. Una frase de negociación.","free":false},{"id":"es-s-z-c-024","text":"Gracias. Son tres cosas. Luego la petición.","sound":"s/z/c","difficulty":2,"source":"original","hint":"s al inicio. Un arranque de reunión.","free":true},{"id":"es-s-z-c-025","text":"El proceso se sesgó cuando se saltó la revisión de las piezas.","sound":"s/z/c","difficulty":4,"source":"original","hint":"s en cadena. Proceso de planta.","free":false},{"id":"es-s-z-c-026","text":"Precisión no es prisa. La prisa se come las ces.","sound":"s/z/c","difficulty":3,"source":"original","hint":"Precisión, prisa, ces.","free":false},{"id":"es-s-z-c-027","text":"Las estaciones de inspección exigen paciencia, no velocidad ciega.","sound":"s/z/c","difficulty":5,"source":"original","hint":"s, c, x. estaciones, inspección, exigen, paciencia.","free":false},{"id":"es-s-z-c-028","text":"Haz la pausa donde cerrarías el punto, no donde te asustas.","sound":"s/z/c","difficulty":2,"source":"original","hint":"Una instrucción de muletillas, con s y c.","free":false},{"id":"es-s-z-c-029","text":"Socorro no es un plan. El plan es el siguiente responsable.","sound":"s/z/c","difficulty":3,"source":"original","hint":"s y r. Socorro, plan, siguiente, responsable.","free":false},{"id":"es-ll-y-030","text":"El cielo está enladrillado. ¿Quién lo desenladrillará?","sound":"ll/y","difficulty":1,"source":"traditional","hint":"ll tradicional. Con yeísmo, ll e y se parecen. Las dos valen.","free":true},{"id":"es-ll-y-031","text":"Yo llevo el hallazgo. Ella lleva la llamada.","sound":"ll/y","difficulty":2,"source":"original","hint":"Yo y llevo. Diferencia o no, según tu acento. Dícelo con intención.","free":true},{"id":"es-ll-y-032","text":"La ley es simple: una idea por frase.","sound":"ll/y","difficulty":2,"source":"original","hint":"ll o y. Una ley de claridad.","free":false},{"id":"es-ll-y-033","text":"Allí, en la orilla, brilla la botella.","sound":"ll/y","difficulty":3,"source":"original","hint":"Folclore de vocales y ll. Tradicional en espíritu, línea propia.","free":false},{"id":"es-ll-y-034","text":"El taller falló el sello y el llenado se fue a la calle.","sound":"ll/y","difficulty":3,"source":"original","hint":"Taller industrial. falló, sello, llenado, calle.","free":false},{"id":"es-ll-y-035","text":"Llámala por su nombre. Luego el hecho. Luego el efecto.","sound":"ll/y","difficulty":2,"source":"original","hint":"SBI en una frase. llama, nombre, hecho, efecto.","free":false},{"id":"es-ll-y-036","text":"La llave del almacén ya no abre, y ayer sí abría.","sound":"ll/y","difficulty":4,"source":"original","hint":"llave, ya, ayer. Yeísmo y distinción, las dos aceptadas.","free":false},{"id":"es-ll-y-037","text":"Un hallazgo pequeño, dicho pronto, vale más que un informe bello.","sound":"ll/y","difficulty":3,"source":"original","hint":"hallazgo, pequeño, bello.","free":false},{"id":"es-ll-y-038","text":"Yo propongo. Tú decides. Lo dejamos escrito.","sound":"ll/y","difficulty":2,"source":"original","hint":"Tres papeles. y y ll suaves.","free":true},{"id":"es-ll-y-039","text":"El murmullo del pasillo no es la decisión del consejo.","sound":"ll/y","difficulty":4,"source":"original","hint":"ll en murmullo y pasillo. Consejo cierra.","free":false},{"id":"es-ll-y-040","text":"Llegamos al límite. O recortamos el alcance o movemos la fecha.","sound":"ll/y","difficulty":3,"source":"original","hint":"llegamos, límite. Una decisión real.","free":false},{"id":"es-ll-y-041","text":"La malla amarilla del andamio brilla bajo la lluvia.","sound":"ll/y","difficulty":5,"source":"original","hint":"ll y y en una imagen de obra.","free":false},{"id":"es-ll-y-042","text":"No hay yuyo en la frase. Hay una petición.","sound":"ll/y","difficulty":2,"source":"original","hint":"Juego breve. Luego di la petición de verdad.","free":false},{"id":"es-ch-043","text":"María Chucena techaba su choza, y un techador que por allí pasaba le dijo: María Chucena, ¿techas tu choza o techas la ajena?","sound":"ch","difficulty":1,"source":"traditional","hint":"Tradicional. ch clara, sin convertirla en sh ni en y.","free":true},{"id":"es-ch-044","text":"Pepe Pecas pica papas con un pico. Con un pico pica papas Pepe Pecas.","sound":"ch","difficulty":2,"source":"traditional","hint":"p y c. El clásico de Pepe.","free":true},{"id":"es-ch-045","text":"Escucha. Repite el hecho. No el personaje.","sound":"ch","difficulty":2,"source":"original","hint":"ch en escucha y hecho. Una regla de feedback.","free":true},{"id":"es-ch-046","text":"El ocho de la noche no es una fecha. El viernes a las ocho, sí.","sound":"ch","difficulty":3,"source":"original","hint":"ch y fechas. Precisión.","free":false},{"id":"es-ch-047","text":"La ficha del paro cabe en un mensaje: qué, desde cuándo, siguiente paso.","sound":"ch","difficulty":3,"source":"original","hint":"ficha, paro. Lenguaje de planta.","free":false},{"id":"es-ch-048","text":"Mucho dato, poca chicha. Quédate con un número.","sound":"ch","difficulty":2,"source":"original","hint":"chicha es coloquial a propósito. Luego di el número.","free":false},{"id":"es-ch-049","text":"El chinche del contrato es la fecha, no el precio.","sound":"ch","difficulty":4,"source":"original","hint":"ch en chinche y fecha. Una frase de negociación.","free":false},{"id":"es-ch-050","text":"Aprovecha la pausa. No la rellenes con un este.","sound":"ch","difficulty":3,"source":"original","hint":"ch y la pausa. El drill de muletillas.","free":false},{"id":"es-ch-051","text":"Chus pechó el cheque y checó el chasis antes del turno.","sound":"ch","difficulty":4,"source":"original","hint":"ch en ráfaga. Luego vuelve a una frase normal.","free":false},{"id":"es-ch-052","text":"Hecho. Dueño. Fecha.","sound":"ch","difficulty":2,"source":"original","hint":"Tres golpes para cerrar una reunión.","free":true},{"id":"es-ch-053","text":"La brecha no es un drama. Es un número y una causa.","sound":"ch","difficulty":3,"source":"original","hint":"brecha. ch al final de sílaba, bien apoyada.","free":false},{"id":"es-ch-054","text":"El despacho rechazó el borracho borrador por capricho.","sound":"ch","difficulty":5,"source":"original","hint":"ch repetida. Capricho cierra con claridad, no con prisa.","free":false},{"id":"es-ch-055","text":"Dicho el acuerdo, se calla el adorno.","sound":"ch","difficulty":2,"source":"original","hint":"dicho, acuerdo, calla.","free":false},{"id":"es-clusters-056","text":"Pablito clavó un clavito. ¿Qué clavito clavó Pablito?","sound":"clusters","difficulty":1,"source":"traditional","hint":"cl tradicional. La lengua no se esconde.","free":true},{"id":"es-clusters-057","text":"Juan junta juncos junto a la zanja.","sound":"clusters","difficulty":2,"source":"traditional","hint":"j y z. En seseo, zanja suena con s. Se acepta.","free":true},{"id":"es-clusters-058","text":"Plantea el problema. Propón tres caminos. Pide la decisión.","sound":"clusters","difficulty":2,"source":"original","hint":"pl y pr. Un guion de reunión.","free":true},{"id":"es-clusters-059","text":"El tren trae el tramo, y el tramo trae el retraso.","sound":"clusters","difficulty":3,"source":"original","hint":"tr. tren, trae, tramo, retraso.","free":false},{"id":"es-clusters-060","text":"Blando no es amable. Amable es claro.","sound":"clusters","difficulty":3,"source":"original","hint":"bl. Una corrección de estilo.","free":false},{"id":"es-clusters-061","text":"El plan de planta prevé el paro, el plazo y la prueba.","sound":"clusters","difficulty":4,"source":"original","hint":"pl y pr en lenguaje industrial.","free":false},{"id":"es-clusters-062","text":"Primero la pregunta. Después tu respuesta.","sound":"clusters","difficulty":2,"source":"original","hint":"pr. No al revés.","free":false},{"id":"es-clusters-063","text":"Tras el tropiezo, el trabajo es transparente o no es confianza.","sound":"clusters","difficulty":4,"source":"original","hint":"tr. tropiezo, trabajo, transparente.","free":false},{"id":"es-clusters-064","text":"La cláusula clave cabe en una línea.","sound":"clusters","difficulty":3,"source":"original","hint":"cl. cláusula, clave.","free":false},{"id":"es-clusters-065","text":"El cristal del clúster crujió cuando la grúa cruzó el claro.","sound":"clusters","difficulty":5,"source":"original","hint":"cr y cl y gr. Hazlo lento.","free":false},{"id":"es-clusters-066","text":"No dramatices el plazo. Dramático es esconderlo.","sound":"clusters","difficulty":3,"source":"original","hint":"dr y pl.","free":false},{"id":"es-clusters-067","text":"Trae el dato. Deja el adjetivo en la puerta.","sound":"clusters","difficulty":2,"source":"original","hint":"tr. Una norma de presencia.","free":true},{"id":"es-clusters-068","text":"Comprueba el contrato, el cronograma y el criterio de salida.","sound":"clusters","difficulty":4,"source":"original","hint":"cr y tr. Tres c de un cierre de proyecto.","free":false},{"id":"es-clusters-069","text":"La prensa pregunta. Tú respondes con una frase, no con un túnel.","sound":"clusters","difficulty":3,"source":"original","hint":"pr. prensa, pregunta, respondes.","free":false},{"id":"es-j-070","text":"El jefe dejó el juicio y se quedó con el hecho.","sound":"j","difficulty":1,"source":"original","hint":"j suave, sin raspar. jefe, dejó, juicio.","free":true},{"id":"es-j-071","text":"El hipopótamo Hipo está con hipo. ¿Quién le quita el hipo al hipopótamo Hipo?","sound":"j","difficulty":2,"source":"traditional","hint":"Tradicional. La j no está. Sirve a la p y a la vocal. Incluido por ritmo. La j llega en los siguientes.","free":false},{"id":"es-j-072","text":"Bajo la queja hay un interés. Nómbralo.","sound":"j","difficulty":2,"source":"original","hint":"j en queja. Una frase de negociación.","free":true},{"id":"es-j-073","text":"El mensaje viaja mejor si el ejemplo es concreto.","sound":"j","difficulty":3,"source":"original","hint":"j en viaja y mensaje. Una regla para explicar técnica.","free":false},{"id":"es-j-074","text":"No es un juego. Es la caja del turno de noche.","sound":"j","difficulty":3,"source":"original","hint":"j y caja. Planta.","free":false},{"id":"es-j-075","text":"Ojo al lujo de las palabras. Quédate con el verbo.","sound":"j","difficulty":2,"source":"original","hint":"j. ojo, lujo.","free":false},{"id":"es-j-076","text":"El reloj de la junta marcó el momento de elegir.","sound":"j","difficulty":4,"source":"original","hint":"j. reloj, junta, elegir.","free":false},{"id":"es-j-077","text":"Trabaja el gesto, no la queja. La queja no asigna dueño.","sound":"j","difficulty":3,"source":"original","hint":"j y queja. Una corrección de reuniones.","free":false},{"id":"es-j-078","text":"La aguja del flujo marcó el cuello de botella.","sound":"j","difficulty":4,"source":"original","hint":"Una imagen de proceso. aguja, flujo, cuello.","free":false},{"id":"es-j-079","text":"Dije que lo haría. Lo hice. Lo dije otra vez, breve.","sound":"j","difficulty":2,"source":"original","hint":"Credibilidad en tres frases. j en dije.","free":false},{"id":"es-j-080","text":"El jefe de jornada exigió el registro, no el relato largo.","sound":"j","difficulty":5,"source":"original","hint":"j repetida con intención de informe.","free":false},{"id":"es-j-081","text":"Lejos del ruido, la frase mejora. Acércate al micrófono, no al grito.","sound":"j","difficulty":3,"source":"original","hint":"lejos, mejora. Proyección sin forzar.","free":false},{"id":"es-j-082","text":"Un ejemplo vale más que un adjetivo.","sound":"j","difficulty":2,"source":"original","hint":"j en ejemplo. La frase es el método.","free":true},{"id":"es-j-083","text":"La caja, el eje y el engranaje. Tres nombres, tres golpes.","sound":"j","difficulty":4,"source":"original","hint":"Vocabulario de mantenimiento, articulado.","free":false},{"id":"es-ñ-084","text":"El niño señala el tamaño, no el muñeco.","sound":"ñ","difficulty":1,"source":"original","hint":"ñ clara. La lengua al paladar. niño, señala, tamaño, muñeco.","free":true},{"id":"es-ñ-085","text":"De una puñada una puñalada. De una puñalada una puñetera.","sound":"ñ","difficulty":2,"source":"traditional","hint":"Juego tradicional de ñ. Dilo limpio, sin convertir ñ en ni.","free":false},{"id":"es-ñ-086","text":"Acompaño el dato con el significado, y paro.","sound":"ñ","difficulty":2,"source":"original","hint":"ñ en acompaño. Una frase de storytelling con datos.","free":true},{"id":"es-ñ-087","text":"El diseño falló en el detalle pequeño, no en la campaña.","sound":"ñ","difficulty":3,"source":"original","hint":"ñ. diseño, pequeño, campaña.","free":false},{"id":"es-ñ-088","text":"Señora directora, el daño es este, la causa es esta, el arreglo es este.","sound":"ñ","difficulty":3,"source":"original","hint":"señora, daño. Tres estoes, a propósito, para sustituir el rodeo.","free":false},{"id":"es-ñ-089","text":"Enseña el número. No lo escondas en el párrafo.","sound":"ñ","difficulty":2,"source":"original","hint":"ñ en enseña.","free":false},{"id":"es-ñ-090","text":"El compañero del turno de mañana dejó la línea en marcha.","sound":"ñ","difficulty":4,"source":"original","hint":"ñ. compañero, mañana.","free":false},{"id":"es-ñ-091","text":"Una piña de ideas no es una estrategia. Elige una.","sound":"ñ","difficulty":3,"source":"original","hint":"ñ. piña, una.","free":false},{"id":"es-ñ-092","text":"El año que viene no es una fecha. El 12 de marzo sí.","sound":"ñ","difficulty":4,"source":"original","hint":"ñ y la precisión del cierre.","free":false},{"id":"es-ñ-093","text":"Sueña el rumbo en una frase que quepa en el ascensor.","sound":"ñ","difficulty":2,"source":"original","hint":"ñ. sueña. Visión breve.","free":true},{"id":"es-ñ-094","text":"La niña guiñó, el muñeco gruñó y el dueño sonrió.","sound":"ñ","difficulty":5,"source":"original","hint":"ñ en cadena, tradicional en el juego, línea propia.","free":false},{"id":"es-ñ-095","text":"No empeñes la credibilidad por un adorno.","sound":"ñ","difficulty":3,"source":"original","hint":"ñ. empeñes.","free":false},{"id":"es-ñ-096","text":"Señal, dueño, fecha. Otra vez.","sound":"ñ","difficulty":2,"source":"original","hint":"El cierre, con ñ en señal.","free":false},{"id":"es-ñ-097","text":"El diseño del engaño es largo. El diseño de la verdad cabe en treinta segundos.","sound":"ñ","difficulty":4,"source":"original","hint":"ñ y una idea de presencia.","free":false},{"id":"es-vowels-098","text":"La idea es una. El ruido son diez.","sound":"vowels","difficulty":1,"source":"original","hint":"Vocales abiertas. idea, una, ruido.","free":true},{"id":"es-vowels-099","text":"Yo no lo sé. Lo sabré el viernes.","sound":"vowels","difficulty":2,"source":"original","hint":"La frase honesta. Vocales sin muletilla detrás.","free":true},{"id":"es-vowels-100","text":"Habla como si la última fila hubiera pagado la vocal.","sound":"vowels","difficulty":2,"source":"original","hint":"Una instrucción de proyección.","free":false},{"id":"es-vowels-101","text":"Acuerdo, oído, hecho.","sound":"vowels","difficulty":3,"source":"original","hint":"Tres diptongos. Tres pausas.","free":false},{"id":"es-vowels-102","text":"Ane abre la reunión. Iker pide el dato. Lucía cierra.","sound":"vowels","difficulty":3,"source":"original","hint":"Los nombres del curso, dichos con calma.","free":false},{"id":"es-vowels-103","text":"No es no. El silencio que sigue también es la frase.","sound":"vowels","difficulty":2,"source":"original","hint":"Vocal o. Una frontera.","free":false},{"id":"es-vowels-104","text":"El audio de tu idea cae si la vocal se esconde.","sound":"vowels","difficulty":4,"source":"original","hint":"audio, idea, cae, vocal.","free":false},{"id":"es-vowels-105","text":"Hoy oigo el objetivo y dejo el adorno.","sound":"vowels","difficulty":3,"source":"original","hint":"oigo, hoy, objetivo.","free":false},{"id":"es-vowels-106","text":"Una frase. Un dueño. Una fecha.","sound":"vowels","difficulty":2,"source":"original","hint":"Vocales y el cierre de reunión.","free":true},{"id":"es-vowels-107","text":"Autora del error, autora del arreglo. Las dos cosas, en voz alta.","sound":"vowels","difficulty":4,"source":"original","hint":"au. Responsabilidad sin teatro.","free":false},{"id":"es-vowels-108","text":"Eu, ou, au. Abre. No masques.","sound":"vowels","difficulty":3,"source":"original","hint":"El ejercicio, dicho como ejercicio.","free":false},{"id":"es-vowels-109","text":"Aún oigo el eco del anuncio y ya urge otra hora.","sound":"vowels","difficulty":5,"source":"original","hint":"Vocales en un titular. aún, oigo, anuncio, urge, hora.","free":false},{"id":"es-vowels-110","text":"Di el nombre de la persona antes que el del problema.","sound":"vowels","difficulty":2,"source":"original","hint":"Una regla humana, con vocales limpias.","free":false},{"id":"es-vowels-111","text":"La pausa es aire, no un fallo.","sound":"vowels","difficulty":3,"source":"original","hint":"Una idea que conviene creer mientras se entrena.","free":false},{"id":"es-r-rr-112","text":"El rumor corre. El reporte, no. Publícalo.","sound":"r/rr","difficulty":3,"source":"original","hint":"r y rr. Una norma de comunicación interna.","free":false},{"id":"es-s-z-c-113","text":"Si no cabe en una servilleta, todavía no es el mensaje.","sound":"s/z/c","difficulty":3,"source":"original","hint":"s y c. Una prueba de claridad.","free":false},{"id":"es-ll-y-114","text":"Lleva la frase hasta el punto. No la dejes en el pasillo.","sound":"ll/y","difficulty":3,"source":"original","hint":"ll. lleva, pasillo.","free":false},{"id":"es-ch-115","text":"Cierra con hecho, dueño y fecha. Otra vez, más lento.","sound":"ch","difficulty":3,"source":"original","hint":"ch. El cierre, repetido a propósito.","free":false},{"id":"es-clusters-116","text":"Prepara la pregunta que temes. La dirás más limpia.","sound":"clusters","difficulty":3,"source":"original","hint":"pr. Una preparación de entrevista y de sala.","free":false},{"id":"es-j-117","text":"El trabajo del líder es elegir, no narrar el camino entero.","sound":"j","difficulty":3,"source":"original","hint":"j. trabajo, elegir.","free":false},{"id":"es-ñ-118","text":"Acompaña cada número de una sola frase de sentido.","sound":"ñ","difficulty":3,"source":"original","hint":"ñ. acompaña. Data storytelling.","free":false},{"id":"es-vowels-119","text":"Hablo para que decidan, no para que me admiren.","sound":"vowels","difficulty":3,"source":"original","hint":"Una frase de presencia. Vocales abiertas, sin prisa.","free":false},{"id":"es-r-rr-120","text":"Ríe el que resume. Se enrolla el que recita.","sound":"r/rr","difficulty":2,"source":"original","hint":"r y rr. Una crítica amable al monólogo.","free":true},{"id":"es-s-z-c-121","text":"La cifra sale al principio. El contexto, después, si lo piden.","sound":"s/z/c","difficulty":2,"source":"original","hint":"s y c. BLUF en español.","free":false},{"id":"es-ñ-122","text":"Mañana no es un plazo. Mañana a las nueve, con nombre, sí.","sound":"ñ","difficulty":2,"source":"original","hint":"ñ. Precisión de cierre.","free":false}]'),h=JSON.parse(`[{"id":"en-p-01","title":"Morning note","level":1,"text":"The line started on time this morning. The night crew left a clear note on the board. We have one open alarm and a spare part on the shelf. I will check the alarm before lunch and send a short result to the team. If the part fits, we close it today. If it does not, we name the owner and the next hour."},{"id":"en-p-02","title":"Gate check","level":1,"text":"Please walk the south gate before the shift change. Look at the lock, the light, and the floor. If you see water, stop and call. If the floor is dry, sign the sheet and move on. Say what you saw in one sentence. A long story helps no one at the gate."},{"id":"en-p-03","title":"Simple ask","level":1,"text":"I need a decision by Thursday at noon. The choice is small. We keep the current plan, or we cut one feature and ship the rest. I recommend we cut the feature. The customer asked for speed, not for more buttons. Tell me yes or no, and I will write it down."},{"id":"en-p-04","title":"Welcome","level":1,"text":"Hello. I am new on this team, and I am glad to be here. For the first week I will listen more than I speak. I want to learn how you hand work from one shift to the next. Please tell me what I should not break. I will bring questions, not surprises."},{"id":"en-p-05","title":"The number","level":1,"text":"Yesterday we lost twenty minutes on line three. The cause was a loose sensor, not the program. The sensor is tight now. We will watch it for two shifts. If it holds, we leave it. If it slips, we change the bracket. That is the whole update."},{"id":"en-p-06","title":"Kind no","level":1,"text":"Thank you for the invitation. I cannot take this on before Friday. I already promised the handover note and the safety walk. I can start Monday, or I can point you to someone who is free tomorrow. Which of those helps you more?"},{"id":"en-p-07","title":"Quiet praise","level":1,"text":"I want to name what I saw in the meeting. You let the other person finish. You asked one clean question. Then you wrote the owner and the date on the board. The room got faster because you got quieter. Please do that again tomorrow."},{"id":"en-p-08","title":"Two paths","level":1,"text":"There are two paths, and both are honest. Path one keeps the date and drops the extra report. Path two keeps the report and moves the date by a week. I prefer path one. The report can follow. The date is what the customer is waiting for."},{"id":"en-p-09","title":"First minute","level":1,"text":"Good morning. Here is the point. The shipment leaves at four if the label is right. It stays if the label is wrong. I need one person on labels and one person on the dock. I will stand at the door at three to check. Questions after that, not before."},{"id":"en-p-10","title":"Break room","level":1,"text":"The coffee is hot and the break is short, so I will be short too. Thank you for covering the late stop. The line is safe. The part we needed is on the way. Eat, then come back to the same station. I will take the first ten minutes of the next hour."},{"id":"en-p-11","title":"Name the person","level":1,"text":"When you hand me a problem, hand me a name as well. Who saw it. Who owns the next step. Who needs to hear the result. A problem without a name sits in the chat and grows. A problem with a name gets a clock. Let us use clocks."},{"id":"en-p-12","title":"Plain words","level":1,"text":"Please say the thing in plain words. Not the long name of the system. Not three letters that only our team knows. Say what stopped, what it costs, and what we do next. If a new person can repeat it, the sentence is ready."},{"id":"en-p-13","title":"Stairs","level":1,"text":"We take the stairs, not the lift, when we walk the floor. It is a small thing. It means we pass the stations and we see the boards. If a light is red, we stop and ask. We do not fix it in the stairwell. We ask the person who stands there."},{"id":"en-p-14","title":"Close of day","level":1,"text":"Before you go, leave three lines. What finished. What is open. What the next person should not touch. Put the time on the note. Sign it. A kind note is a clear note. The night crew should not have to guess what you meant."},{"id":"en-p-15","title":"Shift handover","level":2,"text":"The afternoon shift inherits two jobs and one risk. Job one is the label check on pallet row C. Job two is the call with the supplier at half past four. The risk is the north pump, which ran warm at noon. We did not stop the line. We logged the temperature and agreed to look again at three. If it climbs, stop and call me. If it holds, leave it and say so in the note. Do not carry a warm pump in your head. Put it on the board where the next person can see it without asking."},{"id":"en-p-16","title":"Customer call","level":2,"text":"The customer does not need our internal history. They need the date, the gap, and the remedy. Start with the date we can keep. Then say what will not be in the box. Then say how we will close the gap the following week. Offer one choice, not four. If they push, repeat the date and ask what matters more, the missing piece or the day it arrives. Write their answer before you promise anything new."},{"id":"en-p-17","title":"Feedback, clear","level":2,"text":"Yesterday in the stand-up you spoke over Lena twice. The effect was that her number never reached the board, and we planned the hour without it. I know you were trying to keep us on time. The time was kept, and the fact was lost. Next stand-up, let her finish the sentence, then you can cut the rest of us. I will back you when you do that. If I interrupt, tell me in the room."},{"id":"en-p-18","title":"Change","level":2,"text":"On Monday the report moves from Friday to Wednesday. The reason is simple. The leadership meeting is Thursday, and a Friday report always arrives late to it. You will have less time to polish and more reason to be brief. One page. One chart. Three lines under it. I will read the Wednesday version myself for the first two weeks so the new habit is not a trap."},{"id":"en-p-19","title":"Interview answer","level":2,"text":"Last spring our line stopped for forty minutes because a sensor drifted. I was the engineer on shift. I said what we knew, what we did not, and who was coming. We restarted on a manual check and replaced the sensor the next day. The lesson I kept is this. People trust a clean unknown more than a fast guess. I still write the unknown down before I speak."},{"id":"en-p-20","title":"Salary","level":2,"text":"I am glad we are talking about the role and not only the tasks. The scope you described includes the line, the suppliers, and a weekly report to the director. That is a larger job than the one in the posting. Based on that scope, I am looking for a number in the band we discussed, toward the top. If the band cannot move, I would like to talk about the review date instead."},{"id":"en-p-21","title":"Disagree","level":2,"text":"I see the appeal of shipping on Friday. I do not agree, and I will say why once. The test we skipped is the one that failed last month. If we ship and it fails again, we lose the date and the trust. I recommend Monday, with the test in between. If the room chooses Friday, I will help, and I will log the risk in the note so it is not only mine."},{"id":"en-p-22","title":"Delegate","level":2,"text":"I am asking you to run the supplier call. You know the part better than I do. The aim is a date they will keep, not a date they hope for. Open with what we need and when. Ask what is in their way. Come back with a yes, a no, or a condition. Do not come back with a maybe. I will be in the next room if the call turns."},{"id":"en-p-23","title":"Vision, small","level":2,"text":"In a year this team should be the one that other lines copy, not the one that other lines rescue. That means a board anyone can read, a handover that takes five minutes, and a habit of saying the risk early. We will not get there by working later. We will get there by leaving cleaner work for the person behind us. I will start with my own notes this week."},{"id":"en-p-24","title":"I do not know","level":2,"text":"I do not know the cause yet. I know the line stopped at ten, the alarm was the north gate, and the spare is in the cage. I will be back at half past with a cause or with a clearer unknown. Please do not wait on a guess from me. If you need a decision now, the safe one is to hold the restart."},{"id":"en-p-25","title":"Negotiation","level":2,"text":"You want the lower price, and I want a date I can say out loud. Those are not the same fight. If we hold the date and the quality check, I can move on the price. If the date slips, the price has to stay, because the late fee is already in my number. Tell me which one you are actually buying."},{"id":"en-p-26","title":"Board, short","level":2,"text":"Three points for the board. We are on the date. We are over on one cost, the spare motor. We need a decision on whether to buy it new or wait for the repair. I recommend we buy it. The repair date is a wish. The new motor is a Tuesday. I can take questions on the cost, and I will not guess the rest."},{"id":"en-p-27","title":"Teaching","level":2,"text":"A PLC is the small computer that tells the machines when to move. When it loses a signal, it does what we told it to do in the dark, which is to stop. That stop is not a failure of courage. It is the machine keeping a promise. Our job is to say which promise broke, and how long until we can make it again."},{"id":"en-p-28","title":"Plant director","level":3,"text":"Director, line three stopped at ten fourteen because the PLC lost the signal from the gate sensor. The night bracket had loosened, so the sensor looked at the frame instead of the gate. We did not restart on a bypass. We fixed the bracket, confirmed the signal, and ran a slow first cycle. Lost time was forty two minutes. Scrap was zero. The action is a second clamp on that bracket, owned by maintenance, done before Thursday. I will confirm in the Thursday note, and I will not call it closed until the clamp is on the machine."},{"id":"en-p-29","title":"SCQA pitch","level":3,"text":"The situation is that our best customer now asks for a same week change. The complication is that our plan still assumes a two week freeze. The question is whether we protect the freeze or protect the account. My answer is a narrow door. Changes under a day of work go through. Larger changes wait. The cost is one planner's afternoon, not the whole schedule. If we do nothing, the account will invent its own door, and we will hear about it in a complaint."},{"id":"en-p-30","title":"Difficult conversation","level":3,"text":"I want to talk about the last three handovers. The notes arrived, and they did not say what was unsafe to touch. Yesterday the next shift started a pump that you had isolated, because the note said check the pump and not do not start the pump. I am not questioning your care. I am saying the sentence failed. From tonight the first line of the note is start, stop, or do not touch, and then the reason. I will read tonight's note with you before you leave."},{"id":"en-p-31","title":"Anchoring","level":3,"text":"Before we talk discounts, I want to put our number on the table. The work as scoped is eighty four thousand, payable in three parts, tied to the trial, the install, and the first quiet month. That number assumes your team is on site for the trial. If your team is not available, the number moves up, because we will staff the trial ourselves. I am not opening with a soft number and a hope. Tell me which assumption is wrong, and I will move the number for that reason only."},{"id":"en-p-32","title":"Label the room","level":3,"text":"It sounds like the room is tired of this topic, and also afraid to close it. Both can be true. We have had this slide four times. Each time we leave with a new question and the same owner. I am not blaming the questions. I am saying the fear is that a decision will be blamed on whoever speaks. So I will take the blame in writing. I recommend we stop the pilot. If that is wrong, we will know in two weeks, and I will own that too."},{"id":"en-p-33","title":"STAR, conflict","level":3,"text":"The situation was a Thursday launch review where design and the floor disagreed about a guard. The design said the guard slowed the cycle. The floor said the guard was the only thing between a hand and the press. My task was to get a decision before the shift. I asked each side for the failure they feared, wrote both on the board, and proposed a temporary slower cycle with the guard in place for ten days while design brought a faster guard. The result was no injury, a six day delay, and a guard that is now standard. I would rather explain a delay than a hand."},{"id":"en-p-34","title":"Say no, twice","level":3,"text":"I said no to the extra report last month, and I am saying no again. The reason has not changed. The hour it takes is the hour we use to walk the line. If I give you the report, I will give you a prettier slide and a less safe floor. I can offer a photograph of the board and three numbers, sent on Friday in the same mail as the safety count. I cannot offer a new narrative. If that is not enough, the work belongs with another team, and I will help you ask them."},{"id":"en-p-35","title":"Data, one number","level":3,"text":"The number is eleven. Eleven minutes of unplanned stop per shift, averaged over the last twenty shifts. Before the sensor change it was twenty six. The meaning is that the change paid for itself, and that eleven is still a conversation, not a trophy. The next minute we can actually remove is the restart, which is slow because people wait for permission. The move is a written rule: if the sensor is true and the guard is shut, the lead may restart without a call. I will bring the rule to you on paper, not as a slide."},{"id":"en-p-36","title":"Opening hook","level":3,"text":"At ten fourteen yesterday a gate decided to be a wall. The sensor looked at metal, the PLC kept its promise, and forty people stood still. That is the story. The point is smaller. We already know how to stop. We are less good at starting again. Everything I am about to show you is about the first safe minute after a stop, who owns it, and how we will practise it this month."},{"id":"en-p-37","title":"Vision, three minutes","level":3,"text":"I want this crew to be proud of the silence in the handover, not of the noise in the crisis. Picture a Monday where the board is already true, the spare is already there, and the argument is about a better idea, not about what happened at two in the morning. We get that by three habits. We write the unknown. We name the owner before we leave the room. We praise the person who stopped the line, in public, every time. I will do the third one myself, starting with the stop we had on Tuesday, which was the right stop."},{"id":"en-p-38","title":"Walk away","level":3,"text":"We have been at this for an hour, and the gap is no longer about price. You need a penalty clause we cannot sign, because our insurer will not cover it. I respect the reason you want it. I cannot pretend the clause is a discount. Our alternative is to finish the work we already have and return next quarter with a smaller scope. That is not a threat. It is the other real option. If you can move the clause, I can stay. If you cannot, I should give you the evening back."},{"id":"en-p-39","title":"Chair","level":3,"text":"We have twenty five minutes and three decisions. I will give each decision six minutes, and I will keep the last seven for owners and dates. If a point is interesting and not one of the three, I will write it on the side and we will not chase it today. I need you to help me. If I let us wander, say so. The measure of this meeting is whether we leave with names, not whether everyone spoke."},{"id":"en-p-40","title":"Technical to the board","level":3,"text":"Think of the network on the floor as a set of promises between boxes. One box watches the gate. One box decides. One box moves the arm. Yesterday the watching box lied, so the deciding box did the safe thing and refused to move the arm. We replaced the watcher. We did not need a new brain, and we do not need a new budget line. We need the bracket that keeps the watcher pointed at the gate. That is a hardware problem with a hardware date."},{"id":"en-p-41","title":"Recognition","level":2,"text":"In front of the team I want to say this properly. When the alarm went, you did not reach for a bypass. You called the stop, you pointed at the sensor, and you waited. That choice cost us minutes and saved us a worse afternoon. Thank you. The standard is now yours. If someone is tempted to bypass, they can point at yesterday and at you."},{"id":"en-p-42","title":"Concessions","level":3,"text":"I can give on the payment schedule. I can give on the training day. I cannot give on the acceptance test, because that test is the only proof the line is ours again and not still yours. If we drop the test, we are not negotiating a contract. We are negotiating a hope. Let us trade inside the list I can actually trade, and leave the test where it is."}]`),p=JSON.parse('[{"id":"es-p-01","title":"Nota de la mañana","level":1,"text":"La línea arrancó a su hora. El turno de noche dejó una nota clara en la pizarra. Hay una alarma abierta y un repuesto en la estantería. Miraré la alarma antes de comer y mandaré un resultado corto al equipo. Si la pieza encaja, lo cerramos hoy. Si no encaja, ponemos nombre y hora al siguiente paso."},{"id":"es-p-02","title":"El portón","level":1,"text":"Recorre el portón sur antes del cambio de turno. Mira el cierre, la luz y el suelo. Si ves agua, paras y avisas. Si el suelo está seco, firmas la hoja y sigues. Di lo que viste en una frase. En el portón, un relato largo no ayuda a nadie."},{"id":"es-p-03","title":"Una petición simple","level":1,"text":"Necesito una decisión el jueves antes de las doce. La elección es pequeña. Seguimos con el plan, o quitamos una función y entregamos el resto. Yo quitaría la función. El cliente pidió velocidad, no más botones. Dime que sí o que no, y lo dejo escrito."},{"id":"es-p-04","title":"Llegada","level":1,"text":"Hola. Soy nueva en este equipo y me alegra estar aquí. La primera semana voy a escuchar más de lo que hablo. Quiero entender cómo pasáis el trabajo de un turno a otro. Decidme qué no debo romper. Traeré preguntas, no sorpresas."},{"id":"es-p-05","title":"La cifra","level":1,"text":"Ayer perdimos veinte minutos en la línea tres. La causa fue un sensor flojo, no el programa. El sensor ya está firme. Lo vigilaremos dos turnos. Si aguanta, lo dejamos. Si se suelta, cambiamos el soporte. Ese es todo el parte."},{"id":"es-p-06","title":"Un no amable","level":1,"text":"Gracias por la invitación. No puedo coger esto antes del viernes. Ya prometí la nota de relevo y la ronda de seguridad. Puedo empezar el lunes, o señalar a alguien que está libre mañana. ¿Cuál de las dos cosas te sirve más?"},{"id":"es-p-07","title":"Un elogio quieto","level":1,"text":"Quiero nombrar lo que vi en la reunión. Dejaste terminar a la otra persona. Hiciste una pregunta limpia. Luego escribiste en la pizarra el dueño y la fecha. La sala fue más rápida porque tú fuiste más quieta. Hazlo otra vez mañana."},{"id":"es-p-08","title":"Dos caminos","level":1,"text":"Hay dos caminos, y los dos son honestos. El primero mantiene la fecha y quita el informe extra. El segundo mantiene el informe y mueve la fecha una semana. Prefiero el primero. El informe puede ir detrás. La fecha es lo que el cliente está esperando."},{"id":"es-p-09","title":"El primer minuto","level":1,"text":"Buenos días. Aquí está el punto. El envío sale a las cuatro si la etiqueta es correcta. Se queda si la etiqueta está mal. Necesito una persona en etiquetas y otra en el muelle. Yo estaré en la puerta a las tres para revisar. Las preguntas, después, no antes."},{"id":"es-p-10","title":"El descanso","level":1,"text":"El café está caliente y el descanso es corto, así que yo también seré breve. Gracias por cubrir la parada tardía. La línea está segura. La pieza que faltaba está de camino. Comed y volved al mismo puesto. Yo cubro los primeros diez minutos de la hora que viene."},{"id":"es-p-11","title":"Ponle nombre","level":1,"text":"Cuando me pases un problema, pásame también un nombre. Quién lo vio. Quién se queda el siguiente paso. Quién tiene que oír el resultado. Un problema sin nombre se queda en el chat y crece. Un problema con nombre tiene reloj. Usemos relojes."},{"id":"es-p-12","title":"Palabras llanas","level":1,"text":"Di la cosa con palabras llanas. No el nombre largo del sistema. No tres siglas que solo entiende nuestro equipo. Di qué se paró, qué cuesta y qué hacemos ahora. Si una persona nueva puede repetirlo, la frase está lista."},{"id":"es-p-13","title":"Las escaleras","level":1,"text":"Subimos por la escalera, no por el ascensor, cuando recorremos la planta. Es una cosa pequeña. Así pasamos por los puestos y vemos las pizarras. Si una luz está en rojo, paramos y preguntamos. No lo arreglamos en la escalera. Le preguntamos a quien está ahí."},{"id":"es-p-14","title":"El cierre del día","level":1,"text":"Antes de irte, deja tres líneas. Qué terminó. Qué sigue abierto. Qué no debe tocar la persona que viene. Pon la hora en la nota. Fírmala. Una nota amable es una nota clara. El turno de noche no debería adivinar lo que quisiste decir."},{"id":"es-p-15","title":"Relevo","level":2,"text":"El turno de tarde hereda dos tareas y un riesgo. La primera es la revisión de etiquetas en la fila C. La segunda es la llamada con el proveedor a las cuatro y media. El riesgo es la bomba norte, que fue tibia al mediodía. No paramos la línea. Anotamos la temperatura y quedamos en mirarla a las tres. Si sube, paras y me llamas. Si aguanta, la dejas y lo dices en la nota. No te lleves una bomba tibia en la cabeza. Ponla en la pizarra, donde la siguiente persona la vea sin preguntar."},{"id":"es-p-16","title":"Llamada con el cliente","level":2,"text":"Al cliente no le hace falta nuestra historia interna. Le hace falta la fecha, el hueco y el remedio. Empieza por la fecha que sí podemos cumplir. Luego di qué no irá en la caja. Luego di cómo cerramos el hueco la semana siguiente. Ofrece una opción, no cuatro. Si empuja, repite la fecha y pregunta qué le importa más, la pieza que falta o el día en que llega. Escribe su respuesta antes de prometer nada nuevo."},{"id":"es-p-17","title":"Feedback claro","level":2,"text":"Ayer en el stand-up hablaste por encima de Lena dos veces. El efecto fue que su cifra no llegó a la pizarra, y planeamos la hora sin ella. Sé que intentabas mantener el tiempo. El tiempo se mantuvo, y el dato se perdió. En el próximo stand-up, deja que termine la frase, y luego ya puedes cortarnos a los demás. Yo te apoyaré cuando lo hagas. Si te interrumpo yo, dímelo en la sala."},{"id":"es-p-18","title":"El cambio","level":2,"text":"El lunes el informe pasa del viernes al miércoles. La razón es simple. La reunión de dirección es el jueves, y un informe del viernes siempre llega tarde. Tendréis menos tiempo para pulir y más motivos para ser breves. Una página. Un gráfico. Tres líneas debajo. Yo leeré la versión del miércoles las dos primeras semanas, para que el hábito nuevo no sea una trampa."},{"id":"es-p-19","title":"Respuesta de entrevista","level":2,"text":"La primavera pasada la línea se paró cuarenta minutos porque un sensor se desvió. Yo era la ingeniera de turno. Dije lo que sabíamos, lo que no sabíamos y quién venía. Rearrancamos con una comprobación manual y cambiamos el sensor al día siguiente. La lección que guardé es esta. La gente fía más un desconocido limpio que una adivinanza rápida. Sigo escribiendo lo que no sé antes de hablar."},{"id":"es-p-20","title":"El salario","level":2,"text":"Me alegra que hablemos del puesto y no solo de las tareas. El alcance que describes incluye la línea, los proveedores y un informe semanal a dirección. Es un trabajo más grande que el del anuncio. Con ese alcance, busco una cifra en la banda que comentamos, hacia arriba. Si la banda no se mueve, preferiría hablar de la fecha de revisión."},{"id":"es-p-21","title":"Disentir","level":2,"text":"Veo el atractivo de entregar el viernes. No estoy de acuerdo, y lo diré una vez. La prueba que nos saltamos es la que falló el mes pasado. Si entregamos y vuelve a fallar, perdemos la fecha y la confianza. Recomiendo el lunes, con la prueba en medio. Si la sala elige el viernes, ayudaré, y dejaré el riesgo escrito en la nota para que no sea solo mío."},{"id":"es-p-22","title":"Delegar","level":2,"text":"Te pido que lleves la llamada con el proveedor. Conoces la pieza mejor que yo. El objetivo es una fecha que puedan cumplir, no una fecha que esperan. Abre con lo que necesitamos y para cuándo. Pregunta qué se les interpone. Vuelve con un sí, un no o una condición. No vuelvas con un quizá. Estaré en la sala de al lado si la llamada se tuerce."},{"id":"es-p-23","title":"Visión breve","level":2,"text":"Dentro de un año este equipo debería ser el que las otras líneas copian, no el que las otras líneas rescatan. Eso significa una pizarra que cualquiera lee, un relevo de cinco minutos y el hábito de decir el riesgo pronto. No llegaremos trabajando más tarde. Llegaremos dejando un trabajo más limpio a quien viene detrás. Empiezo esta semana por mis propias notas."},{"id":"es-p-24","title":"No lo sé","level":2,"text":"Todavía no sé la causa. Sé que la línea paró a las diez, que la alarma fue el portón norte y que el repuesto está en la jaula. Volveré a las diez y media con una causa o con un desconocido más claro. No esperéis una adivinanza mía. Si hace falta una decisión ahora, la segura es no rearrancar."},{"id":"es-p-25","title":"Negociación","level":2,"text":"Tú quieres el precio más bajo, y yo quiero una fecha que pueda decir en voz alta. No es la misma pelea. Si mantenemos la fecha y el control de calidad, puedo mover el precio. Si la fecha se escurre, el precio se queda, porque la penalización por retraso ya está en mi cifra. Dime cuál de las dos cosas estás comprando de verdad."},{"id":"es-p-26","title":"Al comité, breve","level":2,"text":"Tres puntos para el comité. Vamos en fecha. Vamos por encima en un coste, el motor de repuesto. Hace falta decidir si lo compramos nuevo o esperamos a la reparación. Recomiendo comprarlo. La fecha de la reparación es un deseo. El motor nuevo es un martes. Puedo responder por el coste, y no voy a adivinar el resto."},{"id":"es-p-27","title":"Enseñar","level":2,"text":"Un PLC es el ordenador pequeño que le dice a las máquinas cuándo moverse. Cuando pierde una señal, hace lo que le dijimos que hiciera a oscuras, que es parar. Esa parada no es una falta de valor. Es la máquina cumpliendo una promesa. Nuestro trabajo es decir qué promesa se rompió, y cuánto falta para poder hacerla otra vez."},{"id":"es-p-28","title":"Dirección de planta","level":3,"text":"Director, la línea tres paró a las diez y catorce porque el PLC perdió la señal del sensor del portón. El soporte de la noche se había aflojado, y el sensor miraba el marco en vez del portón. No rearrancamos con un puente. Arreglamos el soporte, confirmamos la señal e hicimos un primer ciclo lento. El tiempo perdido fue de cuarenta y dos minutos. La chatarra fue cero. La acción es una segunda brida en ese soporte, a cargo de mantenimiento, hecha antes del jueves. Lo confirmaré en la nota del jueves, y no lo daré por cerrado hasta que la brida esté en la máquina."},{"id":"es-p-29","title":"Pitch SCQA","level":3,"text":"La situación es que nuestro mejor cliente ahora pide un cambio en la misma semana. La complicación es que nuestro plan sigue suponiendo dos semanas de congelación. La pregunta es si protegemos la congelación o protegemos la cuenta. Mi respuesta es una puerta estrecha. Los cambios de menos de un día de trabajo pasan. Los grandes esperan. El coste es una tarde de una persona de planificación, no todo el calendario. Si no hacemos nada, la cuenta se inventará su propia puerta, y nos enteraremos por una queja."},{"id":"es-p-30","title":"Conversación difícil","level":3,"text":"Quiero hablar de los tres últimos relevos. Las notas llegaron, y no decían qué era peligroso tocar. Ayer el turno siguiente arrancó una bomba que tú habías aislado, porque la nota decía revisar la bomba y no decía no arrancar la bomba. No discuto tu cuidado. Digo que la frase falló. Desde esta noche, la primera línea de la nota es arrancar, parar o no tocar, y luego la razón. Leeré contigo la nota de esta noche antes de que te vayas."},{"id":"es-p-31","title":"Ancla","level":3,"text":"Antes de hablar de descuentos, quiero poner nuestra cifra en la mesa. El trabajo, con este alcance, son ochenta y cuatro mil, en tres pagos, atados a la prueba, a la instalación y al primer mes tranquilo. Esa cifra supone que vuestro equipo está en la planta durante la prueba. Si no está, la cifra sube, porque cubriremos la prueba nosotros. No abro con un número blando y una esperanza. Dime qué supuesto está mal, y moveré la cifra solo por esa razón."},{"id":"es-p-32","title":"Etiquetar la sala","level":3,"text":"Parece que la sala está cansada de este tema y, a la vez, tiene miedo de cerrarlo. Las dos cosas pueden ser verdad. Hemos visto esta diapositiva cuatro veces. Cada vez salimos con una pregunta nueva y el mismo dueño. No culpo a las preguntas. Digo que el miedo es que la decisión se le eche encima a quien hable. Así que la culpa escrita me la quedo yo. Recomiendo parar el piloto. Si nos equivocamos, lo sabremos en dos semanas, y también eso será mío."},{"id":"es-p-33","title":"STAR, un conflicto","level":3,"text":"La situación fue una revisión de lanzamiento, un jueves, en la que diseño y planta no estaban de acuerdo con una protección. Diseño decía que la protección frenaba el ciclo. Planta decía que era lo único entre una mano y la prensa. Mi tarea era conseguir una decisión antes del turno. Pedí a cada parte el fallo que temía, escribí los dos en la pizarra y propuse un ciclo más lento, con la protección puesta, durante diez días, mientras diseño traía una protección más rápida. El resultado fue ningún daño, seis días de retraso y una protección que ahora es la norma. Prefiero explicar un retraso que una mano."},{"id":"es-p-34","title":"Decir que no, otra vez","level":3,"text":"Dije que no al informe extra el mes pasado, y vuelvo a decir que no. La razón no ha cambiado. La hora que cuesta es la hora que usamos para recorrer la línea. Si te doy el informe, te daré una diapositiva más bonita y una planta menos segura. Puedo ofrecerte una foto de la pizarra y tres cifras, el viernes, en el mismo correo que el recuento de seguridad. No puedo ofrecer un relato nuevo. Si eso no basta, el trabajo es de otro equipo, y te ayudo a pedírselo."},{"id":"es-p-35","title":"Un solo número","level":3,"text":"La cifra es once. Once minutos de parada no prevista por turno, de media, en los últimos veinte turnos. Antes del cambio de sensor eran veintiséis. El sentido es que el cambio ya se pagó, y que once sigue siendo una conversación, no un trofeo. El minuto que de verdad podemos quitar es el rearranque, que es lento porque la gente espera permiso. El paso es una regla escrita: si el sensor es verdadero y la protección está cerrada, el responsable puede rearrancar sin llamar. Traeré la regla en papel, no en una diapositiva."},{"id":"es-p-36","title":"Gancho","level":3,"text":"A las diez y catorce de ayer un portón decidió ser una pared. El sensor miró el metal, el PLC cumplió su promesa y cuarenta personas se quedaron quietas. Esa es la historia. El punto es más pequeño. Ya sabemos parar. Se nos da peor volver a arrancar. Todo lo que voy a enseñar trata del primer minuto seguro después de una parada, de quién lo posee y de cómo lo vamos a practicar este mes."},{"id":"es-p-37","title":"Visión de tres minutos","level":3,"text":"Quiero que este equipo esté orgulloso del silencio del relevo, no del ruido de la crisis. Imaginad un lunes en el que la pizarra ya es verdad, el repuesto ya está y la discusión es sobre una idea mejor, no sobre lo que pasó a las dos de la mañana. Se llega con tres hábitos. Escribimos lo que no sabemos. Ponemos dueño antes de salir de la sala. Elogiamos en público, cada vez, a quien paró la línea. El tercero lo haré yo, empezando por la parada del martes, que fue la parada correcta."},{"id":"es-p-38","title":"Levantarse de la mesa","level":3,"text":"Llevamos una hora, y la distancia ya no es el precio. Necesitáis una cláusula de penalización que no podemos firmar, porque nuestro seguro no la cubre. Respeto la razón por la que la queréis. No puedo fingir que la cláusula es un descuento. La alternativa es terminar el trabajo que ya tenemos y volver el trimestre que viene con un alcance más pequeño. No es una amenaza. Es la otra opción real. Si podéis mover la cláusula, me quedo. Si no podéis, os devuelvo la tarde."},{"id":"es-p-39","title":"Quien preside","level":3,"text":"Tenemos veinticinco minutos y tres decisiones. Daré seis minutos a cada decisión, y guardaré los últimos siete para dueños y fechas. Si un punto es interesante y no es una de las tres, lo apunto al margen y hoy no lo perseguimos. Necesito que me ayudéis. Si dejo que nos dispersemos, decídmelo. Esta reunión sale bien si nos vamos con nombres, no si habló todo el mundo."},{"id":"es-p-40","title":"Lo técnico, al comité","level":3,"text":"Pensad en la red de la planta como un conjunto de promesas entre cajas. Una caja mira el portón. Otra decide. Otra mueve el brazo. Ayer la caja que mira mintió, así que la que decide hizo lo seguro y se negó a mover el brazo. Cambiamos a quien mira. No hacía falta un cerebro nuevo, ni una línea nueva de presupuesto. Hace falta el soporte que mantiene al sensor mirando al portón. Es un problema de ferretería con fecha de ferretería."},{"id":"es-p-41","title":"Reconocimiento","level":2,"text":"Delante del equipo quiero decirlo bien. Cuando sonó la alarma, no fuiste a un puente. Llamaste la parada, señalaste el sensor y esperaste. Esa elección nos costó minutos y nos ahorró una tarde peor. Gracias. El estándar ahora es el tuyo. Si alguien tiene la tentación del puente, puede señalar el día de ayer y señalarte a ti."},{"id":"es-p-42","title":"Concesiones","level":3,"text":"Puedo ceder en el calendario de pagos. Puedo ceder en el día de formación. No puedo ceder en la prueba de aceptación, porque esa prueba es la única demostración de que la línea vuelve a ser nuestra y no sigue siendo vuestra. Si quitamos la prueba, no estamos negociando un contrato. Estamos negociando una esperanza. Intercambiemos dentro de la lista que de verdad puedo intercambiar, y dejemos la prueba donde está."}]'),m=JSON.parse(`[{"id":"en-w-breath","title":"Box breath","focus":"breath","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"Settle","seconds":20,"cue":"Feet on the floor","how":"Sit tall. Drop the shoulders. Let the belly soften."},{"title":"Box of four","seconds":48,"cue":"4 in, 4 hold, 4 out","how":"Three quiet boxes. The hold is empty, not a grip."},{"title":"Speak on the out","seconds":30,"cue":"One sentence, one breath","how":"Say: The point is simple. Finish before the air does."},{"title":"Release","seconds":20,"cue":"Jaw heavy","how":"Lips together, teeth apart. Hum once, then stop."}]},{"id":"en-w-lips","title":"Lip trills","focus":"clarity","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"Loose lips","seconds":20,"cue":"No smile yet","how":"Blow air until the lips flutter. If they lock, slower air."},{"title":"Glide","seconds":30,"cue":"Low to high","how":"Trill a small siren. Keep the jaw still."},{"title":"Words on the trill","seconds":25,"cue":"Today we start","how":"Trill the rhythm of the phrase, then say it."},{"title":"Clean repeat","seconds":25,"cue":"Normal voice","how":"Say the phrase once, consonants light and finished."}]},{"id":"en-w-hum","title":"Hum and face","focus":"volume","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"Hum","seconds":25,"cue":"Feel the lips buzz","how":"Mmm on a comfortable note. Cheeks soft."},{"title":"Ng to ah","seconds":25,"cue":"Hung-ah","how":"Start in the nose, open to ah without a push."},{"title":"Call the room","seconds":30,"cue":"As if to the back row","how":"Say: Here is the update. No shout. Just aim."},{"title":"Quiet check","seconds":15,"cue":"Same line, half volume","how":"The shape stays. Only the air changes."}]},{"id":"en-w-straw","title":"Straw phonation","focus":"breath","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"Straw or imagined straw","seconds":20,"cue":"5 mm if you have one","how":"A coffee straw is enough. No straw: round the lips."},{"title":"Easy bubbles","seconds":40,"cue":"Three notes","how":"Phonate through the straw. Stop if the throat grips."},{"title":"Siren in the straw","seconds":30,"cue":"Small range","how":"Glide a fifth, not an octave. Three times."},{"title":"Speak after","seconds":25,"cue":"The voice should feel cheaper","how":"Say a sentence. Less push, same clarity."}]},{"id":"en-w-siren","title":"Pitch sirens","focus":"pitch","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"Ng siren","seconds":25,"cue":"Tiny range","how":"Glide up and down on ng. Stay where it is easy."},{"title":"Ooh siren","seconds":25,"cue":"A little wider","how":"Round lips. Do not chase a high note."},{"title":"Three pitches","seconds":30,"cue":"Low, mid, high on one word","how":"Say ready on three notes. The word stays clear."},{"title":"Statement, not a question","seconds":20,"cue":"Fall at the end","how":"Say: We start on Monday. The pitch lands."}]},{"id":"en-w-jaw","title":"Jaw and tongue","focus":"clarity","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"Jaw release","seconds":20,"cue":"Teeth apart","how":"Small circles. Stop at any click or pain."},{"title":"Tongue bow","seconds":20,"cue":"Alveolar ridge","how":"Tap t-t-t, then d-d-d, slow."},{"title":"Corners","seconds":20,"cue":"ee then oo","how":"Stretch the lips, then round them. Five pairs."},{"title":"A real sentence","seconds":30,"cue":"Over-articulate once","how":"Say: The decision is the first sentence. Then say it normally."}]},{"id":"en-w-pace","title":"Pace ladder","focus":"pace","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"Slow","seconds":25,"cue":"Half speed","how":"Read: First the fact. Then the meaning. Then the move."},{"title":"Band","seconds":25,"cue":"Conversational","how":"Same line, as if to a colleague. Not a race."},{"title":"Pause","seconds":20,"cue":"One beat of silence","how":"Put a real pause after fact, and after meaning."},{"title":"Fast and still clear","seconds":20,"cue":"Only if the words survive","how":"If a word smears, drop back to the band."}]},{"id":"en-w-pause","title":"Pause, don't fill","focus":"pauses","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"Notice the um","seconds":15,"cue":"Where you usually hide","how":"Think of the spot you say so or um."},{"title":"Replace with air","seconds":30,"cue":"Two beats","how":"Say a sentence. At the join, close your mouth and count two."},{"title":"Three lines","seconds":30,"cue":"Point. Reason. Ask.","how":"Pause between them. Do not bridge with okay so."},{"title":"Keep one","seconds":15,"cue":"The pause you will use today","how":"Mark it. You will need it in the scenario."}]},{"id":"en-w-volume","title":"Last-word energy","focus":"volume","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"Middle volume","seconds":20,"cue":"A calm room","how":"Say: The number is forty. Even from start to end."},{"title":"No trail-off","seconds":25,"cue":"The last word matches the first","how":"Repeat. Do not fade on forty."},{"title":"A notch more","seconds":20,"cue":"Back row","how":"Same sentence, aimed farther, not higher in pitch."},{"title":"Return","seconds":15,"cue":"Colleague volume","how":"Find the level you can hold for a minute."}]},{"id":"en-w-consonant","title":"Consonant edges","focus":"clarity","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"P and B","seconds":20,"cue":"A small pop","how":"Pay, bay, pay, bay. Lips meet and release."},{"title":"T and D","seconds":20,"cue":"Tongue tip","how":"Tie, die, tie, die. No jaw jab."},{"title":"S and SH","seconds":20,"cue":"Air only","how":"Sea, she, sea, she. Smile, then round."},{"title":"A status line","seconds":25,"cue":"Finish every consonant","how":"The fix ships Friday. Hear the p, the f, the day."}]},{"id":"en-w-presence","title":"First thirty seconds","focus":"presence","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"Arrive","seconds":15,"cue":"Before you speak","how":"Feet, breath, look up from the notes."},{"title":"Name the point","seconds":25,"cue":"One sentence","how":"Say the headline you wish you had said last time."},{"title":"Stop","seconds":10,"cue":"Two beats","how":"Let it land. Do not apologise for it."},{"title":"The ask","seconds":20,"cue":"One verb","how":"Say what you want them to do, and by when."}]},{"id":"en-w-reset","title":"Between meetings","focus":"breath","minutes":2,"safety":"Stop if anything hurts. This is a warm-up, not a treatment. Skip it with jaw pain, TMJ, or recent dental work.","steps":[{"title":"Stand or sit tall","seconds":15,"cue":"Uncross","how":"One breath out, longer than the breath in."},{"title":"Hum a fifth","seconds":20,"cue":"Quiet","how":"Nobody in the corridor needs to hear it."},{"title":"Shake the jaw","seconds":15,"cue":"Gentle","how":"Then still."},{"title":"One line","seconds":20,"cue":"For the next room","how":"I will start with the decision."}]}]`),f=JSON.parse('[{"id":"es-w-breath","title":"Respiración en caja","focus":"breath","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"Apoya","seconds":20,"cue":"Pies en el suelo","how":"Siéntate alto. Hombros sueltos. Barriga blanda."},{"title":"Caja de cuatro","seconds":48,"cue":"4 entra, 4 sostén, 4 sale","how":"Tres cajas quietas. El sostén no es un apretón."},{"title":"Habla al salir","seconds":30,"cue":"Una frase, un aire","how":"Di: El punto es simple. Termina antes de que se acabe el aire."},{"title":"Suelta","seconds":20,"cue":"Mandíbula pesada","how":"Labios juntos, dientes separados. Un zumbido y paras."}]},{"id":"es-w-lips","title":"Labios","focus":"clarity","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"Labios flojos","seconds":20,"cue":"Sin sonrisa todavía","how":"Sopla hasta que vibren. Si se traban, menos aire."},{"title":"Glissando","seconds":30,"cue":"De grave a agudo","how":"Una sirena pequeña. La mandíbula quieta."},{"title":"La frase en el trino","seconds":25,"cue":"Hoy empezamos","how":"Marca el ritmo y después di la frase."},{"title":"Limpio","seconds":25,"cue":"Voz normal","how":"Una vez, consonantes terminadas."}]},{"id":"es-w-hum","title":"Zumbido y cara","focus":"volume","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"Zumbar","seconds":25,"cue":"Los labios vibran","how":"Mmm en una nota cómoda."},{"title":"De ng a a","seconds":25,"cue":"Abre sin empujar","how":"Empieza en la nariz y abre a una a."},{"title":"Llama a la sala","seconds":30,"cue":"Como a la última fila","how":"Di: Aquí está el parte. Sin grito. Con puntería."},{"title":"Baja","seconds":15,"cue":"La misma frase, a media voz","how":"Cambia el aire, no la forma."}]},{"id":"es-w-straw","title":"Fonación con pajita","focus":"breath","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"Pajita de unos 5 mm","seconds":20,"cue":"Si no hay, redondea los labios","how":"Una pajita de café basta."},{"title":"Burbuja fácil","seconds":40,"cue":"Tres notas","how":"Fonación a través de la pajita. Para si la garganta aprieta."},{"title":"Sirena corta","seconds":30,"cue":"Una quinta, no una octava","how":"Tres veces."},{"title":"Habla después","seconds":25,"cue":"La voz debería costar menos","how":"Di una frase. Menos empuje, la misma claridad."}]},{"id":"es-w-siren","title":"Sirenas de tono","focus":"pitch","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"Sirena en ng","seconds":25,"cue":"Poca cuerda","how":"Sube y baja donde sea fácil."},{"title":"Sirena en u","seconds":25,"cue":"Un poco más","how":"Labios redondos. No persigas el agudo."},{"title":"Tres tonos","seconds":30,"cue":"Grave, medio, agudo","how":"Di listo en tres notas. La palabra sigue clara."},{"title":"Afirmación","seconds":20,"cue":"El tono cae al final","how":"Di: Empezamos el lunes. El tono aterriza."}]},{"id":"es-w-jaw","title":"Mandíbula y lengua","focus":"clarity","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"Suelta la mandíbula","seconds":20,"cue":"Dientes separados","how":"Círculos pequeños. Para si hay chasquido o dolor."},{"title":"Lengua","seconds":20,"cue":"Detrás de los dientes","how":"Ta-ta-ta, luego da-da-da, lento."},{"title":"Esquinas","seconds":20,"cue":"i y luego u","how":"Estira y redondea. Cinco pares."},{"title":"Una frase real","seconds":30,"cue":"Exagera una vez","how":"Di: La decisión es la primera frase. Luego, normal."}]},{"id":"es-w-pace","title":"Escalera de ritmo","focus":"pace","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"Lento","seconds":25,"cue":"A media velocidad","how":"Lee: Primero el hecho. Luego el sentido. Luego el paso."},{"title":"Banda","seconds":25,"cue":"Como a un colega","how":"La misma línea. No es una carrera."},{"title":"Pausa","seconds":20,"cue":"Un tiempo de silencio","how":"Pausa de verdad después de hecho y de sentido."},{"title":"Rápido y claro","seconds":20,"cue":"Solo si las palabras viven","how":"Si una se embarra, vuelve a la banda."}]},{"id":"es-w-pause","title":"Pausa, no muletilla","focus":"pauses","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"Dónde te escondes","seconds":15,"cue":"El este, el pues, el o sea","how":"Localiza el sitio."},{"title":"Cámbialo por aire","seconds":30,"cue":"Dos tiempos","how":"En el empalme, cierra la boca y cuenta dos."},{"title":"Tres líneas","seconds":30,"cue":"Punto. Razón. Petición.","how":"Pausa entre ellas. No pongas un vale en medio."},{"title":"Quédate una","seconds":15,"cue":"La pausa de hoy","how":"La vas a usar en el escenario."}]},{"id":"es-w-volume","title":"La última palabra","focus":"volume","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"Volumen medio","seconds":20,"cue":"Sala tranquila","how":"Di: La cifra es cuarenta. Igual de principio a fin."},{"title":"Sin caída","seconds":25,"cue":"La última vale como la primera","how":"No apagues cuarenta."},{"title":"Un punto más","seconds":20,"cue":"Última fila","how":"La misma frase, más lejos, no más aguda."},{"title":"Vuelve","seconds":15,"cue":"Volumen de colega","how":"El nivel que aguantas un minuto."}]},{"id":"es-w-consonant","title":"Bordes","focus":"clarity","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"P y B","seconds":20,"cue":"Un golpe pequeño","how":"Paz, vas, paz, vas. Los labios se encuentran y sueltan."},{"title":"T y D","seconds":20,"cue":"Punta de la lengua","how":"Ta, da, ta, da. Sin lanzar la mandíbula."},{"title":"S y suave","seconds":20,"cue":"Solo aire","how":"Si distingues c y z, márcalas. Si seseas, igual de limpias."},{"title":"Un parte","seconds":25,"cue":"Termina cada consonante","how":"El arreglo sale el viernes. Se oye el fin de cada palabra."}]},{"id":"es-w-presence","title":"Los primeros treinta","focus":"presence","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"Llega","seconds":15,"cue":"Antes de hablar","how":"Pies, aire, ojos fuera del papel."},{"title":"Di el punto","seconds":25,"cue":"Una frase","how":"El titular que te habría gustado decir la vez pasada."},{"title":"Calla","seconds":10,"cue":"Dos tiempos","how":"Deja que caiga. No pidas perdón por haberlo dicho."},{"title":"La petición","seconds":20,"cue":"Un verbo","how":"Qué quieres que hagan, y para cuándo."}]},{"id":"es-w-reset","title":"Entre reuniones","focus":"breath","minutes":2,"safety":"Para si algo duele. Es un calentamiento, no un tratamiento. Sáltalo si tienes dolor de mandíbula, ATM o un arreglo dental reciente.","steps":[{"title":"Alto","seconds":15,"cue":"Descruza","how":"Una salida de aire más larga que la entrada."},{"title":"Una quinta en voz baja","seconds":20,"cue":"Que no salga al pasillo","how":"Zumbar basta."},{"title":"Suelta la mandíbula","seconds":15,"cue":"Suave","how":"Y quietud."},{"title":"Una línea","seconds":20,"cue":"Para la sala que viene","how":"Voy a empezar por la decisión."}]}]'),y=[{id:1,title:"Voice foundations",blurb:"Breath, resonance, articulation, pace, pitch, and a voice that still holds at the last meeting of the day."},{id:2,title:"Executive presence",blurb:"Finish the point, hold a silence, and let your face and your sentence agree, including on camera."},{id:3,title:"Clear messages",blurb:"BLUF, SCQA, PREP, and the rule of three, plus plain words for a technical fault and a chart that needs a decision."},{id:4,title:"Storytelling",blurb:"A work story with a stake and a turn, a hero who did the work, and a future scene someone can picture on a Tuesday."},{id:5,title:"Meetings",blurb:"A short stand-up, a chair who keeps the clock, a dissent said once, a pause that lets someone in, and a close with a name and a date."},{id:6,title:"Feedback",blurb:"Specific praise, a clean correction, the skill of hearing a hard note, and a difficult conversation opened while it can still change the work."},{id:7,title:"Influence",blurb:"The need under the demand, a real alternative, a number you can defend, a label that lowers the heat, and a no that leaves a path."}],w=JSON.parse(`[{"id":"m1-breath","module":1,"title":"Breath support","minutes":4,"framework":"Breath support","promise":"You will land the date and the ask on a full breath, with the last word as clear as the first.","focus":"breath","free":true,"cards":[{"kicker":"Why it matters","body":"The date, the name, and the no tend to sit at the end of the sentence, which is where a shallow breath gives out. A faded ending sounds like doubt even when the decision is sound. Support is a work skill, the same kind of skill as a clear agenda."},{"kicker":"Do this","body":"Keep the shoulders still and let the breath drop so the lower ribs widen. Spend that air on one idea, then take another breath on purpose before the next idea. Start the sentence as the air leaves, rather than after you have already begun to fade."},{"kicker":"In the room","body":"Mark a slash in your notes just before the figure, and breathe there. Say the verb and the number on the same breath. If you hear the ending thin out, stop, breathe, and repeat only the last clause."},{"kicker":"Avoid","body":"Do not lift the shoulders to grab air, and do not whisper the last word to sound gentle. Both habits throw away the part people must act on. Give the date its own quiet breath and then stop talking."}],"example":{"speaker":"Priya","role":"team lead","script":"The release stays on Thursday, and the extra dashboard moves to the next sprint. The dashboard failed review twice, and it is now the item that threatens the date. I am protecting the pilot we already promised. I will bring the dashboard back with a named reviewer, not as a silent add. I need a yes on that cut before we leave this call. If we reopen the scope today, we will miss the date the clinic already has.","note":"She can breathe before the ask, so the date does not fade. The cut and the yes are separate breaths, which is why the last line still sounds decided."},"quiz":[{"q":"Where does the breath actually earn its keep?","options":["In the greeting, which is what people remember.","On the last words: the date, the name, or the no.","In one huge inhale at the start, after which you coast."],"answer":1,"why":"Listeners keep the ending, so a voice that dies there takes the instruction with it."},{"q":"What does a useful mid-update breath look like?","options":["A shoulder lift every few words, so the effort is visible.","An audible gasp placed right on the figure.","A low, quiet breath at a comma you chose, shoulders still."],"answer":2,"why":"A low breath reaches the end of the sentence, and a shoulder shrug does not add air that anyone can use."},{"q":"The last words fade. What do you do?","options":["Stop, take a fresh breath, and repeat only the ending.","Push from the throat so the sentence finishes somehow.","Drop to a whisper so you do not sound abrupt."],"answer":0,"why":"A repeated ending on new air is intelligible, and pushing the scraps only adds strain."}],"exercise":{"prompt":"Describe a date change from your real week. The last word of each sentence should arrive as clearly as the first.","seconds":45,"scaffold":["What changes","Why, in one sentence","The date, still supported","One second of silence"],"focus":"breath"}},{"id":"m1-resonance","module":1,"title":"Resonance and projection","minutes":4,"framework":"Forward resonance","promise":"You will reach the back of the room, or the far end of a call, without shouting and without parking the voice in your throat.","focus":"volume","free":true,"cards":[{"kicker":"Why it matters","body":"A pushed voice carries a few metres and then scrapes, and listeners hear the scrape as strain or as anger. A forward tone reaches the person who is not sitting next to you and still sounds like conversation. The person at the back has the same claim on the update as the person beside you."},{"kicker":"Do this","body":"Hum a comfortable note until you feel a light buzz at the lips, then speak the first sentence of your update on that same easy placement. Aim at one person in the second row, or at the camera as if it were that person. Let the microphone amplify you, and keep the jaw loose."},{"kicker":"In the room","body":"Sit or stand tall enough for the ribs to move, and leave the chin level. A dropped chin swallows the tone, and a lifted chin looks like effort and thins the sound. Check once, then talk to a person rather than to your own volume."},{"kicker":"Avoid","body":"Do not chase loudness by leaning into the laptop or by hardening the jaw. Both tricks make the recording worse, not better. If someone missed a line, re-aim the tone before you add force."}],"example":{"speaker":"Marcus","role":"project lead","script":"The Valencia install stays on the calendar, and Lyon moves by two weeks. Lyon is waiting on a part we do not have in the cage. Valencia already has the crew and the window. I am asking you to confirm that split so procurement stops chasing both at once. The risk we still carry is Lyon hearing the slip from anyone but us. I will call them this afternoon if you are aligned.","note":"He aims the split at one person and keeps the same easy volume through the ask. Projection here is placement, not force."},"quiz":[{"q":"Where should extra reach come from first?","options":["A forward tone aimed at a person, with the jaw loose.","A harder push from the throat so the back row wakes up.","Leaning into the laptop microphone."],"answer":0,"why":"A forward tone travels further than a pushed throat, and it still sounds like you."},{"q":"What does a dropped chin do to the voice?","options":["It brightens the tone and helps the back of the room.","It signals confidence, so people listen harder.","It swallows the tone, so people hear less of you."],"answer":2,"why":"The chin drop closes the space the sound needs, so effort goes up and clarity goes down."},{"q":"Someone at the side missed your last point. What do you change first?","options":["You repeat it louder and faster.","You repeat it on an easy forward tone, aimed at them.","You skip it, since the others seemed to hear."],"answer":1,"why":"Re-aiming the tone fixes more missed words than adding force."}],"exercise":{"prompt":"Give a short project split to an imaginary second row. Keep the jaw loose, and finish the ask at the same volume as the first sentence.","seconds":60,"scaffold":["The decision in one sentence","The reason, aimed at one person","The risk you still carry","The ask, at the same volume"],"focus":"volume"}},{"id":"m1-articulators","module":1,"title":"Articulators","minutes":3,"framework":"Consonant finish","promise":"You will finish the consonants that carry the nouns, so people catch the name, the date, and the number the first time.","focus":"clarity","free":true,"cards":[{"kicker":"Why it matters","body":"Most requests to repeat yourself are unfinished consonants, not difficult ideas. A date, a name, and a negation all live in the last sound of the word. If that sound disappears, the room guesses, and the guess is often the opposite of what you meant."},{"kicker":"Do this","body":"Finish the sounds that do the work: the t in next, the d in decided, the n in plan, the s in risks. Speak those words a touch slower than the words around them. You do not need a new accent. You need the end of the important word to exist."},{"kicker":"In the room","body":"When you give a date or a number, face the person who must act on it and finish the word before you add the next clause. On video this matters more, because the microphone already thins the highs. Give it a complete consonant to transmit."},{"kicker":"Avoid","body":"Do not clamp the jaw, and do not over-shape every syllable as if the board were a language class. Uniform exaggeration sounds performed, and people start watching the delivery. Save the extra finish for names, numbers, negatives, and the verb that carries the decision."}],"example":{"speaker":"Elena","role":"product manager","script":"We decided against a May launch for the billing change. The ledger still drops a tax line on cross-border invoices, and finance will not sign that. The date I will defend is the ninth of June. I need design to freeze the invoice states by Wednesday. I need engineering to name the owner of the tax fix today. If either date slips, I will move the launch in the same week, not the week after.","note":"The negative, the date, and the two owners are finished words. That is the whole technique, used only where a guess would be expensive."},"quiz":[{"q":"Which words deserve the extra consonant finish?","options":["Every word, so the talk sounds polished.","Only the first word of each sentence.","Names, numbers, negatives, and the deciding verb."],"answer":2,"why":"Those are the words a listener cannot safely guess."},{"q":"A colleague misses the date you just gave. What is the likely cause?","options":["The final consonant was too soft for the room or the mic.","The idea was too complex for a status meeting.","They were not senior enough to follow the plan."],"answer":0,"why":"Dates fail in the mouth more often than they fail in the logic."},{"q":"How does over-shaping every syllable land with a board?","options":["It sounds precise, and precision always reads as seniority.","It sounds performed, and people start watching the delivery.","It is the only way anyone outside your team can follow."],"answer":1,"why":"Uniform exaggeration draws attention onto technique and away from the point."}],"exercise":{"prompt":"Explain a decision that includes a name, a date, and a no. Finish those three words so someone across a table could write them down.","seconds":40,"scaffold":["The decision, with a clear yes or no","The name of the owner","The date, finished","One consequence if the date moves"],"focus":"clarity"}},{"id":"m1-pace","module":1,"title":"Pace and the power pause","minutes":4,"framework":"Power pause","promise":"You will slow the clause that carries the decision and leave one real pause where a listener can catch up.","focus":"pace","free":true,"cards":[{"kicker":"Why it matters","body":"A fast update feels efficient to you and unfinished to everyone else. People cannot store a number, a name, and a request delivered at the same speed as the background. Pace is how you tell them which sentence to keep."},{"kicker":"Do this","body":"Speak the context at your ordinary rate, then drop the decision sentence by a small, obvious amount. After that sentence, stop for a full beat before the reason. That beat is the power pause: silence you chose, doing work."},{"kicker":"In the room","body":"Use one power pause per turn, and put it after the sentence you want quoted later. If you are running long, cut a sentence of background. Do not pay the debt by speaking faster, because faster is how the decision gets lost."},{"kicker":"Avoid","body":"Do not fill the pause with a little laugh or with so, yeah. That spends the silence and turns a choice into an apology. Also skip the theatrical wait that makes a video call look frozen."}],"example":{"speaker":"James","role":"plant engineer","script":"Line three is back up. The stop this morning was a jammed infeed, and it cost us twenty-two minutes. I am holding the afternoon plan as it stands. I want the next shift to walk the infeed before they start, not after the first jam. Maintenance has already replaced the guide. I will confirm that check on the handover sheet before two.","note":"The short sentence is where he would pause, and everything after it is support at an easier pace. He cuts nothing that the next shift must do."},"quiz":[{"q":"Where does a power pause belong?","options":["Before every sentence, so the talk feels weighty.","After the one sentence you want the room to remember.","Only when you have forgotten the next point."],"answer":1,"why":"One chosen silence marks the point, and a pause on every line becomes a mannerism."},{"q":"You are over time. What keeps the decision intact?","options":["Cut a sentence of background and keep the slower decision line.","Speed up from the middle so you still say everything.","Drop the ask and let people infer it."],"answer":0,"why":"Speed hides the point, and a missing ask leaves the meeting with no owner."},{"q":"What turns a useful pause into noise?","options":["Looking at the person who owns the action.","Breathing out while you hold the silence.","Filling it with so, yeah, or a small laugh."],"answer":2,"why":"The filler spends the silence, so the listener never gets the beat you meant them to have."}],"exercise":{"prompt":"Give a status in this window. Say the result in a short sentence, pause, then give the reason and the next check.","seconds":55,"scaffold":["Context, at an ordinary pace","The result, slower","A full pause","The next check, and who does it"],"focus":"pace"}},{"id":"m1-pitch","module":1,"title":"Pitch variety and uptalk","minutes":5,"framework":"Pitch and uptalk","promise":"You will let a statement end down, and you will lift the voice only when you are actually asking a question.","focus":"pitch","free":true,"cards":[{"kicker":"Why it matters","body":"A rising end on a statement invites the room to approve it, even when you meant to inform them. That habit hands the decision to whoever speaks next. A flat line is hard to follow, and a line that only rises is hard to trust."},{"kicker":"Do this","body":"Hear the last few words of a decision and aim them slightly down, as if you were setting a cup on a table. Let one word inside the sentence carry a little more height, so the line has shape. Save the rise for a real question."},{"kicker":"In the room","body":"On we will ship Thursday, the word Thursday sits down. On does Thursday still work, the word work may rise. If you hear yourself lift on a recommendation, repeat the last clause once with the ending down, and then stop."},{"kicker":"Avoid","body":"Do not pin every sentence to the same low note in the name of sounding serious. Monotone reads as distance, especially on video, where people have less face to read. Also retire the apologetic lift on if that is okay, which turns a plan into a request for permission."}],"example":{"speaker":"Priya","role":"team lead","script":"We will send the offer to the two finalists on Friday. The third candidate stays on the reserve list until the references come back. I am comfortable with that order because the panel scored it the same way on Monday. Does anyone here have a reference we have not already logged? If I hear none, I will send the notes this afternoon. I will use the wording we just agreed, and I will not reopen the ranking in the email.","note":"The decision lands down. The only rise is the real question, and she returns to a statement before she stops."},"quiz":[{"q":"What is uptalk doing inside a recommendation?","options":["It shows warmth, so people feel included.","It keeps the ear awake by varying every ending.","It asks for approval on a sentence you meant as a decision."],"answer":2,"why":"A rising ending turns a statement into a question, whether you intended that or not."},{"q":"Where should pitch be allowed to rise?","options":["On the last word of every sentence, for energy.","On a genuine question, and on one important word inside a statement.","Nowhere, if you want to sound senior."],"answer":1,"why":"Variety keeps the ear engaged, and the final direction tells people whether you decided or asked."},{"q":"A monotone through a whole update tends to sound like what?","options":["Distance, because the ear has no shape to follow.","Gravitas, because serious people never move their pitch.","Clarity, because every word gets equal weight."],"answer":0,"why":"Without shape, listeners work harder and remember less, and many of them read the flat line as disengagement."}],"exercise":{"prompt":"State a decision, ask one real question, then restate the decision. Let only the question rise.","seconds":50,"scaffold":["Decision, ending down","One reason","One real question, ending up","Decision again, ending down"],"focus":"pitch"}},{"id":"m1-health","module":1,"title":"Vocal health for talkers","minutes":4,"framework":"Vocal load","promise":"You will get through a day of calls with a voice that still sounds like you at the last one.","focus":"breath","free":true,"cards":[{"kicker":"Why it matters","body":"A tired voice is a tool losing range, and by the late meeting you will rush, push, and flatten the points that needed care. Most office strain comes from too much air pressure and too little water, not from a dramatic injury. The last call of the day deserves the same voice as the first."},{"kicker":"Do this","body":"Drink water through the day, and take two quiet minutes between stacked calls where you do not narrate your inbox aloud. Unhook the jaw once, even with the lips closed if you are in an open office. Start the next meeting at a comfortable volume instead of matching the loudest person from the call before."},{"kicker":"In the room","body":"When you hand the screen to someone else, take the sip and the reset. If a scratch appears, drop the volume a little and slow the rate. Repeated throat clearing slams the folds together and makes the next hour worse."},{"kicker":"Avoid","body":"Do not whisper through a sore day, because whispering strains more than easy speech. Pain, a voice that cuts out, or hoarseness that outlasts the week belongs with a clinician. Stop the heroic meeting and book the appointment."}],"example":{"speaker":"Elena","role":"product manager","script":"I have a full afternoon of reviews, so this update stays short and at an easy volume. The onboarding experiment continues for one more week. I am not opening a second experiment beside it. Luis owns the copy, and I own the decision on Friday. I am taking two quiet minutes and some water before the next call. Send me anything urgent in writing, and I will deal with it at the start of that call.","note":"She names the load and chooses a smaller, easier turn. That choice is vocal health inside a real calendar."},"quiz":[{"q":"What is a useful reset between back-to-back calls?","options":["Two quiet minutes, a sip of water, and an easy jaw.","A loud hum in the corridor so the voice wakes up.","Whispering your notes, to rest the voice."],"answer":0,"why":"Quiet, water, and a loose jaw reduce load, while whispering and blasting both add strain."},{"q":"A scratch shows up halfway through a long meeting. What do you change?","options":["Clear the throat firmly each time the scratch returns.","Drop the volume a little and slow the rate.","Push more air so the scratch does not show."],"answer":1,"why":"Less force and more time between words irritates a tired voice less than clearing or pushing."},{"q":"Hoarseness that lasts beyond the week means what?","options":["Schedule more speaking practice to build stamina.","Whisper until it passes.","See a clinician rather than coach your way through it."],"answer":2,"why":"Persistent hoarseness, pain, or a voice that cuts out is a medical question, not a technique question."}],"exercise":{"prompt":"Describe a day with four calls. Say how you will open the third one at an easy volume, and name the break you will actually take.","seconds":70,"scaffold":["How many conversations are on the day","The volume you will start with","The break, including water","What you will not add to the third call"],"focus":"breath"}},{"id":"m2-presence","module":2,"title":"What presence is","minutes":4,"framework":"Gravitas","promise":"You will show presence by owning a short silence and by finishing the thought you started.","focus":"presence","free":true,"cards":[{"kicker":"Why it matters","body":"Presence is not a personality type, and it is not height, title, or a deeper voice you put on. It is the impression that you will still be on this point in ten seconds. Rooms trust people who finish, and they fidget when a speaker abandons a sentence to chase a reaction."},{"kicker":"Do this","body":"Arrive at the thought before you speak it. Look at one person for the whole first sentence, and complete that sentence even if a slide is late or a face looks bored. You can adjust the second sentence. The first one gets finished."},{"kicker":"In the room","body":"Let a question land, count one beat, and answer the question that was asked before you add context. People experience that beat as respect and the clean line as command of the subject. Rushing the answer feels like you were waiting to talk."},{"kicker":"Avoid","body":"Do not open with I just want to quickly say. That phrase spends the presence you had, and it invites the interruption you fear. Start with the point, and end when the point is done, including when the room is quiet."}],"example":{"speaker":"Marcus","role":"project lead","script":"I will take the question on the date first. The revised date is the twelfth of May, and I am comfortable defending it. The slip comes from the access window at the hospital, which we did not control. I am not going to walk the whole plan unless you want that next. The decision I need today is approval of the twelfth. If we keep the old date, we will publish a promise the site cannot keep.","note":"He lets the question land, names it, and finishes the date before he offers more. That sequence is gravitas in ordinary clothes."},"quiz":[{"q":"What is a reliable sign of presence?","options":["Speaking more than anyone else in the room.","Finishing the sentence you started, including after a short silence.","Using a lower voice than your natural one."],"answer":1,"why":"Presence is follow-through on a point, and the silence before it shows you are choosing it."},{"q":"A question arrives. What do you do in the first moments?","options":["Explain the background immediately so there is no gap.","Repeat the whole question word for word.","Let it land, then answer that question in one opening line."],"answer":2,"why":"The beat plus a direct answer reads as command, while an instant background dump reads as nerves."},{"q":"Which opener spends presence before you have said anything useful?","options":["I just want to quickly say.","A one-line answer to the question that was asked.","The date, spoken to one person."],"answer":0,"why":"The apology opener tells the room you expect to be interrupted, and they often oblige."}],"exercise":{"prompt":"Answer a hard question about a date. Wait a beat, give the date, give one reason, and stop.","seconds":45,"scaffold":["One beat of silence","The direct answer","One reason","The decision you need","Stop"],"focus":"presence"}},{"id":"m2-composure","module":2,"title":"Composure under pressure","minutes":5,"framework":"Steady state","promise":"You will keep your rate and your volume steady when a question turns sharp.","focus":"presence","free":false,"cards":[{"kicker":"Why it matters","body":"Under pressure, most people speed up and get either louder or smaller. Both changes tell the room the question landed as a threat. Composure is a physical choice you can make on one breath: same pace, same volume, same length of sentence as the minute before."},{"kicker":"Do this","body":"When the sharp question arrives, breathe out before the first word. Answer in a sentence no longer than the ones you were already using. If you need a moment, name the piece you will answer first, and take it. Naming the piece is control."},{"kicker":"In the room","body":"Look at the person who asked, not at a friendly face that will rescue you. Give them the fact, then the limit of what you know. Offer the time of the next update rather than a certainty you invented at the table."},{"kicker":"Avoid","body":"Do not laugh the question off, and do not punish it with a clipped aside. Sarcasm feels like composure from the inside and like contempt from the seats. Skip the long preface about how fair the question is, and answer it."}],"example":{"speaker":"James","role":"plant engineer","script":"The line stopped for forty minutes at the start of nights, and I own that report. The cause I can stand behind is a failed sensor on the filler, and maintenance has replaced it. I do not yet have the note on why the sensor failed. I will have that note by the end of tomorrow, and I will send it to you directly. What I can say now is that the line is stable and the shift lead has a written check. I will not guess the cause in this room.","note":"Rate and sentence length stay ordinary while the content is uncomfortable. He separates what he knows from what he will not invent."},"quiz":[{"q":"A sharp question hits. What is the first useful move?","options":["Breathe out, then answer at the pace you were already using.","Speed up so you look prepared.","Raise your volume so the challenge does not hang in the air."],"answer":0,"why":"Matching your previous pace tells the room the question did not knock you off the point."},{"q":"You do not have the figure they want. What sounds composed?","options":["A rough number, spoken with confidence, so the silence ends.","A long comment on why the question is reasonable.","The limit of what you know, plus the time you will send the real figure."],"answer":2,"why":"A calm boundary is more credible than a number you assembled at the table."},{"q":"Which response pretends to be composure and lands as contempt?","options":["A short answer, looked at the person who asked.","A joke or a clipped aside that punishes the question.","I will take the date first."],"answer":1,"why":"Sarcasm reads as control from the inside and as disdain from the room."}],"exercise":{"prompt":"Someone challenges a slip you own. Answer in steady sentences: what happened, what you know, what you will not guess, and when you will come back.","seconds":60,"scaffold":["The fact you own","One cause you actually know","The limit","The time of the next update"],"focus":"presence"}},{"id":"m2-decisive","module":2,"title":"Decisive language","minutes":4,"framework":"Clean recommendation","promise":"You will take the hedges off a recommendation so the verb says what you actually mean.","focus":"fillers","free":false,"cards":[{"kicker":"Why it matters","body":"A stack of maybe, just, and I think can hide a perfectly good decision. Listeners remember the hedge and misplace the verb. In a room that has to act, extra softeners raise the cost of agreeing with you, because people must first decide whether you meant it."},{"kicker":"Do this","body":"Write the recommendation as a bare sentence and say it, for example that you recommend a two-week delay. If you want to show judgment, put it in a reason or a risk, not in four hedges stacked on the verb. One softener is a choice, and four is a habit."},{"kicker":"In the room","body":"Replace just, sort of, and if that makes sense with a full stop. If you need buy-in, ask for it in a separate sentence that names the decision and the day. That is cleaner than bending the recommendation itself into a question."},{"kicker":"Avoid","body":"Do not swap every hedge for a command you do not have the authority to give. We must, on a topic you do not own, sounds naive. I recommend, I will, and I need match most rooms. The only possible path is a dare."}],"example":{"speaker":"Elena","role":"product manager","script":"I recommend we hold the price test for two weeks. The sample is too small to call a winner, and calling it now would lock a price the data does not support. I will use the extra time to widen the sample to the mid-market accounts. I need a decision from this group before Thursday. I am comfortable being wrong on the delay if a regulator date appears. I am not comfortable treating the current sample as a result.","note":"The hedges are gone, and the humility sits in a real condition rather than in the verb. The ask is its own sentence."},"quiz":[{"q":"Where should humility live in a recommendation?","options":["In a stack of softeners before the verb.","In an apology for raising the topic.","In a reason, a risk, or a condition, beside a clean verb."],"answer":2,"why":"The verb should say what you mean, and the risk can carry the honesty."},{"q":"Which sentence is decisive without overreaching?","options":["I recommend we delay by two weeks.","I just think maybe we kind of delay, if that makes sense.","No serious person would choose anything else."],"answer":0,"why":"I recommend matches ordinary authority, while a hedge stack and an absolute both distort it."},{"q":"You want agreement. How do you ask?","options":["Turn the recommendation into a question with a rising end.","Add a separate sentence that names the decision and the timing.","Add the word just, so the ask feels smaller."],"answer":1,"why":"A separate ask is easy to answer, and a softened recommendation is easy to ignore."}],"exercise":{"prompt":"State a recommendation you actually hold. One clean sentence, one reason, one risk, one ask. Leave out just and I think maybe.","seconds":45,"scaffold":["I recommend","Because","The risk I accept","The decision I need, and when"],"focus":"fillers"}},{"id":"m2-body","module":2,"title":"Body language on video calls","minutes":4,"framework":"Camera presence","promise":"You will let your eyes, hands, and frame agree with the sentence you are saying.","focus":"presence","free":false,"cards":[{"kicker":"Why it matters","body":"On a video call the other person is reading a small rectangle, and a mismatched signal wins. A strong sentence delivered while you watch your own preview, or while you lean toward a second screen, gets discounted. On camera, the body is part of the sentence."},{"kicker":"Do this","body":"Put the camera at eye height, and look into the lens when you deliver the decision. Use one open gesture on the verb, inside the frame, then let the hands rest. Sit close enough that your face is readable and far enough that your shoulders show you are in the meeting."},{"kicker":"In the room","body":"When you listen, look at the screen rather than at your notes, and keep the hands still enough that the other person can finish. One nod at the end of their point reads as attention. A nod on every phrase reads as hurry."},{"kicker":"Avoid","body":"Do not fold your arms for a whole update, and do not roll your chair. Both read as an exit. Skip the glance at your own tile while you finish the ask. The tile is a mirror, and mirrors make speakers perform."}],"example":{"speaker":"Priya","role":"team lead","script":"We are keeping the Thursday release, and we are cutting the extra report. I have told the clinic we will send the core flow only. I am treating that scope question as closed unless someone here has a customer impact I have missed. Sam owns the cut in the build. I own the note to the clinic, and I will send it after this call. If you have a concern, raise it now, and I will take it before I write to them.","note":"The decision is a lens moment, with one gesture on the cut and then stillness while she waits. She does not type, and she does not check her own tile."},"quiz":[{"q":"When do you look into the lens?","options":["For the entire meeting, without a break.","When you deliver the decision or the ask.","Only while someone else is talking."],"answer":1,"why":"The lens is for the line you need believed, and staring at it for an hour looks unreal."},{"q":"What does a constant nod do while the other person talks?","options":["It hurries them, even when you meant to be encouraging.","It proves you agree with every clause.","It makes you look more senior."],"answer":0,"why":"Repeated nodding is a speed cue, and one nod at the end reads as attention."},{"q":"Which habit pulls credibility off a good sentence?","options":["Hands resting after a single gesture.","A camera set at eye height.","Checking your own tile while you finish the ask."],"answer":2,"why":"The self-check tells the listener you are watching yourself rather than them."}],"exercise":{"prompt":"Deliver a decision to a camera, even a phone on a stack of books. Look into the lens on the ask, use one gesture, then be still.","seconds":50,"scaffold":["Frame: eyes and shoulders","The decision, into the lens","One gesture on the verb","Hands still for the ask","Wait"],"focus":"presence"}},{"id":"m2-first30","module":2,"title":"The first 30 seconds","minutes":3,"framework":"Opening frame","promise":"You will spend the opening half-minute on the point, the stake, and the ask.","focus":"structure","free":false,"cards":[{"kicker":"Why it matters","body":"People decide whether to track you in the first half-minute, and they rarely revise that decision because of extra background. A long runway feels polite to the speaker and expensive to the room. The opening is the talk, in miniature."},{"kicker":"Do this","body":"Use three short moves: the point you want them to leave with, the stake if nothing changes, and the ask you need before you sit down. Say those three before you offer the path you will take them down. If you only have one breath, keep the ask."},{"kicker":"In the room","body":"If a slide is still loading, say the three moves anyway. If someone opens with small talk, match them for one line, then cross over with a sentence about what you need from the time. You can be warm and still arrive."},{"kicker":"Avoid","body":"Do not open with your biography, your agenda, or an apology for the technology. Do not open with the history of the project from the year it was funded. History can come second, once they know why they are listening."}],"example":{"speaker":"Marcus","role":"project lead","script":"I need a decision today on the city permit for the sensor mast. If we miss this filing window, the install moves a full month and the training dates move with it. I am asking you to approve the filing on Thursday and the smaller first site. I will cover the risk, the cost, and the option we turned down. I will leave five minutes for the question I expect on the neighbour letter. The decision comes back at the end, so we do not lose it in the detail.","note":"Point, stake, and ask are done before any chronology. The rest of the talk is announced, not begun."},"quiz":[{"q":"What belongs in the first thirty seconds?","options":["The funding history, so the room respects the work.","A short biography, so new people know your role.","The point, the stake, and the ask."],"answer":2,"why":"Those three moves tell people why to listen, and the history can follow if it is still needed."},{"q":"The slide has not loaded. What do you do?","options":["Wait in silence until it appears.","Say the point, the stake, and the ask without it.","Apologise for the technology until someone else starts."],"answer":1,"why":"The opening is a spoken structure, and a slide is only support."},{"q":"Which opening spends the half-minute?","options":["Let me start with how this project was funded.","I need a decision today on the filing.","If we miss the window, the install moves a month."],"answer":0,"why":"Chronology before the stake spends attention you may not get back."}],"exercise":{"prompt":"Open a talk you actually have to give. Point, stake, ask, then one line on what you will cover. Stop inside the window.","seconds":40,"scaffold":["The point","The stake if nothing changes","The ask","The path, in one line"],"focus":"structure"}},{"id":"m2-credibility","module":2,"title":"Credibility","minutes":5,"framework":"Claim, evidence, limit","promise":"You will pair an important claim with a number, a source, and the limit of what that number can prove.","focus":"structure","free":false,"cards":[{"kicker":"Why it matters","body":"Credibility is a trail a sceptical person can walk. A bare adjective such as significant or aligned leaves them nothing to hold. When you offer the figure, where it lives, and what it does not prove, you sound more sure, not less."},{"kicker":"Do this","body":"Use three parts: the claim, the evidence with its number and its source, and the limit you would rather they heard from you. Then recommend only what that limit allows. A limit that is doing real work will narrow the recommendation, and that narrowness is the credibility."},{"kicker":"In the room","body":"If you do not have the number, say what you looked at and when the figure will exist. If someone challenges the source, stay with the method for one sentence. Write down the extra cut of data they want, and do not swap in a friendlier number."},{"kicker":"Avoid","body":"Do not say studies show without a study, and do not flood the slide with three numbers when one would do. A crowd of figures looks like cover. Also skip the false precision of a decimal you cannot explain if someone asks how it was rounded."}],"example":{"speaker":"Elena","role":"product manager","script":"On-site response inside four hours happened on nine of the last twelve night calls. That count is from our own ticket log, for the Bilbao line only, across the last quarter. It does not include the day shift, and I will not stretch it that far. I recommend we renew the night cover and renegotiate the day clause separately. I will bring the day-shift cut when that sample is large enough to survive a sceptical read. The source stays the ticket log, and I can send the extract after this meeting.","note":"Claim, source, and limit arrive before the recommendation, and the recommendation does not travel further than the sample."},"quiz":[{"q":"What completes a credible claim?","options":["A number, the place it came from, and what it does not prove.","A stronger adjective, such as very significant.","Three extra metrics, so the slide looks full."],"answer":0,"why":"A source and a limit give a sceptic a path, and an adjective does not."},{"q":"You do not have the figure yet. What protects credibility?","options":["A rounded guess, spoken as if it were measured.","A plain statement of what you checked, and when the figure will exist.","The phrase studies show, so the claim has a halo."],"answer":1,"why":"Naming the gap is stronger than decorating it."},{"q":"Someone attacks the source. What do you do?","options":["Switch to a different number they have not attacked.","Say the room is getting lost in detail.","Stay with the method for one sentence, and note the extra cut they want."],"answer":2,"why":"Defending the method you actually used keeps the claim inspectable."}],"exercise":{"prompt":"Make one claim from your real work. Use the stack: claim, evidence, limit, and a recommendation that respects the limit.","seconds":65,"scaffold":["The claim in one sentence","The number, and where it lives","The limit","What you recommend given that limit"],"focus":"structure"}},{"id":"m3-bluf","module":3,"title":"BLUF","minutes":4,"framework":"BLUF","promise":"You will open with the bottom line so a busy person hears the decision before the background.","focus":"structure","free":true,"cards":[{"kicker":"Why it matters","body":"BLUF means bottom line up front. Tired people and senior people listen the same way: they take the first concrete sentence as the point, and they treat everything before it as warming up. If your point arrives in minute three, you have made them work for it."},{"kicker":"Do this","body":"Write a sentence a person could forward: the decision, the consequence, and what you need. Say that sentence first, out loud, before cause, history, or credit. Then give only the background that makes the bottom line make sense."},{"kicker":"In the room","body":"In an email, the bottom line is the first line. In a meeting, it is your first breath. In a handover, it is the state of the work and the thing the next person must do, before the story of the night."},{"kicker":"Avoid","body":"Do not hide a bad number under two paragraphs of effort. Effort can follow the number. A bottom line with no ask is a headline, and a handover needs the ask."}],"example":{"speaker":"James","role":"plant engineer","script":"The night shift lost forty-seven minutes on line two because the filler PLC dropped into fault, and nobody on the handover had the reset steps. I want those steps on the shift sheet before Friday. The fault was a full hopper sensor, not a programme change. Maintenance cleared it, and the line has run clean since six in the morning. I need a named owner for the sheet and a check on tonight's handover. A verbal note will cost us the same hour next week.","note":"The lost time and the missing steps are the bottom line, and the cause comes after the ask is already in the room. PLC, downtime, and the handover are all in the first breath."},"quiz":[{"q":"What does BLUF ask you to say first?","options":["The full history, so the decision feels earned.","The decision, the consequence, and what you need.","An apology, if the news is bad."],"answer":1,"why":"The first concrete sentence is the one busy people keep, so that sentence has to be the bottom line."},{"q":"Where does background belong?","options":["Before the point, so nobody feels surprised.","In a separate meeting, never beside the decision.","After the bottom line, and only the part that makes the ask make sense."],"answer":2,"why":"Background serves the decision, and it does not need to introduce it."},{"q":"A handover is running long. What do you protect?","options":["The state of the work and the action the next person must take.","The story of how hard the night was.","Every alarm, in the order it appeared."],"answer":0,"why":"A handover is a bottom line plus the next action, and the chronicle can wait."}],"exercise":{"prompt":"Give a BLUF handover of a real or realistic incident. Put the decision and the ask first, and the cause second.","seconds":55,"scaffold":["What happened, in one sentence","What you need, and by when","The cause, short","The owner of the next step"],"focus":"structure"}},{"id":"m3-scqa","module":3,"title":"Pyramid and SCQA","minutes":5,"framework":"SCQA","promise":"You will shape a recommendation as situation, complication, question, and answer, so the ask has a reason to exist.","focus":"structure","free":false,"cards":[{"kicker":"Why it matters","body":"A list without a question is a pile, and a story without a recommendation wanders, which is why SCQA pairs them. Situation is the fact you share, complication is what changed, and the question is the decision that change creates. The answer is your recommendation, narrow enough that someone can own it."},{"kicker":"Do this","body":"Draft four lines and say them in order the first time you use the shape. One sentence each is enough. Add evidence under the answer only after the four lines have landed. If the situation takes a minute, you have written a preface."},{"kicker":"In the room","body":"Pick a situation the listener already believes, or you will spend the meeting proving the wrong thing. Make the complication specific enough that the question has only a few honest answers. Then recommend one of them, with an owner."},{"kicker":"Avoid","body":"Do not open with the answer when you chose SCQA to bring a sceptical room with you. That job belongs to BLUF, which is better when people already want the headline. Do not invent a complication to make a calm update feel dramatic."}],"example":{"speaker":"Priya","role":"team lead","script":"The on-call rota has been stable all quarter, and people can plan a weekend. Last month three alerts fired for the same stale job, and two of them woke someone at two in the morning. The question is whether we delete that job or keep paging on it. I recommend we delete it this week and review the other nightly jobs on Friday. The customer impact of the stale job has been zero since March. I will send the deletion note if this room agrees.","note":"Situation, complication, question, and answer each have their own sentence. The evidence is one line, and then she asks for the agreement."},"quiz":[{"q":"What is the situation in SCQA?","options":["A stable fact the listener already believes.","Your recommendation, dressed as context.","The most dramatic detail you have."],"answer":0,"why":"If they do not accept the situation, they never reach your question."},{"q":"What is the complication's job?","options":["To prove the team has been working hard.","To fill time before the ask.","To change the situation so a real decision appears."],"answer":2,"why":"The complication is the change that forces a choice."},{"q":"When is SCQA a better opening than BLUF?","options":["When the room only wants a headline and already trusts you.","When a sceptical room needs to feel the question before the answer.","When you have no recommendation yet."],"answer":1,"why":"SCQA earns the answer by building the question, while BLUF hands the answer over immediately."}],"exercise":{"prompt":"Build an SCQA for a decision you are actually in. Four sentences, in order, then one line of evidence.","seconds":60,"scaffold":["Situation they already accept","Complication that changed it","The question, spoken as a question","Your answer","One piece of evidence"],"focus":"structure"}},{"id":"m3-prep","module":3,"title":"PREP for impromptu","minutes":4,"framework":"PREP","promise":"You will answer an unexpected question with a point, a reason, an example, and the point again.","focus":"structure","free":false,"cards":[{"kicker":"Why it matters","body":"Impromptu trouble is rarely a lack of knowledge. It is a lack of a first sentence. PREP gives you that sentence and a way back to it: point, reason, example, point. You can fill the four slots while the question is still being asked."},{"kicker":"Do this","body":"Start with a verb. Yes, I would delay, is a point. Add one reason, then one example from this week, not from your whole career. Say the point again in fresh words so the answer closes on your conclusion."},{"kicker":"In the room","body":"If the question is sharp, PREP keeps you from matching the heat. Keep the example inside two sentences. If you have no real example, use a concrete hypothetical and label it as one, then return to the point."},{"kicker":"Avoid","body":"Do not open with that is a great question as a reflex. It buys no time and it sounds like a stall. Give one reason, not three, and do not end on the anecdote."}],"example":{"speaker":"Elena","role":"product manager","script":"Yes, I would buy the notifications service rather than build it. The reason is staffing: the same four people already own checkout. Last month a small in-house alert tool slipped twice because those four were on a payments incident. I checked that with the engineering manager on Monday. So I would buy, and I would keep the contract to one year. I will bring a vendor shortlist on Friday if you want the next step.","note":"Point, reason, a short example, and the point again. The Friday line is a next step still in service of the same answer."},"quiz":[{"q":"What is the first move in PREP?","options":["A compliment on the question.","Three reasons, so you sound thorough.","A point, stated as a sentence with a verb."],"answer":2,"why":"The point gives the answer a spine, and the rest of PREP hangs from it."},{"q":"How long should the example be?","options":["Short enough for two sentences, and taken from recent work.","A full career story, so the point feels earned.","Skipped, because senior people do not need examples."],"answer":0,"why":"A small true example proves the point, and a long one replaces it."},{"q":"Where should the answer end?","options":["On the most vivid detail of the example.","On the point, said again in fresh words.","On a new topic you would rather discuss."],"answer":1,"why":"The repeated point is what you want remembered, and the example is only support."}],"exercise":{"prompt":"Answer a question you do not have a slide for. Use PREP inside this window, and close on the point rather than on the story.","seconds":45,"scaffold":["Point, one sentence","One reason","One recent example","Point again"],"focus":"structure"}},{"id":"m3-three","module":3,"title":"Rule of three","minutes":4,"framework":"Rule of three","promise":"You will group a messy update into three beats a person can repeat after the meeting.","focus":"structure","free":false,"cards":[{"kicker":"Why it matters","body":"Working memory keeps a few chunks and drops the rest, however fair your twelve points were. Three is a number people can retell without notes. Two can feel thin, and four starts to sound like a list you might reorder under pressure."},{"kicker":"Do this","body":"Cluster the raw points into three buckets with plain names, such as progress, risk, and ask. Say the three names before you fill them. Then one or two sentences each. A point that fits nowhere is a candidate to cut or to park."},{"kicker":"In the room","body":"Number them in speech, first, second, third, and give each a similar length. Parallel shape is what makes the three memorable. A long middle and two scraps is really one point with decorations."},{"kicker":"Avoid","body":"Do not force three when you have one clean recommendation. A single decision beats a fake trilogy. And do not name the buckets with abstract nouns nobody will repeat."}],"example":{"speaker":"Marcus","role":"project lead","script":"Three things from the school device rollout. First, the year-seven laptops arrive on the eighth if the board signs the delivery window today. Second, the risk is storage at the two smaller sites, not the image, which is ready. Third, I need a named facilities contact at each site by Wednesday. I will send the one-page brief after this meeting. I am parking the discussion of the staff tablets until this window is decided. That is the whole update.","note":"He names the three before the detail grows, and he parks a fourth topic out loud so it cannot sneak in."},"quiz":[{"q":"Why three, rather than every point you prepared?","options":["Because three is a classical habit you ought to honour.","Because people can retell three chunks after they leave.","Because leaders get impatient after exactly one minute."],"answer":1,"why":"Three matches what listeners can carry and repeat, and the rest belongs in a note."},{"q":"A point fits none of the three buckets. What do you do?","options":["Park it or cut it, and say that you have done so.","Add it quickly as a fourth, so nobody feels ignored.","Stretch a bucket until the point sort of fits."],"answer":0,"why":"A named park keeps trust, and a smuggled fourth breaks the shape people were holding."},{"q":"What makes the three easy to replay?","options":["Abstract labels that sound strategic.","A much longer second point, where the real content sits.","Plain names, spoken first, with a similar length on each."],"answer":2,"why":"Parallel shape and ordinary words are what a listener can say back in the corridor."}],"exercise":{"prompt":"Take a messy update and deliver it as three named beats. Say the names before you fill them.","seconds":50,"scaffold":["Three things","First, with a plain name","Second, similar length","Third, the ask","What you are parking"],"focus":"structure"}},{"id":"m3-technical","module":3,"title":"Explain technical topics simply","minutes":5,"framework":"Plain words first","promise":"You will explain a technical issue as an effect someone can see, one picture, and the decision that picture creates.","focus":"clarity","free":false,"cards":[{"kicker":"Why it matters","body":"Jargon is a shortcut between specialists and a wall for everyone else. If you leave the wall up in a decision meeting, people pretend to follow or they take the decision away from you. Translation is part of knowing the subject, not a favour you add if time remains."},{"kicker":"Do this","body":"Start with the effect a non-specialist can see: a queue, a failed payment, a line that waits, a nurse who cannot see the list. Then one picture, such as a gate that sticks or a list that lost a name. Use the real term once, tied to the picture, and end on the decision."},{"kicker":"In the room","body":"Match the depth to the person who must act, not to the colleague who could grade your expertise. Offer the mechanism in a bounded way, for two minutes, if they want it. If they do not, stop. Knowing more than you say is a form of respect."},{"kicker":"Avoid","body":"Do not stack acronyms to prove you belong, and do not soften the conclusion just because the mechanism is now in plain words. A line such as replace the sensor this week can be simple and still exact. A shrug that the issue is technical and handled gives nobody a decision."}],"example":{"speaker":"James","role":"plant engineer","script":"The filler waits for a small switch that says the hopper is full, and last night that switch stuck. Picture a kettle that never tells you it has boiled, so you stand there and nothing pours. The real name is a level sensor on the PLC input, and maintenance has already fitted a new one. The line is running. The decision is whether we keep a spare sensor on the night shift, because the next stuck switch will cost the same wait. I recommend we do, and I can name the cost after this meeting.","note":"Effect, picture, the real term once, then a decision. He does not make the director learn the input map."},"quiz":[{"q":"What should a non-specialist hear first?","options":["The acronym, defined later if anyone asks.","The full mechanism, so the decision is rigorous.","The effect they can already picture, in plain words."],"answer":2,"why":"The effect gives them a reason to care about the mechanism."},{"q":"How often should the specialist term appear?","options":["In every sentence, so the meaning sinks in.","Once, tied to the picture, then back to plain words.","Never, because the real name is a distraction."],"answer":1,"why":"One accurate term respects the subject, and a chain of them hides it."},{"q":"What belongs at the end of a technical explanation to executives?","options":["The decision the picture creates.","A promise that the team has it.","A second, deeper mechanism, in case the first felt thin."],"answer":0,"why":"The explanation exists so someone can act, and the last line should be that act."}],"exercise":{"prompt":"Explain a technical issue from your work to a smart person outside your field. Effect, picture, the term once, then the decision.","seconds":70,"scaffold":["The effect in plain words","One picture","The real term, once","The decision you recommend"],"focus":"clarity"}},{"id":"m3-data","module":3,"title":"Data storytelling","minutes":4,"framework":"Data to decision","promise":"You will turn a chart into one sentence that says what changed, why it matters, and what you will do.","focus":"structure","free":false,"cards":[{"kicker":"Why it matters","body":"A chart without a sentence asks the room to do your job while you talk. People will find different stories in the same bars, and the loudest story will win. Your job is to choose the story the data can support, and to say it before anyone squints."},{"kicker":"Do this","body":"Use one sentence with three slots: what changed, with a number and a window; why it matters to a customer, a ward, a line, or a budget; and what you will do, with an owner and a date. If the third slot is empty, call the chart a curiosity rather than a decision. Read the number slowly enough that someone could write it down."},{"kicker":"In the room","body":"Point at the one mark that carries the sentence, then stop pointing. Read the number slowly enough to write down. A second real trend gets a second sentence, not a tour of every series."},{"kicker":"Avoid","body":"Do not say as you can see when the slide is busy. They cannot see, which is why you are speaking. If you do not know the cause, say what you ruled out and what you will test next."}],"example":{"speaker":"Elena","role":"product manager","script":"Failed checkouts in mid-market fell by a third between week ten and week twelve. That matters because those four countries are the ones we mean to expand next quarter, and the drop is in our payments log. I will roll the change to the rest of mid-market on the second, with Luis as the owner. I am not claiming the enterprise book will move the same way. The enterprise sample is too thin, and I will say so if someone asks me to extend the number. The action I want today is the mid-market roll, not a company-wide one.","note":"Change, consequence, and action are spoken, and the limit is in the room before anyone else can stretch the number."},"quiz":[{"q":"What are the three slots of a data sentence?","options":["What changed, why it matters, and what you will do.","The source system, the analyst, and the colour key.","Three trends, so the chart feels fully used."],"answer":0,"why":"A chart becomes a decision only when movement, consequence, and action are spoken."},{"q":"You do not know the cause. What do you say?","options":["The cause you hope is true, so the story is tidy.","What you have ruled out, and the test you will run next.","As you can see, and then you move to the next slide."],"answer":1,"why":"A named limit keeps the number trustworthy while the cause is still open."},{"q":"How do you handle a second real trend?","options":["Fold it into the same sentence so the slide stays quick.","Drop it, because one chart may hold only one fact.","Give it a second sentence, after the first story is complete."],"answer":2,"why":"A second sentence keeps each trend attached to its own meaning."}],"exercise":{"prompt":"Describe one real chart or metric. Cover the change, the consequence, the action, and the limit of the number.","seconds":60,"scaffold":["What changed, with a number and a window","Why it matters to a person","What you will do, with an owner","The limit of the number"],"focus":"structure"}},{"id":"m4-spine","module":4,"title":"Story spine","minutes":4,"framework":"Story spine","promise":"You will tell a work story with a stake, a turn, and a result in under a minute.","focus":"structure","free":true,"cards":[{"kicker":"Why it matters","body":"Facts inform, and a spine makes them stick. A work story is a short sequence: someone had something at stake, something turned, and the result changed a decision you still stand behind. Without the turn, you have a status report in a costume."},{"kicker":"Do this","body":"Keep five beats tight: who it was for, the stake, what the team did, what turned, and what is different now. If you cannot name the turn, give the update in BLUF instead of stretching an anecdote. One true turn is enough for a minute."},{"kicker":"In the room","body":"Start in the scene, not in the moral. Save the lesson for the last sentence, and make it something the room can use this month. Then stop, even if the longer version is better at dinner."},{"kicker":"Avoid","body":"Do not invent dialogue you do not remember, and do not make yourself the genius of every turn. Do not tell a story whose result you would not put in a written note. If it only works with a wink, it does not belong in the meeting."}],"example":{"speaker":"Priya","role":"team lead","script":"On Monday the clinic called because a nurse could not tell which patients were in the pilot. The stake was simple: a wrong list means a wrong conversation at the bedside. We stopped the extra report and put a single status on the main screen that night. The turn came when the charge nurse used it on Tuesday without calling us. We have kept that screen, and we have dropped three other views that said the same thing. The lesson I want us to keep is that one obvious status beats a clever report nobody opens.","note":"Stake, action, turn, result, and lesson. She is in the story, and the nurse is the person the story is for."},"quiz":[{"q":"What turns a work anecdote into a story spine?","options":["A moral stated before any fact.","A stake, a turn, and a result you can stand behind.","More detail, so the scene feels vivid."],"answer":1,"why":"The turn is the moment the situation changed, and without it you have a description."},{"q":"Where does the lesson belong?","options":["In the first sentence, so busy people can leave.","In a second story, to reinforce the first.","In the last sentence, as something the room can use this month."],"answer":2,"why":"A lesson after the turn has been earned, and a lesson before the scene sounds like a poster."},{"q":"When should you drop the story and use BLUF instead?","options":["When you cannot name a real turn.","When the story is shorter than a minute.","When the result is easy to measure."],"answer":0,"why":"No turn means no story, and a plain update will serve the room better."}],"exercise":{"prompt":"Tell a work story from the last month in five beats, and land the lesson in the final sentence.","seconds":45,"scaffold":["Who it was for","The stake","What the team did","The turn","What is different now"],"focus":"structure"}},{"id":"m4-hero","module":4,"title":"The hero is your team","minutes":4,"framework":"Hero shift","promise":"You will put the person who lived the constraint at the centre of a story you are proud of.","focus":"presence","free":false,"cards":[{"kicker":"Why it matters","body":"A story that stars you can be true and still shrink the room. People support what they can see themselves in. When the centre is the nurse, the operator, the customer, or the junior who caught the miss, the same facts invite pride rather than polite applause."},{"kicker":"Do this","body":"Tell the story from that person's constraint: what they could see, what they lacked, what they did. Put yourself in the role you actually had, in one clause, then go back to them. End on what they can do now that they could not do before."},{"kicker":"In the room","body":"Use a job title and one concrete act, not a compliment about passion. If they are present, offer the result to the group rather than pinning them with a spotlight. A specific act is easier to stand in than a speech about character."},{"kicker":"Avoid","body":"Do not perform humility with it was all the team and no names. That is as vague as taking the credit yourself. Also skip a hero story about someone who did not agree to be the example."}],"example":{"speaker":"Marcus","role":"project lead","script":"The ward clerk spotted that our training slots clashed with the drug round. She had no authority to move the install, and she wrote to us anyway, on a Tuesday night. I moved the access window to the twelfth of May because of that note. The build was already ready, so the change cost us pride and not code. On the day, the round happened on time and the training happened after it. The result belongs to a constraint she was willing to put in writing.","note":"His own act is one clause, and the centre of the story stays with the clerk. The praise is a specific act, not a trait."},"quiz":[{"q":"Who can carry a work story more usefully than you can?","options":["The person who lived the constraint: a customer, an operator, a colleague on the spot.","The most senior person in the room, out of respect.","Nobody. A leadership story should star the leader."],"answer":0,"why":"Listeners enter through the person who had something at stake, and that person is often not the speaker."},{"q":"How should you mention your own part?","options":["Leave it out, so you appear humble.","Describe it at length, because you are accountable.","Name it in one clause, then return to the person at the centre."],"answer":2,"why":"One true clause is accountable, and both a vanishing act and a monologue distort the story."},{"q":"What keeps public praise from becoming a spotlight?","options":["A comment about their passion and energy.","A specific act, offered to the room, from a scene they are willing to own.","A joke that they saved the company."],"answer":1,"why":"A concrete act respects the person, and a trait label puts them on a stage."}],"exercise":{"prompt":"Retell a win with someone else at the centre. Your own action gets one clause.","seconds":55,"scaffold":["Who was on the spot","What they could and could not do","The act they took","Your part, in one clause","What they can do now"],"focus":"presence"}},{"id":"m4-vulnerability","module":4,"title":"Vulnerability with purpose","minutes":5,"framework":"Purposeful vulnerability","promise":"You will name one real limit and the step you already took, in service of a decision the room has to make.","focus":"presence","free":false,"cards":[{"kicker":"Why it matters","body":"A well-placed limit builds more trust than a polished surface, because the room can see the edge of what you know. A disclosure without a purpose is a confession. The useful purposes are narrow: correct a plan, ask for help you have specified, or show that a standard applies to you too."},{"kicker":"Do this","body":"Use a tight shape: the limit in one plain sentence, the consequence of hiding it, the step you have already taken, and the help you want. State that help as something the room can actually give. Then stop, without a tour of how the limit felt."},{"kicker":"In the room","body":"Say the limit early enough that people can still act: a missed staffing risk is useful on Tuesday and expensive on the day of the install. Match the size of the disclosure to the size of the decision. A launch review can hold a miss, and a first meeting with a customer is the wrong room for a career worry."},{"kicker":"Avoid","body":"Do not confess a flaw you have no plan to touch, and do not undercut a clear recommendation with a story that asks the room to take care of you. Comfort is not an action item. If you need a decision, ask for the decision."}],"example":{"speaker":"Elena","role":"product manager","script":"I missed a dependency on the partner API, and that miss is why the May date moved. Hiding it would have put a half-built checkout in front of accounts we are trying to keep. I have asked the partner for a written interface freeze, and I have moved our launch to the ninth of June. What I need from this room is agreement that June is the date we will all say out loud. I am not asking anyone to soften the miss. I am asking us to stop circulating the old date in side conversations.","note":"Limit, consequence, step taken, and an ask. There is no request to be comforted, and no tour of how the miss felt."},"quiz":[{"q":"When is naming a limit useful in a meeting?","options":["Whenever you feel uneasy, so the room can sit with it.","When the story is interesting, even if nothing changes.","When the limit changes a plan, a standard, or a specific request for help."],"answer":2,"why":"Purpose separates a useful limit from a confession the room cannot act on."},{"q":"What belongs immediately after the limit?","options":["The consequence of hiding it, and the step you have already taken.","A full account of how the miss felt.","A joke that shows you are fine."],"answer":0,"why":"Consequence and action turn the limit into information the room can use."},{"q":"Which ask fits this kind of moment?","options":["I hope you are not disappointed in me.","A decision, or a concrete help, that the room can actually give.","A request that someone else explain the miss for you."],"answer":1,"why":"A decision is an action, and reassurance is not."}],"exercise":{"prompt":"Name a real limit you can say at work. Give the consequence, the step you have already taken, and one ask. Leave the feelings report out.","seconds":40,"scaffold":["The limit, one sentence","What happens if it stays hidden","The step you have taken","The decision or help you want"],"focus":"presence"}},{"id":"m4-vision","module":4,"title":"Vision stories","minutes":4,"framework":"Concrete vision","promise":"You will describe a future state as a scene people can picture on a working day.","focus":"pitch","free":false,"cards":[{"kicker":"Why it matters","body":"Abstract vision language washes off. Best in class and customer obsessed give nobody a clue what to do on Tuesday. A vision that works is a short scene of the work going well, plus a standard you will refuse to drop."},{"kicker":"Do this","body":"Pick one ordinary moment: a handover, a release, a clinic morning, a line start. Describe what a person sees and does when the team is succeeding, in the present tense. Then say the one behaviour you will protect. Let the voice lift a little on the scene, and set it down on the standard."},{"kicker":"In the room","body":"Keep it inside a minute unless you were given a stage. Name people by role, not by slogan. End with a part the listener can play this quarter. A vision with no part for the room is a trailer."},{"kicker":"Avoid","body":"Promise a scene you are willing to be held to, rather than a feeling. Skip the foolish rival and the pile of adjectives. One picture, one standard, one part for the room."}],"example":{"speaker":"Priya","role":"team lead","script":"It is a Thursday in March, and the on-call engineer sleeps through the night because the only page that fires is a real one. The stale job is gone, the status on the screen is obvious, and the morning handover takes ten minutes. We got there by refusing every alert that did not change a decision. That refusal is the standard I will protect this quarter. I want each of you to name one alert we can delete before the end of the month. Picture the quiet night, and the cuts get easier to choose.","note":"The scene is in the present tense, the standard lands as a decision, and the room is given a part they can do this month."},"quiz":[{"q":"What is a vision scene?","options":["A list of values on a slide.","An ordinary working moment, described as if you are standing in it.","A promise that the team will feel proud."],"answer":1,"why":"A scene gives people something to recognise and to build, and a feeling does not."},{"q":"Where does the voice settle?","options":["Down, on the standard you will protect.","Up, on every sentence, to keep the energy high.","Flat, so the future sounds serious."],"answer":0,"why":"The scene can lift, and the standard should land as a decision."},{"q":"How do you invite the room in?","options":["By criticising a rival who lacks vision.","By adding adjectives until the picture sounds large.","By naming one part they can play this quarter."],"answer":2,"why":"A part turns a trailer into shared work."}],"exercise":{"prompt":"Describe a working day a year from now as one scene. Lift on the scene, land on the standard, and give the room a part.","seconds":75,"scaffold":["The day and the place","What a person sees and does","The standard you will protect","The part this room plays this quarter"],"focus":"pitch"}},{"id":"m5-standup","module":5,"title":"Running a stand-up","minutes":3,"framework":"One-minute stand-up","promise":"You will run a stand-up that surfaces blockers in about a minute a person and ends with names, not a vibe.","focus":"structure","free":true,"cards":[{"kicker":"Why it matters","body":"A stand-up that becomes a status theatre steals the morning and still hides the blocker. The point of the meeting is the obstacle that needs another person. Progress is context. The blocker is the work."},{"kicker":"Do this","body":"Give every speaker the same three slots, and model them yourself: what you finished, what you are on today, and the name you need if you are blocked. If there is no blocker, they say so and stop. Park any solve past one sentence into a huddle of the people named."},{"kicker":"In the room","body":"Start on time, and keep your own update the shortest if you are chairing. Thank a useful blocker. A person who names a risk early has done the job. If a life story starts, ask who they need, and write the name where the group can see it."},{"kicker":"Avoid","body":"Do not solve a design question with eight people who do not own it. Do not skip the quiet person because a fluent one ran long. Do not end with a vague plea to stay aligned."}],"example":{"speaker":"James","role":"plant engineer","script":"I will go first, and I will keep it to the three slots. Finished: the guide on line three is replaced, and the afternoon plan held. Today: I am writing the infeed check onto the handover sheet. Blocker: none. When you speak, I want finished, today, and the name you need if you are stuck. If the blocker needs a design talk, we will take it after, with the two people named. I will write those names on the board before we leave.","note":"He models the shape, including a clean none, and he pre-commits to parking the solve. The stand-up stays a naming meeting."},"quiz":[{"q":"What is the stand-up actually for?","options":["A full status, so nobody needs another report.","Bonding, through longer personal updates.","The blocker that needs another person, caught early."],"answer":2,"why":"Progress is context, and the blocker is the reason the meeting exists."},{"q":"What are the three slots?","options":["Mood, risks, and a motivational close.","Finished, today, and the name you need if you are blocked.","Yesterday in detail, every task today, and a demo."],"answer":1,"why":"Those three stay inside a minute and make the obstacle visible."},{"q":"A design debate starts with the whole group. What do you do?","options":["Park it for the named people, at a time you set before you adjourn.","Let it run, because energy is a good sign.","Solve it yourself from the chair so it ends."],"answer":0,"why":"The stand-up names the problem and the people, and the solve happens in the smaller huddle."}],"exercise":{"prompt":"Run your own stand-up turn, then give the group one sentence on where problem-solving will happen.","seconds":50,"scaffold":["Finished","Today","Blocker and the name, or no blocker","Where the solve will happen"],"focus":"structure"}},{"id":"m5-chair","module":5,"title":"Chairing and timeboxing","minutes":4,"framework":"Timebox","promise":"You will name the minutes a topic has, park a tangent, and bring the room back to the decision.","focus":"pace","free":false,"cards":[{"kicker":"Why it matters","body":"A meeting without a clock belongs to the most fluent person in it. Chairing is the work of protecting a decision from interesting detours. When you name the time out loud, you give everyone permission to be brief, including the senior person who would otherwise expand."},{"kicker":"Do this","body":"Open with the decision and the minutes it has. At halfway, say what is still unresolved. When a tangent appears, park it on a visible list with a name, and return to the question in the same breath. Close the item when the time ends, even if the talk is enjoyable."},{"kicker":"In the room","body":"Speak a little slower than the fastest person, so the pace of the room drops toward the decision. Call on someone who has not spoken before you call again on someone who has spoken twice. If you also have a view, mark the moment you step out of the chair."},{"kicker":"Avoid","body":"Do not apologise for the clock. The clock is the courtesy. Do not park a point and then forget the park, or people will stop trusting it. If you are close, say the decision and test it."}],"example":{"speaker":"Marcus","role":"project lead","script":"This item has ten minutes, and the decision is the access window. I am parking the staffing point with Ana for a huddle at four, and I am keeping this room on the date. Halfway through, we still have no yes or no on the twelfth of May. I will hear from the two people who have not spoken, and then I will test a decision. Stepping out of the chair, I recommend the twelfth. Back in the chair, I need any dissent now, before the item closes.","note":"He names the box, parks in the same breath, and marks the hat change. The pace of the chair is steadier than the pace of the argument."},"quiz":[{"q":"What do you say when you open an item?","options":["The decision, and the minutes it has.","A welcome, until the room feels relaxed.","The full history, so latecomers catch up."],"answer":0,"why":"A named decision and a named clock give everyone permission to be brief."},{"q":"A useful tangent appears. What is the move?","options":["Explore it, since it might matter more than the agenda.","Park it visibly, with a name, and return to the question immediately.","Ask the group if they would like to change the agenda."],"answer":1,"why":"A park with an owner respects the point without spending the decision's time."},{"q":"You are chairing and you also have a view. How do you handle it?","options":["Argue from the chair, so the view carries the role.","Stay silent, because chairs never have views.","Mark a short step out of the chair, say the view, and step back."],"answer":2,"why":"Separating the hats keeps the clock credible."}],"exercise":{"prompt":"Chair a short item. Open the box, park one tangent, step out of the chair and back, then test the decision.","seconds":60,"scaffold":["Decision and time","The park, with a name","Halfway: what is still unresolved","Your view, with the hat marked","The test of the decision"],"focus":"pace"}},{"id":"m5-disagree","module":5,"title":"Disagree and commit","minutes":5,"framework":"Disagree and commit","promise":"You will state a dissent cleanly, and once the decision is made you will commit to it in the same meeting.","focus":"presence","free":false,"cards":[{"kicker":"Why it matters","body":"Silent disagreement becomes corridor sabotage, and a performed fight becomes a status contest. A professional room needs both halves of the practice. The dissent must be clear enough to change the decision, and the commit must be clear enough that your team will not hear two messages."},{"kicker":"Do this","body":"Say I disagree, then one reason, one risk, and one alternative. Stop, so a decision can actually happen. If it goes against you, say the commit in the same meeting, including that you will not re-argue it in side meetings."},{"kicker":"In the room","body":"Aim the dissent at the decision, and keep your volume where it was. If you are the decision-maker, repeat the dissent in one sentence before you rule. A commit from you sounds like this: I heard the risk, I am still choosing the date, and I own that."},{"kicker":"Avoid","body":"Do not agree out loud and undo it in the corridor. Do not stack five reasons in the hope of wearing the room down. Say the commit as a straight sentence, without a tone that asks the room to feel sorry for you."}],"example":{"speaker":"Elena","role":"product manager","script":"I disagree with opening the German site before the translated flows are signed off. A wrong price string will sit with customers for months, and support cannot unwind it politely. My alternative is a two-week delay and a named reviewer for the strings. That is the whole dissent. If this room chooses to open now, I will run the launch cleanly and I will not re-argue the date with the team. I will also write the risk down, so we can see it if refunds move.","note":"One reason, one alternative, a stop, and a commit that includes the side-meeting clause. The volume stays level."},"quiz":[{"q":"What does a useful dissent contain?","options":["Every reason you can think of, delivered with heat.","One reason, one risk, and one alternative, then a stop.","A hint, so you stay liked if you turn out to be wrong."],"answer":1,"why":"A compact dissent can change a decision, and a flood of reasons becomes a contest."},{"q":"The decision goes against you. What do you say in the same meeting?","options":["Nothing, and then you explain your real view to the team later.","Fine, in a tone that leaves the door open.","The decision, your support, and a refusal to re-argue it in side meetings."],"answer":2,"why":"The commit is a public instruction to your future self and to your team."},{"q":"You are deciding, and someone dissents. What shows you heard it?","options":["Repeat the dissent in one sentence, then rule and own the ruling.","Thank them warmly and move on without restating it.","Ask them to make the dissent again, more briefly."],"answer":0,"why":"Restating the risk proves it landed, and the ruling then has somewhere to stand."}],"exercise":{"prompt":"Disagree with a decision you know well. Give one reason and one alternative, then commit as if you had lost.","seconds":45,"scaffold":["I disagree","One reason and one risk","My alternative","The commit, including side meetings"],"focus":"presence"}},{"id":"m5-quiet","module":5,"title":"Getting quiet people to talk","minutes":4,"framework":"Invitation pause","promise":"You will leave a real pause and offer a specific invitation so a quieter person can enter.","focus":"pauses","free":false,"cards":[{"kicker":"Why it matters","body":"Silence in a meeting is the only door some people will use. If you fill every gap, you select for speed and volume, and you miss the person who has the risk written down. Pausing is a facilitation skill, not a personality trait."},{"kicker":"Do this","body":"Ask a question one person can answer, then count two beats before you speak again. Name what they saw, so the door is narrow enough to walk through. If they need a smaller door, offer a choice of two, and keep your mouth closed while they choose."},{"kicker":"In the room","body":"Protect the pause from helpful colleagues with a light line: let us give that a second. When the person speaks, repeat their point in their strength and put that version where it will be seen. Do not sand it into your own opinion."},{"kicker":"Avoid","body":"Do not call someone quiet in public, and do not ask what does everyone think and then stare. That is a stage, not an invitation. For a large topic, send the question before the meeting and use the live pause for the short version."}],"example":{"speaker":"Priya","role":"team lead","script":"Ana, you watched the first hour of the new on-call rota, and I want the failure you saw in that hour. I am leaving space for it, and you can start with the first page if that is easier. Thank you. I am writing it as you said it: the page named a job we had already retired, and you had to check the log to be sure. I want the room to respond to that wording. We will not move on until Ana's version is the version on the board.","note":"The invitation names a person and a narrow window, and the pause is built into the wording. The board keeps her sentence rather than a polished rewrite."},"quiz":[{"q":"What makes a pause an invitation rather than a blank?","options":["A named person, a question they can answer, and two beats of real silence.","What does everyone think, followed by you answering it.","A joke about the room being quiet today."],"answer":0,"why":"A specific question gives a door, and an open question plus your own voice closes it."},{"q":"Someone jumps in to cover the silence. What do you say?","options":["Nothing, because any intervention is rude.","Let us move on, then.","Let us give that a second."],"answer":2,"why":"A light protection of the pause tells the room the silence was intentional."},{"q":"How do you handle the point once it has been made?","options":["Smooth it into a version the room will find easier.","Repeat it in their strength, and put that version where it will be seen.","Thank them and return to the previous speaker's idea."],"answer":1,"why":"Their wording is the contribution, and a rewrite takes it back."}],"exercise":{"prompt":"Invite one specific person into a topic. Ask, leave two beats, and say their point back without sanding it down. You can play both parts.","seconds":40,"scaffold":["Their name, and what they saw","A narrow question","Two beats","Their point, in their words","The board, unchanged"],"focus":"pauses"}},{"id":"m5-close","module":5,"title":"Closing with owners and dates","minutes":4,"framework":"Owner and date","promise":"You will end a meeting with an owner, a date, and a sentence everyone could repeat.","focus":"structure","free":false,"cards":[{"kicker":"Why it matters","body":"Meetings fail in the last ninety seconds, when people pack up and the actions stay implied. An implied action belongs to nobody. A close with a name and a date can be checked without calling another meeting to discover what was meant."},{"kicker":"Do this","body":"Reserve the last two minutes and use them for nothing else. Read decisions in short sentences, then actions as name, verb, date. Ask the named person to confirm in a word. End on the sentence you want repeated in the corridor."},{"kicker":"In the room","body":"Write the close in the chat or on the board before you say goodbye, so remote people and latecomers can see it. An action with no date is a wish: date it or drop it. If the owner is absent, the person in the room who will tell them becomes the owner of that telling, with a date."},{"kicker":"Avoid","body":"Do not end on great discussion and a list of themes. Themes do not move work. Do not invent an owner for someone who did not agree, and do not open a new topic because the close reminded you of one."}],"example":{"speaker":"Marcus","role":"project lead","script":"We are at the close, and I am reading only decisions and actions. Decision: the access window is the twelfth of May. Action: Ana confirms the clinical trainer by Wednesday. Ana, is Wednesday yours? Action: I will send the one-page brief today, and I own the note to the site. The sentence I want repeated is this: we install on the twelfth, with training after the drug round. Anything else goes on the next agenda, which I will send tomorrow morning.","note":"Name, verb, and date, plus a spoken confirm and a corridor sentence. A new topic is pushed to a dated agenda rather than squeezed into the goodbye."},"quiz":[{"q":"What is the minimum a real action contains?","options":["A theme and a sense of urgency.","A discussion and a slide number.","A name, a verb, and a date."],"answer":2,"why":"Without all three, the action cannot be checked, and it will be relitigated next time."},{"q":"The right owner is not in the room. What do you do?","options":["Name the person present who will tell them, and date that telling.","Assign it anyway, and assume they will read the notes.","Drop the whole decision until they can attend."],"answer":0,"why":"The owner in the room is the person who carries the message, on a date."},{"q":"How should the meeting actually end?","options":["On a warm comment about the quality of the discussion.","On the sentence you want repeated in the corridor.","On a new topic that surfaced during the close."],"answer":1,"why":"The last sentence is the one that travels, so choose it on purpose."}],"exercise":{"prompt":"Close a meeting you were in this week. Decisions first, then name, verb, and date, then the corridor sentence.","seconds":55,"scaffold":["The decision","Name, verb, date","The confirm","The sentence to repeat","The park, if you need one"],"focus":"structure"}},{"id":"m6-sbii","module":6,"title":"SBI(I) feedback","minutes":4,"framework":"SBI","promise":"You will give feedback as a situation, a behaviour, an impact, and one invitation to continue or to change.","focus":"structure","free":true,"cards":[{"kicker":"Why it matters","body":"Vague feedback feels polite and changes nothing. Be more proactive leaves the person guessing which hour of which day you meant. SBI ties the note to a moment they can remember, and the invitation tells them what to repeat or what to do differently next time."},{"kicker":"Do this","body":"Name the time and place, describe what a camera or a transcript would show, and leave any guess about motive out of it. Say the effect on the work, then make one request about the next time the situation appears. A verdict such as careless is not a behaviour, so it does not belong in that second line."},{"kicker":"In the room","body":"Give a correction in private, and keep it to one behaviour. Give reinforcement close to the event, in public only if the person is comfortable being named. Then stop. The silence is their turn."},{"kicker":"Avoid","body":"Do not hide the request between two compliments they will learn to ignore. Do not diagnose a personality or a generation. If you fill the silence after the invitation, you have turned the feedback into a speech about yourself."}],"example":{"speaker":"Elena","role":"product manager","script":"In Monday's demo, when the customer asked what happens on a failed payment, you showed the happy path and moved on. The impact is that they left believing the failure case was handled, and I had to correct that in the follow-up note. I want the next demo to show the failed payment before anyone asks. You do not need a longer demo. You need the unhappy path in the first three minutes. I am happy to rehearse that opening with you before Thursday.","note":"The behaviour is observable, and the invitation is a single change plus a rehearsal. There is no comment on attitude."},"quiz":[{"q":"What counts as behaviour in SBI?","options":["Your theory about why they did it.","What a camera or a transcript would show.","A trait, such as careless or proactive."],"answer":1,"why":"Observable behaviour can be repeated or changed, and a motive is a guess."},{"q":"What is the invitation?","options":["One request about the next time this situation appears.","Praise wrapped around the hard point so it lands softly.","A question about their personality."],"answer":0,"why":"The invitation turns the impact into a next action the person can attempt."},{"q":"After the four parts, what do you do?","options":["Add two more examples so they feel the pattern.","Explain your own week at length.","Stop, and leave the next turn to them."],"answer":2,"why":"The silence hands the feedback over, and filling it takes it back."}],"exercise":{"prompt":"Give one piece of SBI feedback, reinforcing or corrective, about a real moment. Stop after the invitation.","seconds":60,"scaffold":["Situation: time and place","Behaviour a camera would see","Impact on the work","One invitation"],"focus":"structure"}},{"id":"m6-receive","module":6,"title":"Receiving feedback","minutes":5,"framework":"Listen, then ask","promise":"You will hear a hard note without building a defence, and you will leave with one clarifying question.","focus":"presence","free":false,"cards":[{"kicker":"Why it matters","body":"The first minute after hard feedback is when people lose the content. They build a case, they explain context the giver already has, or they apologise in general and hear nothing specific. Your face, your pace, and your silence decide whether that person will be honest with you again."},{"kicker":"Do this","body":"Write the note down as they say it, which also keeps your mouth busy. Thank them for the specific part, not for the feedback in the abstract. Ask one question that sharpens the behaviour or the invitation, and then stop."},{"kicker":"In the room","body":"If they have a fact wrong, correct it in one sentence after you have understood the impact, and do not add a closing argument. If you need time, say you will come back tomorrow with what you will change. Then come back."},{"kicker":"Avoid","body":"Do not lead with your intention. It can wait, and often it does not need to be said. Do not punish the messenger with a colder tone for the rest of the week. Do not agree instantly to a vague request you cannot perform."}],"example":{"speaker":"James","role":"plant engineer","script":"I am writing this down, and I want the version you saw. You are saying the downtime sat in paragraph four, so the director heard the recovery and missed the forty minutes. Is the behaviour the buried number, or the fact that the cause was still a guess? I can see how that lands in a board pack. The sensor was replaced before dawn, and that fact can stay in a later sentence. I will bring a rewritten opening tomorrow, and I will not spend this conversation on how busy the night was.","note":"Notes, a clarifying question, and a fact that does not become a defence. He sets a time to return with the change."},"quiz":[{"q":"What is the first useful move when a hard note arrives?","options":["Explain the context they may have missed.","Apologise in general until the moment passes.","Write it down, and let them finish."],"answer":2,"why":"Notes keep you present and give you their words rather than your defence."},{"q":"What kind of question helps?","options":["Why would you think that about me?","One question that pins down the behaviour or the invitation.","A series of challenges to their evidence."],"answer":1,"why":"A sharper target is something you can change, and a trial of the giver is not."},{"q":"They have a fact wrong. How do you handle it?","options":["One sentence of correction, after you have understood the impact, with no closing speech.","A full timeline, so the record is fair.","Silence forever, because any fact sounds like a defence."],"answer":0,"why":"A single fact keeps the record clean without turning the moment into a case."}],"exercise":{"prompt":"Receive a hard note. Do not defend. Reflect the behaviour, ask one clarifying question, and set a time to come back.","seconds":50,"scaffold":["Notes, mouth closed","The behaviour in their words","One clarifying question","When you will return with the change"],"focus":"presence"}},{"id":"m6-recognition","module":6,"title":"Recognition that motivates","minutes":3,"framework":"Specific recognition","promise":"You will praise a specific behaviour and its effect, so the person knows what to repeat.","focus":"presence","free":false,"cards":[{"kicker":"Why it matters","body":"Great job feels kind and teaches nothing. People repeat what you name. A trait tells them you like them today. An act, plus the effect it had, tells them what the work looks like when it is good, and it tells everyone who overhears."},{"kicker":"Do this","body":"Use the same shape as a correction, aimed at reinforcement. Situation, behaviour, impact, and an invitation to keep it. Deliver it close to the event, while the scene is still easy to recall. Match the size of the praise to the size of the act."},{"kicker":"In the room","body":"A public thank-you for a visible contribution helps a standard spread. A private note works better for someone who dislikes a spotlight, and the content stays just as specific. Look at them for the behaviour, and look at the room if you want the standard copied."},{"kicker":"Avoid","body":"Do not add a correction on the end, because a trailing but deletes the recognition people just heard. Praise the choice that put the hours on the right risk, rather than the hours themselves. Specific and plain beats a gush."}],"example":{"speaker":"Priya","role":"team lead","script":"In yesterday's incident note, you put the customer impact in the first line and the timeline underneath. The on-call engineer from the other squad used that line to decide what not to roll back. That saved a second outage and it showed the rest of us what an incident note is for. Please keep leading with the impact, including on the quiet nights. I am saying this here so the standard is shared. I do not have a second note hidden behind it.","note":"Act, effect, and an invitation to repeat it. She refuses the trailing but, and the praise is the size of the act."},"quiz":[{"q":"What does useful recognition name?","options":["A behaviour, and the effect it had.","A trait, such as being a star.","The number of hours they stayed."],"answer":0,"why":"Named acts get repeated, and traits and hours do not tell anyone what to do tomorrow."},{"q":"When should you give it?","options":["At the annual review, so it feels official.","Close to the event, while the scene is easy to recall.","Only when you also have a correction ready."],"answer":1,"why":"Proximity lets the person feel which act you mean."},{"q":"How do you stop the praise being deleted?","options":["Add a small improvement at the end, so it stays balanced.","Praise three other people in the same breath.","End on the invitation to repeat it, with no but."],"answer":2,"why":"A trailing correction teaches people to wait for the real message."}],"exercise":{"prompt":"Praise someone specific from your real week. Situation, act, effect, and an invitation to keep doing it.","seconds":45,"scaffold":["When and where","The act a camera saw","The effect on the work","The invitation to repeat it"],"focus":"presence"}},{"id":"m6-difficult","module":6,"title":"Difficult conversations","minutes":5,"framework":"Issue, impact, next step","promise":"You will open a hard conversation with the issue, the impact, and a shared next step, and you will leave the hedges out.","focus":"fillers","free":false,"cards":[{"kicker":"Why it matters","body":"Difficult conversations rot when they start with a long warm-up. The other person hears the warmth, relaxes, and then feels ambushed. A clean opening is kinder, and it keeps just, a bit, and sorry to be a pain from shrinking the issue until nobody can act."},{"kicker":"Do this","body":"Name the topic in the invite. Open with the issue a camera would see, the impact on the work, and the next step you want to build together. Then ask for their account before you propose the fix. One issue per meeting."},{"kicker":"In the room","body":"Keep the pace at conversation speed. A raced opening sounds like anger even when the words are fair. If they match heat with heat, return to the impact sentence rather than to a character review. Sit where you can both see the notes."},{"kicker":"Avoid","body":"Do not open with I feel like you always. Always is a trap, and a feeling-word is a poor container for a missed check. Do not bring an audience, and do not leave without a next step, even if that step is a date to continue."}],"example":{"speaker":"James","role":"plant engineer","script":"I asked for this half hour because of the lock-out note, and I want to start with the issue. The contractor started on the filler twice this month without the note signed. The impact is that the shift lead cannot tell a visitor the line was safe to touch. I want us to leave with one check we both trust before anyone opens a guard. I would like your account of how those two jobs started, before I propose the check. I am going to stay on this issue until we have that.","note":"The topic was named in advance, the opening has no warm-up, and the hedges are absent. He asks for their account before the fix."},"quiz":[{"q":"What belongs in the first minute of a hard conversation?","options":["A long appreciation, so they feel safe before the point.","The issue, the impact, and the next step you want to build.","Every example you have saved since January."],"answer":1,"why":"A clean opening respects their time and prevents the ambush of a buried point."},{"q":"Which line keeps the conversation on the work?","options":["I feel like you always rush.","Everyone else has noticed this too.","The note was unsigned on two jobs, and the shift lead could not show the line was safe."],"answer":2,"why":"Observable impact can be discussed, and always plus a chorus of allies turns it into a trial."},{"q":"They push back hard. Where do you return?","options":["To the impact sentence, at a steady pace.","To a review of their attitude.","To a softer version of the issue that no longer needs a fix."],"answer":0,"why":"The impact is the shared ground, and character talk raises the heat without moving the work."}],"exercise":{"prompt":"Open a difficult conversation you have been postponing. Issue, impact, the next step you want, then a question that invites their account.","seconds":70,"scaffold":["The topic, named plainly","The issue a camera would see","The impact","The next step you want","Their account, invited"],"focus":"fillers"}},{"id":"m7-interests","module":7,"title":"Interests versus positions","minutes":4,"framework":"Interests versus positions","promise":"You will ask what the other side needs underneath the position they have stated.","focus":"structure","free":true,"cards":[{"kicker":"Why it matters","body":"A position is a demand: this price, this date, this vendor. An interest is the need that demand is trying to serve: uptime, a quiet ward, a number a finance partner can defend. Arguing positions can only split the difference. Finding interests often solves both sides."},{"kicker":"Do this","body":"State their position fairly, in one sentence, so they know you heard the demand. Ask one interest question, and listen for the constraint under the answer. Share one interest of your own at the same altitude before you offer a package."},{"kicker":"In the room","body":"Write the interest down in their words. Keep the first options small and reversible, two packages that meet the need in different ways. The pause after the question is where the real need shows up."},{"kicker":"Avoid","body":"Do not use the interest question as a trick to expose them. Do not translate their words into a flattering version they did not say. Do not jump to your answer in the same breath as the question."}],"example":{"speaker":"Marcus","role":"project lead","script":"You want the mast filing submitted this week. That is the position, and I have it. What does a filing this week protect for you? I am asking because my interest is a neighbour letter we can defend if someone challenges the site. If your interest is a grant deadline, we can file the mast and send the letter the same day, with counsel on the copy. If your interest is a board slide, we can show the board the plan and the open letter. I will write your interest in your words before I offer a package.","note":"He restates the position, asks one interest question, and puts his own interest at the same level. The packages stay conditional until he has heard the answer."},"quiz":[{"q":"What is an interest, as distinct from a position?","options":["The need the demand is trying to serve.","The opening number in a negotiation.","A softer wording of the same demand."],"answer":0,"why":"Positions are the demands, and interests are the reasons those demands exist."},{"q":"What do you say first?","options":["Your counter-demand, so you do not look soft.","A package of options, to show energy.","Their position, fairly, then one question about the need underneath."],"answer":2,"why":"A fair restatement earns the question, and a counter-demand starts a tug of war."},{"q":"When do you offer a package?","options":["In the same breath as the question, to save time.","After you have heard their interest and stated one of your own.","Only after they accept your original position."],"answer":1,"why":"Options that arrive before the need are just new positions."}],"exercise":{"prompt":"Take a demand you have heard at work. Restate it, ask for the interest, and share one interest of your own.","seconds":55,"scaffold":["Their position, in their words","One interest question","Your interest, at the same level","A pause","One option, conditional on what you hear"],"focus":"structure"}},{"id":"m7-batna","module":7,"title":"BATNA","minutes":5,"framework":"BATNA","promise":"You will know your walk-away option before you sit down, and you will be able to name it without turning it into a threat.","focus":"structure","free":false,"cards":[{"kicker":"Why it matters","body":"BATNA is your best alternative to a negotiated agreement: what you will actually do if this deal does not happen. Without it, every pressure in the room feels binding, including pressure you invented. With a real alternative, you can listen, because a no has somewhere to go."},{"kicker":"Do this","body":"Before the meeting, write the alternative in concrete terms: who, when, and what it costs you. Write the moment you would take it, and the sentence you will use, short of any sneer. Practise that sentence at the same volume as the rest of your talk."},{"kicker":"In the room","body":"Open on the interest, and let the alternative sit while the conversation is still producing value. If you need it, say it once, then pause. If they improve the deal past your alternative, say so and stay."},{"kicker":"Avoid","body":"Do not bluff an alternative you do not have. A practical question will drop it on the floor. Do not describe their options in a mocking way, and do not keep a stale alternative after the facts have changed."}],"example":{"speaker":"James","role":"plant engineer","script":"I want on-site cover inside four hours, because the night shift cannot wait on a ticket queue. That is the interest I came in with. If this contract cannot include that cover, my alternative is the second firm, who start in nine weeks at last year's rate. I would rather stay with you, and I am saying the alternative so the choice is clear. I will not repeat it as a threat. If you can meet the four hours inside this term, I will close with you today.","note":"Interest first, the alternative once, and a condition for staying. There is no sneer and no bluff."},"quiz":[{"q":"What is a BATNA?","options":["The first number you say, so you anchor the talk.","A threat you hope you will never have to explain.","The real alternative you will take if this agreement does not happen."],"answer":2,"why":"It has to be something you can actually do, on a real timeline."},{"q":"When do you put the alternative on the table?","options":["After the interest is clear, and only if the deal is not beating it.","In the first minute, so they know you are serious.","Never, because naming an alternative is always rude."],"answer":0,"why":"An early alternative sounds like a threat, and a single later statement sounds like information."},{"q":"They ask a practical question about your alternative. What does that test?","options":["Your nerve.","Whether the alternative is real.","Your loyalty to them."],"answer":1,"why":"A true alternative survives a practical question, and a bluff does not."}],"exercise":{"prompt":"State an interest, then your real alternative, once, at an ordinary volume. Include the condition under which you would stay.","seconds":60,"scaffold":["The interest","The alternative: who, when, and cost","The sentence, said once","The condition for staying"],"focus":"structure"}},{"id":"m7-anchor","module":7,"title":"Anchoring and concessions","minutes":4,"framework":"Anchor and concession","promise":"You will set a first number with a reason, then concede in steps you decided before the meeting.","focus":"pace","free":false,"cards":[{"kicker":"Why it matters","body":"The first serious number pulls the rest of the conversation toward it. A number with no reason is a dare, and a number you cannot explain will be walked back in public. Pace matters: a fast pattern of concessions tells them every silence will produce a discount."},{"kicker":"Do this","body":"Open at the ambitious end of what you can defend, with one reason their boss could repeat. Then wait. Plan three concessions, each smaller than the last, each traded for something you named. Say a concession slowly, and do not fill the silence after it."},{"kicker":"In the room","body":"If they flinch, repeat the reason rather than rescuing them with an instant better offer. If their number arrives first and it is far from yours, restate your anchor instead of splitting the gap in the first minute. Write the trades down so you do not concede the same thing twice."},{"kicker":"Avoid","body":"Do not concede because the silence feels rude, and do not apologise for the opening. Do not make the first concession the largest. A big first drop tells them the anchor was theatre."}],"example":{"speaker":"Priya","role":"team lead","script":"I am asking for a twelve-month renewal at last year's rate, because the scope has not grown and the night cover has. I can move by a small step if the on-site response stays inside four hours and the term stays one year. A second move, smaller than the first, is available if the spare unit is included in that rate. I am not going to split the difference this morning. I will wait for your number, and I will write any trade down before I agree it. The reason I will repeat to my own director is the unchanged scope.","note":"The anchor has a reason a director can hear, and the concessions shrink and buy something. She treats the silence as part of the price."},"quiz":[{"q":"What makes an anchor survive contact with the other side?","options":["How ambitious it is, regardless of proof.","A reason their boss could repeat, at the ambitious end of what you can defend.","An apology that shows you are flexible."],"answer":1,"why":"A reasoned number holds, and a dare gets walked back and hands them the anchor."},{"q":"How should concessions be shaped?","options":["Planned, each smaller than the last, each traded for a named thing.","Largest first, to build goodwill.","Invented whenever a silence appears."],"answer":0,"why":"Shrinking, traded steps teach them that movement has a price."},{"q":"They go quiet after your number. What do you do?","options":["Offer a quick discount to ease the moment.","Restate the number with a joke about being bad at this.","Wait, and let the reason stand."],"answer":2,"why":"The pause is part of the anchor, and filling it spends money."}],"exercise":{"prompt":"Put down an anchor for a real negotiation, with a reason, one planned concession, and a silence you do not fill.","seconds":50,"scaffold":["The number","The reason a boss could repeat","A pause","One smaller concession, traded","What you will not split today"],"focus":"pace"}},{"id":"m7-empathy","module":7,"title":"Tactical empathy and labelling","minutes":4,"framework":"Labelling","promise":"You will name the pressure you hear, in a short label, before you propose anything.","focus":"presence","free":false,"cards":[{"kicker":"Why it matters","body":"People do not hear a proposal while they are busy being unseen. A label names the pressure without judging it and without solving it. Done well, it lowers the temperature enough for an interest to surface. It is a professional move, not a counselling session."},{"kicker":"Do this","body":"Start with it sounds like or it seems like, and keep the label to one clause. Then stop. Do not add but and your point. If you are wrong, they will correct you, and the correction is useful."},{"kicker":"In the room","body":"Label the pressure, not the personality. It sounds like headcount is the worry is usable. You are being difficult is a verdict. Match your volume to theirs or a little under, because a bright, fast label sounds sarcastic."},{"kicker":"Avoid","body":"Do not label and solve in one breath, and do not tell them they are wrong to feel the pressure. It sounds like you are stressed, so you should accept the date, is a trap. One label, one pause, then a question."}],"example":{"speaker":"James","role":"plant engineer","script":"It sounds like maintenance is wary of being blamed for a stop they did not cause. I am going to leave that there. It seems like the night shift wants a check they can finish before the line starts, not a longer form. I want to understand which of those two pressures is heavier this week. If it is the blame, we separate the sensor history from the shift sheet. If it is the check, we shorten the sheet tonight and talk about history tomorrow. I am not offering a package until I hear which one I misread.","note":"Two short labels, with room to be corrected. He withholds the package until the heavier pressure is named."},"quiz":[{"q":"What is a label in this sense?","options":["A diagnosis of their personality.","A solution, phrased softly.","A short guess about the pressure, which they are free to correct."],"answer":2,"why":"A label names the weather in the room, and it does not treat the person or close the deal."},{"q":"What do you do immediately after the label?","options":["Add your proposal, joined with but.","Stop, and let them confirm or correct it.","Explain that you learned the move on a course."],"answer":1,"why":"The pause is what makes the label feel true, and a but spends it."},{"q":"Which line is a label rather than a verdict?","options":["It sounds like the four-hour cover is the part your boss will question.","You are being inflexible about the term.","It sounds like you are stressed, so take the date."],"answer":0,"why":"It names a pressure and leaves room, while the other two judge or steer."}],"exercise":{"prompt":"Label the pressure in a real disagreement. Do it twice if the first label is off. Do not solve it inside the window.","seconds":45,"scaffold":["It sounds like","A pause","A correction, if they would offer one","A question about which pressure is heavier","No proposal yet"],"focus":"presence"}},{"id":"m7-no","module":7,"title":"Saying no gracefully","minutes":4,"framework":"A useful no","promise":"You will decline a request with a reason, a boundary, and one alternative you can actually keep.","focus":"fillers","free":false,"cards":[{"kicker":"Why it matters","body":"A muddy no creates a second meeting. Let me see and I will try feel kinder today and cost more by Friday, when someone has planned around a yes you never gave. A clear no protects work you already committed, and it lets the asker go elsewhere in time."},{"kicker":"Do this","body":"Acknowledge the request in a few words, then say no in the same opening. Give one reason tied to a commitment they can understand. State the boundary as a fact about your plan, and offer one real alternative: a later date, a smaller slice, or a different owner."},{"kicker":"In the room","body":"Leave just, sorry sorry, and I feel terrible but out of the sentence. One sorry is human if you caused the mess. A chain of them makes the no sound negotiable. Match the pace to an ordinary sentence."},{"kicker":"Avoid","body":"Do not invent a policy, and do not blame a ghost such as leadership would never allow it. Do not offer an alternative you will resent. Do not say circle back soon unless you name the week."}],"example":{"speaker":"Marcus","role":"project lead","script":"I cannot add the second school site to this month's rollout. The year-seven delivery already owns the crew, and splitting them will miss the eighth. The boundary is this month, not the idea of the second site. I can put that site on the agenda for the first week of next month, with a storage check beside it. If the head teacher cannot move, Sam can scope a holding note, and I will review it for half an hour on the twentieth. I will not say I will try, because that would be a yes the crew cannot keep.","note":"The no is in the first sentence, with one reason, a boundary, and a real alternative that has a date. He refuses the muddy middle out loud."},"quiz":[{"q":"Where does the no belong?","options":["In the opening, after a brief acknowledgement.","After a long explanation, so they feel the effort.","In a hint, so the relationship stays easy."],"answer":0,"why":"An early no lets them plan, and a delayed no wastes the week."},{"q":"What makes an alternative useful?","options":["It sounds generous, even if you hope they forget it.","It is real: a date, a smaller slice, or a named other owner.","It pushes the request to an unnamed leader."],"answer":1,"why":"A real alternative respects the asker, and a ghost alternative creates a second chase."},{"q":"Which phrase turns a no back into a maybe?","options":["The year-seven delivery owns the crew.","I can review a holding note on the twentieth.","Let me try, and we will circle back."],"answer":2,"why":"I will try is a yes the calendar has not agreed to."}],"exercise":{"prompt":"Say no to a real request. Acknowledge it, decline it, give one reason, and offer one alternative with a date.","seconds":40,"scaffold":["The request, named","No, in the opening","One reason","The boundary","A real alternative with a date"],"focus":"fillers"}}]`),g=[{id:"cap-vision",title:"3-minute team vision",minutes:8,brief:"You lead a team that has spent the year reacting. People can describe the queue. They cannot describe a good Tuesday. You have three minutes at the monthly all-hands. Two new people are in the room, plus a finance partner who funds the headcount, and a director who has stopped believing slogans. Give them a picture they can use when they plan next week. Name who you serve and the friction that person still feels. Describe one scene that will look different because of how this team works: a handover, a release, a clinic morning, or a line start. Say one thing you will stop doing. Close with a sentence the room can repeat to someone who missed the meeting, and name what you need from them this quarter. Stay inside three minutes. If the ending starts to rush, slow down and finish that last sentence. A finished scene is the whole job.",scaffold:["Who we serve, and the friction they still feel","One working scene that looks different","The standard I will protect","What we will stop doing","The sentence to repeat, and the ask this quarter"],seconds:180,rubric:["Opens on who the team serves, in concrete language","Gives one scene a person could recognise on a working day","Names something the team will stop","Closes with a repeatable sentence and a quarterly ask, inside the time"],focus:"presence"},{id:"cap-board",title:"Mock board update",minutes:8,brief:"The board has given you three minutes. They want the decision, the risk, and the ask. The project is six weeks behind the date you set in March, and spend is still inside the envelope. A supplier in Germany missed a firmware drop. A safety review on the Bilbao line added work the plan never held. You can give back four of the six weeks if the board accepts a narrower first release. You will not promise nights and weekends as a recovery plan. Open with the new date and the reason. Name the option you recommend and the option you refused, including why the refused option is not free. State the risk the board still accepts if it chooses the narrow release, and what the second release will carry. Ask for a decision before you sit down: approve the narrow release, or accept the full slip. Leave the chart in the appendix. Speak as the owner of the outcome, including the part that moved.",scaffold:["The date now, and why it moved","The option I recommend","The option I will not pretend is free","The risk that sits with the board","The decision I am asking for today"],seconds:180,rubric:["The first sentence contains the new date and the cause","Recommends one option and names the option refused","States the risk the board still owns","Asks for a decision and stops, without a tour of the chart"],focus:"structure"},{id:"cap-negotiation",title:"Negotiation roleplay",minutes:8,brief:"You are renewing support for a line that stopped twice last quarter. The vendor opened eighteen percent above last year's rate and tied any discount to a three-year lock. Your alternative is a second firm that can start in nine weeks at last year's rate, with a weaker on-site clause. You would rather keep this vendor, because their engineers already know the night shift and the controls. Open on the shared interest: uptime on the night shift, not a percentage. Put a number down with a reason tied to last year's scope. If they mention headcount, travel, or a target from their own leadership, label that pressure in a short phrase and wait. Concede one item you chose before the meeting, slowly, and ask for the on-site response time in exchange. If they will not leave the three-year lock, state the alternative in a calm sentence and let the silence sit. Close with a next step that has a date: agreement today, or the day you will instruct the other firm.",scaffold:["The shared interest, before any percentage","My number, with a reason","A label if I hear pressure on their side","One planned concession, traded for response time","The alternative, said once, and a dated next step"],seconds:180,rubric:["Opens on uptime or another shared interest, not on a complaint","Puts down a reasoned number and waits","Labels pressure without turning it into a speech","States a real alternative once, and closes with a dated next step"],focus:"structure"}],b={modules:y,lessons:w,capstones:g},v=[{id:1,title:"Fundamentos de la voz",blurb:"Aire, resonancia, boca, ritmo, tono y una voz que aguanta la semana. Si esto falla, el mejor argumento se queda en la mesa."},{id:2,title:"Presencia",blurb:"Presencia es terminar la frase y poder esperar. Calma, lenguaje que cierra, cuerpo en la cámara y unos primeros segundos que no piden perdón."},{id:3,title:"Mensajes claros",blurb:"BLUF, pirámide, SCQA, PREP y la regla de tres. También cómo contar un dato o un fallo técnico sin humo y sin manual."},{id:4,title:"Relato",blurb:"Un relato de trabajo tiene espinazo, nombra a quien hizo el trabajo y admite un fallo solo si deja un cambio. La visión se puede repetir el lunes."},{id:5,title:"Reuniones",blurb:"La reunión corta, el reloj de quien preside, el desacuerdo dicho una vez y el silencio que deja hablar. Se sale con nombre y fecha."},{id:6,title:"Feedback",blurb:"SBI para el comentario que corrige y para el que quieres que se repita. Recibir sin defenderte a la primera y no aplazar la conversación incómoda."},{id:7,title:"Influencia",blurb:"Intereses antes que posturas, una alternativa real si no hay acuerdo, un número que se sostiene y un no que no cierra la puerta."}],k=JSON.parse('[{"id":"m1-breath","module":1,"title":"Apoyo del aire","minutes":4,"framework":"Apoyo","promise":"Vas a llegar a la fecha y al no con la voz todavía entera, sin apretar la garganta.","focus":"breath","free":true,"cards":[{"kicker":"Por qué importa","body":"La fecha, el nombre y el no suelen ir al final, que es donde el aire se acaba. Si la voz se apaga ahí, la sala se queda con el preámbulo y pierde el encargo. Hablar con apoyo es un oficio, no un truco de escenario."},{"kicker":"Haz esto","body":"Deja los hombros quietos y el cuello largo. El aire baja: se mueve el abdomen y se abren las costillas, sin subir el pecho en cada frase. Respira en la coma que marcaste, no cuando el susto te corta la cifra por la mitad."},{"kicker":"En la sala","body":"Pon una barra en la nota justo antes del dato y toma aire ahí. Di el verbo y la cifra en el mismo aire. Si notas que te apagas, para, llena de nuevo y repite solo el final."},{"kicker":"Evita","body":"No levantes los hombros para buscar aire: se ve y te cansas antes. No hables hasta quedarte vacío y luego tomes aire con un golpe que se oye. No susurres la última palabra para parecer suave: el final es lo que hay que hacer."}],"example":{"speaker":"Ane","role":"líder de equipo","script":"El informe de incidencias pasa al miércoles. Dirección se reúne el jueves y un texto del viernes siempre llega tarde. Esta semana es una página, con una cifra y tres líneas debajo. Yo leo las dos primeras entregas, para que el cambio no sea una trampa. Si el miércoles se te cruza con un cliente, dímelo hoy y no el martes por la noche. La fecha nueva es el miércoles a las tres.","note":"La fecha va al final y se oye entera. Ane no empuja la garganta para llegar a «las tres»: el aire ya estaba tomado."},"quiz":[{"q":"¿Dónde te hace falta el aire de verdad?","options":["En el saludo, que es lo que la gente recuerda.","En la última palabra: la fecha, el nombre o el no.","En una inspiración enorme al empezar, y luego ya no respiras."],"answer":1,"why":"La sala se lleva el final. Si ahí se apaga la voz, el encargo no llega."},{"q":"¿Cómo es una toma de aire útil a mitad de frase?","options":["Baja y silenciosa, con los hombros quietos, en una coma que elegiste.","Levantando los hombros cada tres palabras para que se note el esfuerzo.","Un golpe audible justo encima de la cifra, para ganar tiempo."],"answer":0,"why":"El apoyo bajo llega hasta el final de la frase. El hombro alto se ve en la mesa y en la cámara, y no alarga la frase."},{"q":"La voz se te cae al decir la fecha. ¿Qué haces?","options":["Empujas desde la garganta para terminar como sea.","Bajas a un susurro para no parecer brusco.","Paras, tomas aire y repites solo el final, audible."],"answer":2,"why":"Un final repetido con aire nuevo se entiende. Empujar el resto de voz solo añade esfuerzo."}],"exercise":{"prompt":"Cuenta un cambio de fecha de tu semana. La última palabra de cada frase tiene que oírse tan clara como la primera.","seconds":45,"scaffold":["Qué cambia","Por qué, en una frase","La fecha, con aire todavía","Un segundo en silencio"],"focus":"breath"}},{"id":"m1-resonance","module":1,"title":"Resonancia y proyección","minutes":4,"framework":"Resonancia","promise":"Vas a llegar al fondo de la sala, o de la nave, sin gritar y sin quedarte en la garganta.","focus":"volume","free":true,"cards":[{"kicker":"Por qué importa","body":"Gritar no es proyectar: el grito cansa y suena a enfado aunque no lo haya. La voz que llega usa aire y un sitio donde resonar, en el pecho y en la cara. Quien está al fondo tiene el mismo derecho al parte que quien está a tu lado."},{"kicker":"Haz esto","body":"Zumbar un momento en una nota cómoda, con los labios cerrados, hasta notar vibración en la cara. Abre a la frase sin perder ese zumbido. Apunta la voz a una persona concreta del fondo, como si la frase fuera solo para ella."},{"kicker":"En la nave","body":"Si hay ruido de máquina, acércate o usa el micrófono antes de subir el volumen a pulso. Una frase más corta llega más lejos que un párrafo gritado. La última palabra lleva el mismo cuerpo de voz que la primera."},{"kicker":"Evita","body":"No hables solo para la primera fila y des por hecho que el resto preguntará. No subas el tono cuando quieres más volumen: agudo no es lejos. No aprietes la mandíbula para «sacar» la voz: la cierras."}],"example":{"speaker":"Mateo","role":"líder de equipo","script":"El parte de hoy cabe en cuatro ideas, y el fondo de la nave también tiene que oírlas. A las once paramos diez minutos para cambiar un sensor en la estación norte. No es una parada de turno: es un hueco corto y ya avisado. Mantenimiento está en el puesto desde las diez y media. Quien esté al fondo y no distinga la hora, que mire la pizarra. La hora es las once en punto.","note":"Mateo apunta al fondo y no grita. La hora se dice con el mismo cuerpo de voz que el principio, no se apaga."},"quiz":[{"q":"Quieres que te oigan al fondo de una sala ruidosa. ¿Qué es proyectar?","options":["Subir el tono y apretar la garganta hasta que duela un poco.","Hablar el doble de rápido para acabar antes de que el ruido tape la frase.","Aire, resonancia y una frase apuntada a quien está lejos, sin grito."],"answer":2,"why":"El grito se confunde con enfado y no aguanta una mañana de partes. Llegar lejos es dirección y aire, no fuerza en el cuello."},{"q":"¿Para qué sirve el zumbido corto antes de hablar?","options":["Para hacer tiempo mientras buscas la diapositiva.","Para notar la voz en la cara y entrar en la frase con esa vibración.","Para demostrar al equipo que calientas, aunque nadie te oiga luego."],"answer":1,"why":"El zumbido te coloca la voz fuera de la garganta. La frase que viene después cuesta menos y se oye más."},{"q":"¿Qué haces si la nave tapa tu voz?","options":["Te acercas o usas el micrófono, y acortas la frase.","Gritas el parte entero para que nadie pueda decir que no avisaste.","Lo dejas en el chat y no lo dices, porque el ruido manda."],"answer":0,"why":"Un micrófono o tres pasos menos son oficio. Gritar el parte es una lesión anunciada, no más claridad."}],"exercise":{"prompt":"Di un parte de cuatro frases como si la última persona estuviera a diez metros. Sin gritar. La última palabra, igual de presente que la primera.","seconds":50,"scaffold":["A quién apuntas","El hecho","La hora o la cifra","La misma voz al final"],"focus":"volume"}},{"id":"m1-articulators","module":1,"title":"Articuladores","minutes":4,"framework":"Articulación","promise":"Vas a terminar las consonantes para que la segunda mitad de la frase no se convierta en papilla.","focus":"clarity","free":true,"cards":[{"kicker":"Por qué importa","body":"En español, el final de la palabra lleva plurales, tiempos y nombres. Si te comes la ese, la ene o la de, el otro adivina y a veces adivina mal. Claridad no es hablar como un locutor: es no hacer trabajar de más a quien escucha."},{"kicker":"Haz esto","body":"Labios, lengua y mandíbula hacen las consonantes: deja que se encuentren y se suelten. Abre un poco más la boca en la sílaba que manda. Di el nombre propio una vez despacio y, si hace falta, deletrea solo lo que se confunde."},{"kicker":"En la sala","body":"Cuando aceleras, se embarra el final, no el principio. Si oyes que una frase se te ha ido, repite las tres últimas palabras, no todo el discurso. Quien sesea y quien distingue zeta pueden articular igual de limpio: la app no te pide el otro acento."},{"kicker":"Evita","body":"No hables con los dientes casi cerrados por parecer serio. No te comas el segundo apellido, el número de línea o el nombre del proveedor. No exageres cada consonante en la reunión: una vez en el ensayo, luego natural y terminada."}],"example":{"speaker":"Lucía","role":"jefa de proyecto","script":"El hito de esta semana es la prueba con el proveedor Hartmann, no con el de embalaje. Hartmann trae el sensor el jueves antes de las doce. Si el sensor no entra, el viernes no hay prueba y el comité se entera el mismo viernes. Nuria prepara el banco de ensayo el miércoles por la tarde. Yo confirmo el albarán el jueves a las nueve. El nombre que tiene que quedar es Hartmann, con hache.","note":"Lucía no se traga «Hartmann» ni «jueves». Repite el nombre una vez, despacio, porque es lo que se iba a confundir."},"quiz":[{"q":"¿Por qué importa terminar la consonante final?","options":["Porque ahí van plurales, tiempos y nombres que el otro no debería adivinar.","Porque suena más culto, aunque el sentido ya estuviera claro.","Porque hay que marcar todas las zetas aunque en tu acento no se distingan."],"answer":0,"why":"Una ese comida convierte un plural en un singular. Eso en un parte es un error de trabajo, no un detalle de estilo."},{"q":"Se te ha embarullado el final de una frase. ¿Qué repites?","options":["El discurso desde el saludo, para que quede redondo.","Nada: seguir es mejor que corregir.","Las tres últimas palabras, las que llevaban el dato."],"answer":2,"why":"El dato suele estar al final. Repetir solo eso arregla la frase sin convertirla en un segundo discurso."},{"q":"¿Qué haces con un apellido que la sala va a oír mal?","options":["Lo dices más alto y más agudo.","Lo dices una vez más despacio y, si hace falta, deletreas solo el tramo que se confunde.","Lo cambias por «el proveedor» para no arriesgarte."],"answer":1,"why":"El nombre es el dato. Despacio y un deletreo corto bastan: no hace falta un discurso sobre el nombre."}],"exercise":{"prompt":"Explica un encargo con dos nombres propios y una hora. Termina cada palabra. Si uno se te come, repite solo ese trozo.","seconds":40,"scaffold":["El encargo en una frase","El primer nombre, terminado","El segundo nombre","La hora, sílaba a sílaba"],"focus":"clarity"}},{"id":"m1-pace","module":1,"title":"Ritmo y la pausa con poder","minutes":5,"framework":"Pausa con poder","promise":"Vas a dejar un silencio después de la palabra que importa, en vez de rellenarlo con un eh.","focus":"pace","free":true,"cards":[{"kicker":"Por qué importa","body":"Una pausa con poder va después de la palabra importante, no antes, a modo de duda. Ese silencio es el tiempo en que el otro apunta la fecha. Si hablas sin un solo alto, todo pesa igual y no pesa nada."},{"kicker":"Haz esto","body":"Marca en la nota una barra donde quieres callar: después del número, después del nombre, después del no. Cierra la boca y cuenta un tiempo lento. Luego sigue, sin pedir perdón por el silencio."},{"kicker":"En el relevo","body":"Di la hora de la parada y calla lo justo para que se escriba. Di la hora de arranque y calla otra vez. El ritmo de un parte bueno es frase, silencio, frase: no una cinta."},{"kicker":"Evita","body":"No tapes el silencio con eh, pues, bueno, vale u o sea. No hagas la pausa antes de saber qué ibas a decir: eso es un hueco, no un acento. No aceleres el final de la reunión: es donde se pierden el nombre y la fecha."}],"example":{"speaker":"Iker","role":"responsable de planta","script":"Ayer la línea dos estuvo parada cuarenta minutos. La causa fue un sensor suelto, no el programa. El sensor ya está firme y lo miramos dos turnos. Si aguanta, lo dejamos. Si se suelta, cambiamos el soporte y lo digo en el parte. Eso es todo.","note":"Después de «cuarenta minutos» y de «no el programa» cabe un silencio. Iker no lo rellena: la pausa subraya la causa y deja escribir."},"quiz":[{"q":"¿Dónde va una pausa con poder?","options":["Antes de cada frase, mientras buscas la palabra.","En medio de la cifra, para crear intriga.","Después de la palabra que quieres que se apunte."],"answer":2,"why":"El silencio posterior deja caer el dato. El silencio anterior, si no sabes qué sigue, solo suena a duda."},{"q":"¿Con qué no se rellena esa pausa?","options":["Con eh, pues, bueno, vale u o sea.","Con la boca cerrada y un tiempo de silencio.","Con la siguiente frase, cuando el tiempo ya ha pasado."],"answer":0,"why":"La muletilla le quita el peso al silencio y lo convierte en relleno. Callar es la pausa: hablar por hablar la deshace."},{"q":"¿Qué tramo de la reunión no conviene acelerar?","options":["El saludo, porque es de educación.","El cierre, donde viven el nombre y la fecha.","Las bromas, para que la sala se relaje."],"answer":1,"why":"El cierre apresurado se come al responsable y al plazo. Ahí el ritmo tiene que bajar, no subir."}],"exercise":{"prompt":"Da un parte de tres frases. Después del número y después de la causa, cierra la boca un tiempo entero. Sin eh y sin vale.","seconds":60,"scaffold":["El hecho","Silencio","La causa","Silencio","El paso siguiente"],"focus":"pace"}},{"id":"m1-pitch","module":1,"title":"Variedad de tono y uptalk","minutes":4,"framework":"Contorno","promise":"Vas a hacer que una decisión suene a decisión, y una pregunta solo cuando lo sea.","focus":"pitch","free":true,"cards":[{"kicker":"Por qué importa","body":"Si el tono sube al final, la frase pide permiso. Eso es el uptalk: una decisión disfrazada de pregunta. Quien tiene que ejecutar se queda sin saber si ya está decidido."},{"kicker":"Haz esto","body":"Di la misma frase de tres maneras: como dato, como decisión y como pregunta de verdad. Solo la pregunta sube al final. En la decisión, el tono baja en la última palabra y ahí te quedas."},{"kicker":"En la sala","body":"Mueve el tono en la palabra que manda, no en todas. Una nota plana todo el rato parece leída. Una melodía que siempre sube parece que estás pidiendo que te aprueben la frase."},{"kicker":"Evita","body":"No conviertas «salimos el viernes» en una pregunta si ya está cerrado. No bajes tanto que parezca que amenazas: aterrizar no es gruñir. No uses una voz más grave de la tuya para parecer serio: se nota el disfraz."}],"example":{"speaker":"Ane","role":"líder de equipo","script":"Salimos el viernes con el alcance que ya está en la nota. No meto informes nuevos entre medias. El cliente oye la fecha el jueves, de mi boca, no por un correo suelto. Si el viernes se mueve, lo digo yo el mismo día. La decisión es el viernes. Lo demás se comenta, y no reabre la fecha.","note":"En «la decisión es el viernes» el tono baja. No queda colgando como si Ane estuviera pidiendo permiso al equipo."},"quiz":[{"q":"¿Qué le hace el uptalk a una decisión?","options":["La hace más amable y por eso conviene en casi todos los cierres.","La convierte en una pregunta y deja sin saber si ya se puede ejecutar.","Solo cambia la música de la frase, y el sentido queda igual."],"answer":1,"why":"Quien ejecuta necesita oír un final que cae. Si la frase sube, espera una confirmación que nadie va a dar."},{"q":"¿En cuál de estas tres versiones debe subir el tono?","options":["En el dato, para que destaque.","En la decisión, para sonar enérgico.","En la pregunta de verdad, y solo en esa."],"answer":2,"why":"La pregunta sube porque pide respuesta. El dato y la decisión aterrizan."},{"q":"¿Cómo evitas sonar plano sin disfrazar la voz?","options":["Mueves el tono en la palabra que manda y luego vuelves a bajar.","Subes un poco al final de cada frase, para que haya variedad.","Adelantas una voz más grave que la tuya durante toda la reunión."],"answer":0,"why":"La variedad va en la palabra que pesa, no en un disfraz. Subir siempre es uptalk, no expresividad."}],"exercise":{"prompt":"Di «salimos el viernes» primero como decisión y después como pregunta. Luego añade una frase de encargo con el tono que aterriza.","seconds":45,"scaffold":["La decisión, tono que baja","La pregunta, tono que sube","El encargo","La última palabra, abajo"],"focus":"pitch"}},{"id":"m1-health","module":1,"title":"Salud vocal para quien habla","minutes":3,"framework":"Cuidado de la voz","promise":"Vas a aguantar un día de reuniones y de parte sin dejar la voz en el pasillo.","focus":"breath","free":true,"cards":[{"kicker":"Por qué importa","body":"Quien habla por trabajo gasta voz como quien anda gasta suela. Un día de cuatro reuniones más una nave deja la garganta seca si no cambias nada. Cuidarla es oficio, no un tratamiento ni una moda."},{"kicker":"Haz esto","body":"Ten agua a mano y bebe a sorbos, no un vaso de golpe cuando ya raspas. Antes de una mañana larga, zumba un minuto y di una frase a volumen de sala. En la nave, acércate o usa micrófono: llegar al fondo a gritos no es presencia."},{"kicker":"Para","body":"Si algo duele al hablar, paras. Dolor no es una señal de que «ya entra en calor». Si te duele varios días, lo ve alguien que entienda de voz: esto no lo diagnostica una lección."},{"kicker":"Evita","body":"No susurres toda la mañana: susurrar no ahorra, aprieta. No conviertas el carraspeo en muleta: una vez está bien, la serie reseca. No salgas de un café solo a cuatro horas de parte sin una gota de agua."}],"example":{"speaker":"Mateo","role":"líder de equipo","script":"Hoy tengo parte a las ocho, reunión a las diez y visita de proveedor a la una. El agua se queda en la mesa, no en la mochila. En la nave uso el micrófono del puesto, no la garganta. Si una frase no llega, la acorto y me acerco. Entre la reunión y la visita no hablo por hablar en el pasillo. Mañana quiero la misma voz que hoy a las ocho.","note":"Mateo reparte la voz del día: agua, micrófono y menos charla de pasillo. No presume de aguantar: organiza el gasto."},"quiz":[{"q":"Te duele al hablar a media mañana. ¿Qué haces?","options":["Paras. El dolor no es el calentamiento.","Sigues, porque la voz «se abre» con el uso.","Susurras el resto del día para ahorrar."],"answer":0,"why":"Dolor es señal de parar, no una fase del oficio. Susurrar no descansa la voz."},{"q":"¿Qué ayuda de verdad en un día largo de voz?","options":["Carraspear antes de cada frase para «limpiar».","Agua a sorbos, un minuto de zumbido y micrófono si hay ruido.","Café seguido y hablar más alto para no parecer cansado."],"answer":1,"why":"La humedad, un arranque suave y no gritar aguantan la jornada. El carraspeo en serie y el café solo van al revés."},{"q":"¿Por qué no conviene susurrar todas las reuniones?","options":["Porque queda poco profesional en el acta.","Porque la gente cree que tienes un secreto.","Porque el susurro aprieta en vez de ahorrar voz."],"answer":2,"why":"Hablar bajo con aire es una cosa. Susurrar sin voz es otra, y cansa más."}],"exercise":{"prompt":"Di en voz alta cómo vas a repartir la voz en tu próximo día largo: agua, un arranque corto y dónde no vas a gritar.","seconds":30,"scaffold":["Dónde bebes","El minuto de antes","Dónde hay ruido y qué harás"],"focus":"breath"}},{"id":"m2-presence","module":2,"title":"Qué es la presencia","minutes":5,"framework":"Gravitas","promise":"Vas a ocupar la frase hasta el punto final y quedarte ahí, sin adornar ni pedir perdón.","focus":"presence","free":true,"cards":[{"kicker":"Por qué importa","body":"Presencia es que se note que estás en esa frase y puedes esperar. No es hablar más alto, ni más grave, ni contar más. La gravitas se ve cuando terminas y no rellenas el segundo que sigue."},{"kicker":"Haz esto","body":"Elige a una persona y mírala durante una frase entera, no un vistazo por palabra. Di el verbo que manda y calla. Si te sale un «bueno» o un «nada, era eso», cómetelo: la frase ya había acabado."},{"kicker":"En la sala","body":"Llega al punto antes de mirar el papel. Los pies, o la espalda en la silla, quietos mientras cae la frase. Quien preside y quien informa usan el mismo músculo: acabar la frase."},{"kicker":"Evita","body":"No pidas perdón por tomar la palabra si te toca hablar. No sonrías el final de una mala noticia para que pese menos: pesa igual y tú quedas flojo. No confundas presencia con ocupar todo el tiempo."}],"example":{"speaker":"Lucía","role":"jefa de proyecto","script":"El proyecto va tarde una semana y lo digo al principio. La causa es la prueba que repetimos, no un misterio del equipo. Propongo mover la entrega al día doce y no prometer el día cinco. El coste de decirlo hoy es una conversación. El coste de decirlo el viernes es una sorpresa. Necesito un sí o un no antes de las cuatro.","note":"Lucía no adorna el retraso ni se ríe al final. La gravitas está en la primera frase y en el silencio de después del sí o el no."},"quiz":[{"q":"¿Qué es la gravitas en una reunión, dicho en corto?","options":["Una voz más grave de la tuya, sostenida todo el rato.","Hablar más que el resto para que se note que llevas el tema.","Terminar la frase y poder esperar, sin rellenar ni pedir perdón."],"answer":2,"why":"El peso está en el final y en el silencio que lo respeta. El disfraz de voz y el monólogo no dan presencia."},{"q":"¿Cuánto tiempo miras a alguien si quieres presencia?","options":["Una frase entera, no un vistazo por palabra.","Todo el rato a la mesa, para no intimidar.","Solo al saludar, y luego al papel."],"answer":0,"why":"Una frase, una persona: el otro nota que la frase es para alguien. El barrido de ojos deja la frase sin dueño."},{"q":"Acabas de dar una mala noticia clara. ¿Qué sobra?","options":["Callar un segundo.","Una sonrisa que le quite peso y un «bueno, nada, era eso».","Decir qué decisión necesitas."],"answer":1,"why":"La sonrisa de disculpa y la coletilla le quitan seriedad a un hecho. El hecho sigue ahí: solo quedas tú más flojo."}],"exercise":{"prompt":"Di una mala noticia de trabajo en cuatro frases. Termina cada una. Al acabar, cuenta un segundo en silencio, sin «bueno» y sin sonrisa de disculpa.","seconds":75,"scaffold":["El hecho, primero","La causa, una","Lo que propones","El sí o el no que pides","Un segundo callado"],"focus":"presence"}},{"id":"m2-composure","module":2,"title":"Calma bajo presión","minutes":4,"framework":"La primera palabra","promise":"Cuando te aprieten, vas a contestar con la primera palabra más baja y más lenta que la pregunta.","focus":"presence","free":false,"cards":[{"kicker":"Por qué importa","body":"Bajo presión la voz se acelera y se sube, y el contenido parece menos sólido de lo que es. La sala lee esa prisa como duda, aunque tengas el dato. La calma aquí es un ajuste de oficio, no un discurso sobre cómo te sientes."},{"kicker":"Haz esto","body":"Un aire antes de la primera palabra. Esa palabra, más baja y más lenta que la pregunta que te acaban de hacer. Repite la pregunta en una línea y luego responde: «la causa es esta»."},{"kicker":"Si te aprietan","body":"Puedes decir «un segundo» y usarlo de verdad. Si no lo sabes, dilo en la primera frase y di a qué hora vuelves. No te rías para quitar hierro: la risa nerviosa acelera todavía más."},{"kicker":"Evita","body":"No entres con «a ver, o sea, es que». No contestes a la velocidad de quien te interrumpe: su prisa no es tu ritmo. No des tres causas si te han pedido una."}],"example":{"speaker":"Iker","role":"responsable de planta","script":"La pregunta es por qué la línea dos perdió cuarenta minutos. La causa es un sensor suelto, no el programa y no el turno. Ya está firme. Lo miramos hoy y mañana. Si se vuelve a soltar, paro y cambio el soporte. No tengo otra causa y no me la invento.","note":"Iker repite la pregunta y baja el ritmo en la causa. No se engancha a la velocidad de quien le ha apretado."},"quiz":[{"q":"Te preguntan un retraso en tono seco. ¿Cómo entra tu primera palabra?","options":["Más rápida que la pregunta, para demostrar control.","Más baja y más lenta que la pregunta, después de un aire.","Con una risa breve que quite hierro."],"answer":1,"why":"Bajar el ritmo deshace la prisa que la sala iba a leer como duda. Reírte o acelerar la confirman."},{"q":"¿Qué haces con la pregunta antes de soltar causas?","options":["La ignoras y cuentas el contexto de las últimas semanas.","La discutes, porque el tono no te ha gustado.","La repites en una línea y respondes a esa, no a tres más."],"answer":2,"why":"Nombrar la pregunta demuestra que la has oído y te ancla. El contexto largo, en ese momento, suena a huida."},{"q":"No tienes la causa todavía. ¿Qué frase aguanta la presión?","options":["«No la sé. Vuelvo a las once con la causa o con un hueco más claro.»","«Seguro que es el proveedor, pero no me quotes.»","«Es complicado, hay muchos factores, ahora te digo algo.»"],"answer":0,"why":"Un desconocido con hora de vuelta es más sólido que una causa inventada. «Es complicado» no le da a nadie un siguiente paso."}],"exercise":{"prompt":"Alguien te pregunta, seco, por qué algo va tarde. Un aire. Primera palabra lenta. La causa en una frase, o la hora a la que la tendrás.","seconds":60,"scaffold":["Un aire","La pregunta, repetida","Una causa o un no lo sé","La hora de vuelta"],"focus":"presence"}},{"id":"m2-decisive","module":2,"title":"Lenguaje que decide","minutes":4,"framework":"Verbo que cierra","promise":"Vas a cambiar el paquete de quizá por un verbo: propongo, decido o pido.","focus":"fillers","free":false,"cards":[{"kicker":"Por qué importa","body":"«Yo creo que quizás podríamos» son cuatro frenos delante de un verbo que no llega. La sala no sabe si estás decidiendo, sugiriendo o pidiendo permiso. Decidir en voz alta no es ser brusco: es no hacer adivinar."},{"kicker":"Haz esto","body":"Un solo atenuante si lo necesitas, no tres. Verbos que cierran: propongo, decidimos, hace falta, pido, dejo fuera. Escribe la frase antes de entrar y tacha «un poco», «en principio» y «si te parece» cuando vayan de relleno."},{"kicker":"La frase","body":"«Propongo cerrar el alcance el viernes». «Si ves un riesgo, dilo ahora». Cabe el matiz después del verbo, no en lugar del verbo."},{"kicker":"Evita","body":"No apiles o sea, en plan, digamos, tipo, bueno y vale en la misma frase. No digas «no sé si» cuando sí sabes lo que propones y solo te cuesta decirlo. No suavices tanto el no que el otro se vaya con un sí."}],"example":{"speaker":"Ane","role":"líder de equipo","script":"Propongo sacar el informe extra de esta entrega. El cliente pidió la fecha, no más páginas. El informe puede ir la semana siguiente, con Nuria. Hace falta la cifra de defectos el jueves a las doce, y esa sí va. Si alguien ve un riesgo de cliente, lo quiero oír ahora. Si no, el alcance queda cerrado al salir de esta sala.","note":"No hay «quizá podríamos». Ane deja un sitio para el riesgo y, si nadie habla, el cierre es un cierre."},"quiz":[{"q":"¿Qué frase decide?","options":["«Propongo cerrar el alcance el viernes. Si hay un riesgo, dilo ahora.»","«Yo creo que quizás, en principio, podríamos ir viendo de cerrar, ¿no?»","«No sé si será una tontería, pero a lo mejor el alcance, tipo, ya está.»"],"answer":0,"why":"Hay un verbo y una puerta para el riesgo. Las otras dos hacen adivinar si ya está decidido."},{"q":"¿Cuántos atenuantes aguanta una frase que tiene que cerrar?","options":["Todos los que hagan falta para que nadie se moleste.","Ninguno, aunque el contenido sea una hipótesis.","Uno, si lo necesitas, y el verbo sigue estando."],"answer":2,"why":"Un matiz es educación. Tres matiz es una frase que no se puede ejecutar."},{"q":"Dices «no sé si» y en realidad sí tienes propuesta. ¿Qué está pasando?","options":["Estás siendo riguroso con la incertidumbre.","Estás tapando el verbo porque te cuesta soltarlo.","Estás invitando al equipo a decidir por ti, que es lo correcto."],"answer":1,"why":"«No sé si» cabe cuando no sabes. Si ya hay propuesta, el «no sé» es relleno y el otro lo nota."}],"exercise":{"prompt":"Di una propuesta que suelas adornar. Primera versión con los quizá. Segunda con un verbo solo y, como mucho, un matiz.","seconds":50,"scaffold":["La frase floja, una vez","Tacha un poco, quizá, en principio","Propongo o pido","El riesgo, si cabe, al final"],"focus":"fillers"}},{"id":"m2-body","module":2,"title":"Cuerpo y mirada en la videollamada","minutes":4,"framework":"Cámara","promise":"En la cámara vas a mirar al lente cuando pidas algo, y a dejar las manos quietas el resto del tiempo.","focus":"presence","free":false,"cards":[{"kicker":"Por qué importa","body":"En videollamada el otro no te ve entrar en la sala: te ve una cabeza y, si acaso, un gesto. Los ojos que se van a otra pantalla parecen una frase leída, aunque no lo sea. El cuerpo cuenta si la petición va en serio."},{"kicker":"Haz esto","body":"Cámara a la altura de los ojos, no desde abajo. Encuadra cabeza y algo de pecho, con luz en la cara y no en la ventana de detrás. Cuando llegue la petición, mira al lente una frase entera y luego vuelve a la gente para escuchar."},{"kicker":"El gesto","body":"Un gesto, dentro del encuadre, para una idea. Luego manos quietas. Si lees, deja el texto pegado a la cámara para que el ojo no viaje de lado en cada línea."},{"kicker":"Evita","body":"No mires tu propia imagen para comprobar cómo quedas: te pierdes la frase. No te balancees en la silla: en cámara es un vaivén constante. No abras preguntando si se te ve y si se te oye cuando ya te han saludado: esa prueba era antes de entrar."}],"example":{"speaker":"Lucía","role":"jefa de proyecto","script":"Resumo en un minuto y luego quiero una decisión. La prueba con el cliente queda el jueves, no el martes. El martes no tenemos el sensor y no voy a fingir que sí. Pido que el comité acepte el jueves antes de cerrar esta llamada. Si alguien no puede el jueves, lo dice ahora y buscamos el viernes por la mañana. Me quedo callada lo justo para que dé tiempo a decir que no.","note":"En la frase del pedido, Lucía mira al lente. Al callar, deja las manos quietas y no rellena el silencio."},"quiz":[{"q":"¿Cuándo miras al lente y no a las caras de la pantalla?","options":["Durante toda la llamada, para no perder presencia.","Nunca: queda raro y la gente quiere contacto visual en la pantalla.","En la frase de la petición, y al escuchar vuelves a las caras."],"answer":2,"why":"El lente es tus ojos para quien te ve. Usarlo en la petición, y no todo el rato, marca el encargo sin dejarte sordo."},{"q":"¿Cómo encuadras la cámara?","options":["Desde abajo, muy cerca, para que se vea la cara grande.","A la altura de los ojos, con cabeza, algo de pecho y luz en la cara.","Con la ventana detrás, que queda más luminoso."],"answer":1,"why":"Desde abajo y a contraluz te vuelves una silueta. A la altura de los ojos pareces en la misma mesa."},{"q":"¿Qué hacen las manos en una videollamada?","options":["Un gesto para una idea, y quietas el resto.","Acompañan cada palabra, como en un escenario.","Fuera de cámara siempre, por si distraen."],"answer":0,"why":"Un gesto se lee. El gesto continuo, en un recuadro pequeño, es ruido."}],"exercise":{"prompt":"Con la cámara del portátil, o imaginándola, pide una decisión en tres frases. En la frase del pedido, mira al lente. Luego calla.","seconds":45,"scaffold":["El hecho","La petición, al lente","La alternativa si dicen que no","Manos quietas al callar"],"focus":"presence"}},{"id":"m2-first30","module":2,"title":"Los primeros 30 segundos","minutes":5,"framework":"Apertura","promise":"Vas a abrir con el punto, el número o la escena, no con el agradecimiento y el contexto.","focus":"structure","free":false,"cards":[{"kicker":"Por qué importa","body":"En medio minuto la sala decide si sigue contigo o si abre el correo. «Gracias por el tiempo, voy a dar un poco de contexto» gasta ese minuto en nada. Quien llega tarde a tu punto ya no vuelve, aunque el punto fuera bueno."},{"kicker":"Tres puertas","body":"La decisión que pides. El número que cambia la conversación. Una escena de una frase, concreta, y enseguida para qué la cuentas."},{"kicker":"Al abrir","body":"Después de la puerta, una sola línea de por qué importa hoy. Luego ya puedes dar el mapa, si todavía hace falta. Treinta segundos bien usados caben en tres frases cortas."},{"kicker":"Evita","body":"No cuentes tu cargo ni la historia del proyecto como entrada. No leas el orden del día antes de decir qué hay que salir a decidir. No abras con una disculpa por la hora, el material o el enlace."}],"example":{"speaker":"Mateo","role":"líder de equipo","script":"Necesito una decisión antes de las doce: cambiamos el soporte del sensor hoy o esperamos al paro del viernes. Ayer se soltó dos veces y la segunda nos costó veinte minutos. Hoy el cambio son quince minutos avisados, con el repuesto ya en el puesto. El viernes es más barato de reloj y más caro de riesgo. Yo haría el cambio hoy. Si la sala prefiere el viernes, lo dejo escrito como riesgo, no como olvido.","note":"La primera frase ya es la decisión. Mateo no gasta el medio minuto en dar las gracias ni en explicar qué es un sensor."},"quiz":[{"q":"¿Cuál es una apertura de treinta segundos que sirve?","options":["«Gracias por el hueco. Doy un poco de contexto y luego, si da tiempo, la petición.»","«La decisión es hoy o el viernes. Ayer fueron veinte minutos. Yo lo haría hoy.»","«Primero me presento, luego el histórico del año y al final, si llegamos, la pregunta.»"],"answer":1,"why":"Decisión, cifra y postura caben al principio. El contexto y el cargo pueden esperar, y a veces no hacen falta."},{"q":"¿Qué tres puertas valen para abrir?","options":["La decisión, el número o una escena de una frase.","El agradecimiento, la agenda y una disculpa.","Tu biografía, el organigrama y el histórico."],"answer":0,"why":"Cualquiera de esas tres puertas pone contenido en el primer aliento. El resto gasta el medio minuto en cortesía o en historia."},{"q":"Después de la primera frase, ¿qué cabe?","options":["Diez minutos de antecedentes para que nadie se pierda.","Otra disculpa, por si la primera frase sonó directa.","Una línea de por qué importa hoy, y solo entonces el mapa."],"answer":2,"why":"Una línea de actualidad basta para enganchar el mapa. Los antecedentes largos y la segunda disculpa devuelven la apertura al principio."}],"exercise":{"prompt":"Abre un tema real en treinta segundos. Sin gracias y sin contexto. Decisión, número o escena, y una línea de por qué es hoy.","seconds":60,"scaffold":["La puerta, en la primera frase","Por qué hoy","Qué pides","Calla"],"focus":"structure"}},{"id":"m2-credibility","module":2,"title":"Credibilidad","minutes":4,"framework":"Hecho y límite","promise":"Vas a sostener una cifra con su fuente y con su borde, y a decir que no lo sabes cuando no lo sepas.","focus":"structure","free":false,"cards":[{"kicker":"Por qué importa","body":"Una cifra sin día y sin fuente es un rumor con aspecto de dato. Credibilidad, dicha en voz alta, es concreta, propia y con límite. Quien promete el universo deja de ser creíble en el detalle que sí conocía."},{"kicker":"Haz esto","body":"Cuenta lo que vio tu gente, no lo que «seguro pasa en todas las plantas». Pon al lado del número el turno, el día y de dónde sale. Si el número tiene un hueco, el hueco va en la misma frase."},{"kicker":"El límite","body":"«No lo sé» más la hora a la que volverás pesa más que una seguridad nebulosa. No te atribuyas el mérito ni la culpa de otro turno. Una promesa pequeña, cumplida, vale más que una grande dicha con voz firme."},{"kicker":"Evita","body":"No redondees a tu favor y lo llames orden de magnitud si el parte ya tiene el dato. No digas que está controlado si no puedes decir el siguiente paso. No tapes un hueco con adjetivos: robusto, alineado, prácticamente resuelto."}],"example":{"speaker":"Iker","role":"responsable de planta","script":"La chatarra de ayer en la línea dos fue de dieciocho palés, contados en el parte de las tres. El turno anterior, con el mismo producto, se quedó en cuatro. No sé todavía si el sensor nuevo lo explica entero. Mantenimiento lo mira esta mañana y yo vuelvo con la causa a las doce. Hasta esa hora no prometo que no se repita. Lo que sí prometo es no rearrancar a ciegas.","note":"Iker separa lo contado, lo comparado y lo que no sabe. La credibilidad está en el límite de las doce, no en un tono de certeza."},"quiz":[{"q":"¿Qué sostiene una cifra delante de una sala exigente?","options":["El número, de dónde sale y qué no cubre.","Un tono seguro y la palabra controlado.","El promedio del año, dicho sin fecha."],"answer":0,"why":"Fuente y límite permiten usar el número. El tono seguro, sin borde, se gasta a la primera pregunta."},{"q":"No tienes la causa. ¿Qué frase conserva la credibilidad?","options":["Está controlado: fue un tema puntual.","No lo sé. Vuelvo a las doce con la causa o con un hueco más claro.","Seguro que es el sensor, pero no lo pongas por escrito."],"answer":1,"why":"Un desconocido con hora de vuelta se puede gestionar. Una causa inventada, aunque sea en voz baja, te deja sin crédito cuando salga la real."},{"q":"¿De quién hablas al contar un fallo de tu turno?","options":["De la empresa entera, para que suene estratégico.","Del turno de noche, que seguramente hizo lo mismo.","De lo que vio tu gente, con el parte y la hora."],"answer":2,"why":"Lo propio se puede defender. Hablar por toda la planta o por otro turno es una atribución que no te han pedido."}],"exercise":{"prompt":"Da una cifra real de tu trabajo. Di de dónde sale, con qué la comparas y qué parte todavía no sabes. Pon hora a esa parte.","seconds":50,"scaffold":["El número y la fuente","La comparación","Lo que no sabes","La hora de vuelta"],"focus":"structure"}},{"id":"m3-bluf","module":3,"title":"BLUF: lo importante primero","minutes":5,"framework":"BLUF","promise":"Vas a poner el estado y la petición en la primera frase, antes de que nadie tenga que preguntarte dónde está el punto.","focus":"structure","free":true,"cards":[{"kicker":"Por qué importa","body":"BLUF es decir lo importante al principio. Quien decide suele quedarse con la primera frase y con la última. Si el encargo vive en el minuto cuatro, te pedirán que resumas y habrás perdido la sala."},{"kicker":"Haz esto","body":"Primera frase: cómo está el asunto y qué pides. Después, dos razones, no el diario de la semana. Al final, nombre y fecha, por si alguien solo oyó el cierre."},{"kicker":"En el comité","body":"«Vamos una semana tarde y pido mover la entrega al día doce» ya se puede discutir. Cómo se torció cabe después, en dos frases, o cuando te lo pregunten. Una sala con prisa agradece el orden y desconfía del preámbulo."},{"kicker":"Evita","body":"No abras con contexto para situar si la situación ya está en la convocatoria. No guardes la mala noticia para cuando la sala esté más receptiva. No llames resumen a repetir el relato desde el lunes."}],"example":{"speaker":"Lucía","role":"jefa de proyecto","script":"Vamos una semana tarde y pido mover la entrega al día doce. La prueba se repitió porque el sensor llegó el jueves y no el lunes. El cliente prefiere una fecha cierta a un viernes heroico. El coste de decirlo hoy es una conversación, no una sorpresa. Nuria confirma el banco el miércoles. Yo dejo la fecha nueva escrita antes de salir de la sala.","note":"La primera frase ya se puede aceptar o rechazar. Lucía no esconde el retraso detrás del viaje del sensor."},"quiz":[{"q":"¿Qué es abrir en BLUF?","options":["Contar la historia en orden y dejar la petición para el cierre.","Empezar por las gracias y por el contexto compartido.","Decir el estado y la petición en la primera frase."],"answer":2,"why":"Si la primera frase no se puede discutir, todavía no has empezado. El orden cronológico es cómodo para quien habla y caro para quien decide."},{"q":"El comité te pide que resumas. ¿Qué ha pasado casi siempre?","options":["La petición iba tarde y la primera frase no decidía nada.","Has sido tan breve que ahora necesitan el histórico completo.","Has usado un número y los números, de por sí, confunden."],"answer":0,"why":"El resumen que te piden suele ser la frase con la que tendrías que haber abierto. No es una queja sobre los números: es una queja sobre el orden."},{"q":"¿Dónde conviene repetir el nombre y la fecha?","options":["Solo en el correo de después, para no alargar la sala.","Al cierre, porque hay quien solo alcanza a oír el final.","En el saludo, antes de saber si hacen falta."],"answer":1,"why":"La última frase también se la lleva la gente. Nombre y fecha ahí no son un repetir por vicio: son el encargo para quien llegó tarde al punto."}],"exercise":{"prompt":"Actualiza un tema real como si tuvieras un minuto de comité. La primera frase lleva el estado y la petición. Luego dos razones y el cierre con nombre.","seconds":75,"scaffold":["Estado y petición","Razón una","Razón dos","Nombre y fecha"],"focus":"structure"}},{"id":"m3-scqa","module":3,"title":"Pirámide y SCQA","minutes":5,"framework":"SCQA","promise":"Vas a ordenar un asunto en situación, complicación, pregunta y respuesta, con la respuesta a la vista.","focus":"structure","free":false,"cards":[{"kicker":"La pirámide","body":"La respuesta va arriba y debajo caben las razones y, más abajo, las pruebas. SCQA es un camino para llegar a esa respuesta sin perder a la sala. Situación, complicación, pregunta y respuesta: cuatro frases, si el asunto lo permite."},{"kicker":"En la sala","body":"La situación es lo que todos reconocerían en una frase, no la historia de la cuenta. La complicación es lo que ya no cabe en el plan de antes. La pregunta se dice en una línea y la respuesta se puede empezar esta semana."},{"kicker":"Si ya lo saben","body":"Si la sala vive en esa situación, no la cuentes como si fuera nueva. Gasta el minuto en la complicación y en la respuesta. Siete razones debajo de una respuesta buena la tumban: deja dos."},{"kicker":"Evita","body":"No uses este orden para esconder la respuesta al final, como un chiste. No llames complicación a un estado de ánimo o a una lista de quejas. No hagas una pregunta que ya trae el sí escondido."}],"example":{"speaker":"Ane","role":"líder de equipo","script":"La situación es que el cliente pide cambios dentro de la misma semana. La complicación es que nuestro plan sigue congelando dos semanas. La pregunta es si protegemos la congelación o protegemos la cuenta. Mi respuesta es una puerta estrecha: lo que cueste menos de un día entra, y lo grande espera. El coste es una tarde de planificación, no el calendario entero. Si no ponemos nosotros la puerta, el cliente se la inventa y nos enteramos por una queja.","note":"La respuesta no espera al minuto tres. Situación y complicación son cortas porque la sala ya vive ahí."},"quiz":[{"q":"En SCQA, ¿qué es la complicación?","options":["El estado de ánimo con el que la sala llega.","Lo que ha cambiado y ya no cabe en el plan anterior.","La lista de todo lo que fue mal en el trimestre."],"answer":1,"why":"La complicación es un cambio concreto respecto al plan. Una lista de quejas no le dice a nadie qué pregunta hay que resolver."},{"q":"¿Dónde va la respuesta si hablas en pirámide?","options":["Al final, para que el relato tenga intriga.","En un anexo, junto a la gráfica.","Arriba, antes de las razones y de las pruebas."],"answer":2,"why":"Quien decide necesita la respuesta para saber qué hacer con las pruebas. La intriga está bien en un cuento y mal en un comité."},{"q":"La sala ya conoce la situación. ¿Qué haces?","options":["La dices en una frase y pasas a la complicación.","La cuentas completa, por si hay alguien nuevo en la sala.","Te la saltas y entras por una anécdota personal."],"answer":0,"why":"Una frase basta para alinearse y no trata a la sala de nueva. Repetir el contexto entero gasta el tiempo de la respuesta."}],"exercise":{"prompt":"Plantea un cambio real con SCQA. Cuatro frases, en ese orden, y la respuesta tiene que caber en una semana de trabajo.","seconds":90,"scaffold":["Situación, una frase","Complicación","La pregunta","Tu respuesta","El coste de no hacerla"],"focus":"structure"}},{"id":"m3-prep","module":3,"title":"PREP para improvisar","minutes":4,"framework":"PREP","promise":"Con medio minuto y sin diapositiva vas a decir un punto, una razón, un ejemplo y el punto otra vez, más corto.","focus":"structure","free":false,"cards":[{"kicker":"Cuando improvisas","body":"PREP es punto, razón, ejemplo y punto. Sirve cuando te preguntan y no hay tiempo de armar un informe. No hace falta sonar brillante: hace falta que te puedan repetir."},{"kicker":"El punto","body":"El punto es una frase que sobrevive en el pasillo. La razón es una, la más fuerte, no el racimo. El ejemplo es un caso con nombre y con día."},{"kicker":"La vuelta","body":"El segundo punto es el mismo, con menos palabras. Ahí se nota si el primero era de verdad una idea o solo un arranque. Si te sobra un aliento, di qué harías si la sala elige lo contrario."},{"kicker":"Evita","body":"No abras por el ejemplo si todavía no has dicho qué opinas. No cierres con un «en fin, no sé» que deshaga el punto. No metas un segundo ejemplo ya que estás."}],"example":{"speaker":"Mateo","role":"líder de equipo","script":"Mi punto es no salir a producción este jueves. La razón es que la prueba de paro no está hecha, y la última vez que la saltamos se paró la línea. El ejemplo es el jueves doce: saltamos el ensayo y al día siguiente perdimos cuarenta minutos. El punto, otra vez: el jueves no se sale, se sale el lunes con la prueba en medio. Si la sala elige el jueves de todos modos, lo anoto como riesgo con nombre. No lo voy a llamar un sí tranquilo.","note":"Hay un solo ejemplo, con día. Mateo repite el punto más corto y no lo deshace al final."},"quiz":[{"q":"¿Qué orden es PREP?","options":["Punto, razón, ejemplo y el mismo punto, más corto.","Problema, relato, emoción y promesa.","Pregunta, respuesta, evidencia y pausa."],"answer":0,"why":"El ejemplo ilustra una razón, y el cierre no abre un punto nuevo. Las otras secuencias mezclan marcos que sirven para otra cosa."},{"q":"En medio minuto, ¿cuántos ejemplos caben?","options":["Tres, para que la sala elija.","Todos los que recuerdes, en orden de calendario.","Uno, con nombre y con día."],"answer":2,"why":"El segundo ejemplo se come la vuelta al punto. Uno concreto se recuerda: tres se convierten en lista."},{"q":"¿Cómo es el segundo punto?","options":["Una idea nueva, para no repetirte.","El mismo punto, dicho con menos palabras.","Una pregunta abierta, para que participe la sala."],"answer":1,"why":"Repetir más corto fija la frase que quieres que se lleven. Una idea nueva al final deja dos mensajes y ninguno cerrado."}],"exercise":{"prompt":"Te preguntan, sin aviso, si un plazo se debe mover. Responde en PREP. Un ejemplo solo. El punto final, más corto que el primero.","seconds":60,"scaffold":["Tu punto","Una razón","Un caso con día","El punto, más corto"],"focus":"structure"}},{"id":"m3-three","module":3,"title":"La regla de tres","minutes":4,"framework":"Regla de tres","promise":"Vas a dejar tres ideas en paralelo, capaces de sobrevivir al pasillo, y ninguna cuarta de regalo.","focus":"structure","free":false,"cards":[{"kicker":"Por qué importa","body":"Tres cosas se pueden repetir al salir de la sala. Dos se quedan cortas cuando el tema es de verdad ancho. Cuatro empiezan a perderse en cuanto alguien interrumpe."},{"kicker":"La forma","body":"Las tres empiezan igual: mismo tipo de frase. Qué y cuándo, o riesgo y dueño, no una mezcla de estilos. Si una es un verbo y otra es un adjetivo, la lista no se sostiene."},{"kicker":"Si hay siete","body":"Agrupa los siete en tres. Di el grupo y abre el detalle solo si te preguntan. Decirlos todos por si acaso es la forma más segura de que no se lleven ninguno."},{"kicker":"Evita","body":"No numeres en voz alta hasta siete con la esperanza de ir rápido. No hagas tres puntos que son el mismo dicho de tres maneras. No añadas un «y ya que estamos» al cerrar."}],"example":{"speaker":"Ane","role":"líder de equipo","script":"Esta semana hay tres cosas, y no hay una cuarta. Primero, la cifra de defectos el jueves a las doce. Segundo, la prueba con Hartmann el viernes por la mañana. Tercero, el texto de una página para dirección, el miércoles a las tres. Si entra algo nuevo, sale una de estas tres, y digo yo cuál. Al salir, cualquiera de esta mesa puede repetir las tres sin mirar la nota.","note":"Las tres tienen la misma forma: qué y cuándo. Ane no regala un cuarto punto al final."},"quiz":[{"q":"Tienes siete asuntos y un minuto. ¿Qué haces?","options":["Los dices todos, más rápido.","Eliges dos al azar para no abrumar.","Los agrupas en tres y dejas el detalle para quien pregunte."],"answer":2,"why":"Tres grupos se pueden recordar y defender. Siete a toda prisa se oyen como ruido."},{"q":"¿Por qué importa que las tres frases tengan la misma forma?","options":["Porque suena a eslogan y el eslogan motiva.","Porque así se repiten al salir sin tener que reconstruirlas.","Porque tres frases largas impresionan más que tres cortas."],"answer":1,"why":"El paralelo es una ayuda de memoria, no un adorno. Una lista desigual obliga al otro a hacer el trabajo de ordenar."},{"q":"¿Qué sobra en una regla de tres bien cerrada?","options":["Un cuarto punto añadido con un «ya que estamos».","Una hora al lado de cada encargo.","Decir en voz alta que no hay una cuarta."],"answer":0,"why":"El cuarto punto, dicho de pasada, es el que luego se discute en el pasillo. Nombrar que no hay cuarta protege a las tres."}],"exercise":{"prompt":"Di las tres prioridades de tu semana, con la misma forma y con fecha. Si te sale una cuarta, métela dentro de una de las tres o déjala fuera.","seconds":50,"scaffold":["Primero, qué y cuándo","Segundo, igual de concreta","Tercero","Di que no hay cuarta"],"focus":"structure"}},{"id":"m3-technical","module":3,"title":"Explicar lo técnico sin humo","minutes":5,"framework":"Traducción","promise":"Vas a explicar un fallo técnico por lo que se paró, lo que costó y qué se decide, no por el manual del armario.","focus":"clarity","free":false,"cards":[{"kicker":"El oído de dirección","body":"Quien dirige necesita la causa en una frase, el daño y el siguiente paso. El esquema del armario no le ayuda a decidir. «Hubo un tema técnico» no es una causa: es una cortina."},{"kicker":"Traduce","body":"Una sigla cabe si la traduces en el mismo aliento. El PLC es el equipo que le dice a la máquina cuándo moverse. Si pierde una señal, hace lo que le pedimos a ciegas, y eso casi siempre es parar."},{"kicker":"El daño","body":"Di minutos y piezas, no un «impacto operativo». Di quién tiene el relevo y a qué hora vuelve el puesto a su modo normal. Si queda una decisión para la sala, formúlala: si no queda, no inventes una."},{"kicker":"Evita","body":"No sueltes siglas en fila para parecer que dominas el tema. No simplifiques hasta borrar la causa: «se paró sola» no se puede arreglar. No eches el paro a «falta de compromiso» cuando la máquina cumplió una norma de seguridad."}],"example":{"speaker":"Iker","role":"responsable de planta","script":"Ayer, en la planta de Bilbao, la línea dos paró a las 14:12. El PLC, el equipo que ordena los movimientos, dejó de recibir la señal del motor que apila los palés, y la estación paró, como tiene que hacer si se queda a ciegas. Perdimos cuarenta minutos y dieciocho palés. El relevo de tarde ya lleva ese puesto en manual, con una persona guiándolo y un técnico del proveedor al lado. Mañana a las ocho cambiamos la pieza de comunicación, dentro de la parada corta de quince minutos. Si el repuesto no llega, seguimos en manual hasta mediodía, y no prometo otra cosa.","note":"Iker nombra el PLC y lo traduce en la misma frase. Luego hay daño, relevo y hora: no hay manual y no hay humo."},"quiz":[{"q":"Se para una línea. ¿Qué necesita oír quien dirige?","options":["Las siglas del fabricante y el esquema del armario.","Qué falló en una frase, qué costó y cuándo vuelve.","Que hubo un tema técnico y que el equipo está en ello."],"answer":1,"why":"Con causa, daño y hora se puede decidir. El esquema y el «tema técnico» no dejan un siguiente paso."},{"q":"¿Cuándo cabe decir PLC en voz alta?","options":["Cuando lo traduces en el mismo aliento a lo que hace en la máquina.","Siempre que la sala parezca técnica, aunque no lo hayas comprobado.","Nunca: cualquier palabra de oficio estorba."],"answer":0,"why":"El término justo, traducido, es más claro que un rodeo. Soltarlo sin traducción es jerga: prohibirlo siempre también esconde el oficio."},{"q":"La estación paró al perder la señal. ¿Cómo lo cuentas?","options":["Como una falta de carácter del turno.","Como un misterio que ya se investigará.","Como la máquina cumpliendo la norma de parar cuando no ve."],"answer":2,"why":"Parar a ciegas es lo que se le pidió. Contarlo como misterio o como culpa deja la causa fuera de alcance."}],"exercise":{"prompt":"Explica una parada o un fallo técnico a alguien que decide y no vive en tu armario. Traduce la sigla. Di el daño y la hora de vuelta.","seconds":90,"scaffold":["Qué se paró y a qué hora","La causa en una frase, traducida","Minutos y piezas","Quién lo tiene ahora","A qué hora vuelve, o hasta cuándo no prometes"],"focus":"clarity"}},{"id":"m3-data","module":3,"title":"Contar un dato","minutes":4,"framework":"Número comparado","promise":"Vas a soltar un número con una comparación y un sentido, en vez de una ristra de cifras.","focus":"structure","free":false,"cards":[{"kicker":"Por qué importa","body":"Un número sin comparación no dice si es mucho o poco. Dieciocho palés importan cuando se sabe de cuántos del turno salieron. El sentido es la frase de después: qué cambia, o qué vas a hacer, por ese número."},{"kicker":"Un solo número","body":"Elige un protagonista y deja el resto de apoyo, o en la nota. Redondea si el decimal es adorno y nadie lo va a usar. Di la comparación en la frase siguiente, no tres gráficos después."},{"kicker":"Cuatro golpes","body":"Número, comparación, sentido y petición. Si no hay petición, di qué harás tú con ese número y cuándo. La gráfica no habla: si la enseñas, di la frase que quieres que se lea."},{"kicker":"Evita","body":"No juntes presupuesto, plazo, chatarra y plantilla en el mismo aliento. No pongas un «solo» delante del número para quitarle peso. No leas la tabla en voz alta celda por celda."}],"example":{"speaker":"Lucía","role":"jefa de proyecto","script":"La cifra es once minutos de parada no prevista por turno, de media, en los últimos veinte turnos. Antes del cambio de sensor eran veintiséis. El sentido es que el cambio ya se pagó, y que once sigue siendo conversación y no un trofeo. El minuto que todavía podemos quitar está en el rearranque, porque se espera permiso. Propongo una regla: si el sensor es de verdad y la protección está cerrada, se rearranca sin llamar. La traigo en papel el jueves, no en una diapositiva.","note":"Un número, comparado con el de antes. Lucía no añade la moda ni el máximo: la petición es una regla con fecha."},"quiz":[{"q":"¿Qué le falta a un número dicho solo?","options":["Una comparación y una frase de qué significa.","Más decimales, para parecer exacto.","Otros cuatro números en la misma frase, para dar contexto."],"answer":0,"why":"Sin comparación, la sala no sabe si alegrarse o preocuparse. Más cifras juntas no orientan: compiten."},{"q":"En un minuto, ¿cuántos números protagonistas caben?","options":["Cinco, si hablas deprisa.","Todos los de la gráfica, por transparencia.","Uno, y los demás solo si sujetan a ese."],"answer":2,"why":"Un protagonista se recuerda y se puede discutir. La transparencia no obliga a leer la hoja entera."},{"q":"¿Qué petición queda bien pegada a un dato?","options":["Pedir que estemos atentos.","Traer el jueves, en papel, la regla de rearranque.","Decir que el dato es interesante y ya se verá."],"answer":1,"why":"La regla tiene verbo, forma y fecha. «Estar atentos» no cambia el minuto siguiente."}],"exercise":{"prompt":"Cuenta un dato de tu trabajo en cuatro golpes: el número, con qué lo comparas, qué significa y qué pides o qué harás.","seconds":60,"scaffold":["Un número","La comparación","El sentido","La petición con fecha"],"focus":"structure"}},{"id":"m4-spine","module":4,"title":"El espinazo del relato","minutes":5,"framework":"Espinazo","promise":"Vas a poder decir un caso en una frase: qué pasó, qué giro hubo y qué quedó.","focus":"structure","free":true,"cards":[{"kicker":"Por qué importa","body":"Un relato de trabajo no es la crónica de la semana. El espinazo cabe en un respiro: situación, giro y consecuencia. Si no puedes decir esa frase, todavía tienes notas, no un relato."},{"kicker":"Empieza tarde","body":"Entra en el momento en que el asunto se mueve. El lunes por la mañana sobra si el cuento es el martes a media mañana. El proveedor, el tiempo y la reunión previa entran solo si empujan el giro."},{"kicker":"Una acción","body":"Alguien hace algo: no «se gestionó». El resultado se puede mirar: minutos, piezas o una norma nueva. Si el final es que se aprendió mucho, el relato no ha acabado."},{"kicker":"Evita","body":"No conviertas la causa en un misterio si la sala tiene que decidir hoy. Puedes decir el espinazo primero y el detalle después. No metas dos historias en el mismo minuto."}],"example":{"speaker":"Mateo","role":"líder de equipo","script":"El espinazo es este: el martes se soltó el sensor, Nuria paró, y el jueves el soporte nuevo ya es la norma. Empiezo el martes, no en el histórico del sensor. A las diez y veinte la lectura se fue de rango y Nuria paró la estación sin pedir permiso. Perdimos dieciocho minutos y no salió ni una pieza mala. El jueves, mantenimiento dejó una segunda brida y la instrucción de parar está en la pizarra. La charla del café no entra, porque no movió el resultado.","note":"La primera frase ya se puede repetir. Mateo nombra a Nuria, que es quien hizo el giro, y corta lo que no cambia el final."},"quiz":[{"q":"¿Qué es el espinazo?","options":["El organigrama de quienes estaban aquel día.","Una moraleja del tipo «aprendimos mucho».","Una frase con situación, giro y consecuencia."],"answer":2,"why":"Esa frase es la que tiene que sobrevivir si se acaba el tiempo. Sin giro y sin consecuencia solo hay ambiente."},{"q":"¿Por dónde conviene empezar?","options":["Tarde, en el momento en que el asunto se mueve.","El lunes a primera hora, por respeto al orden.","Por tu cargo, para que se entienda quién narra."],"answer":0,"why":"Empezar tarde quita la crónica y deja el giro. El cargo no es un comienzo: es un crédito que se gana con el relato."},{"q":"¿Qué sobra si no cambia el resultado?","options":["El nombre de quien paró.","La charla del café y el histórico entero.","Los minutos perdidos."],"answer":1,"why":"Lo que no mueve el giro estorba a quien intenta repetir la historia. El nombre y los minutos sí son el giro y la consecuencia."}],"exercise":{"prompt":"Cuenta un caso real de tu trabajo. Primero la frase-espinazo, de un respiro. Luego solo el detalle que prueba esa frase.","seconds":75,"scaffold":["Situación, giro y consecuencia","El momento en que empieza","Quién hizo qué","Qué quedó, en algo que se puede mirar","Qué dejas fuera"],"focus":"structure"}},{"id":"m4-hero","module":4,"title":"El héroe es tu equipo","minutes":4,"framework":"Nombres","promise":"Vas a nombrar a quien hizo el trabajo y a quedarte, en primera persona, solo lo que de verdad decidiste.","focus":"structure","free":false,"cards":[{"kicker":"Por qué importa","body":"Si el héroe de cada historia eres tú, se oye un ascenso y no un parte. El trabajo tiene nombres y el tuyo va en la decisión, en el obstáculo que quitaste o en el error. «Lo hizo el equipo» es educado y no se puede repetir."},{"kicker":"Nombres","body":"Di el nombre y el gesto: qué hizo esa persona que cambió el resultado. Si no puedes, es que no lo viste, y entonces no toca elogiarlo todavía. Un elogio sin gesto no enseña qué repetir mañana."},{"kicker":"El yo","body":"Di yo en la decisión que sí tomaste y en el error que te quedas. No uses el nosotros para esconder una decisión tuya. No uses el yo para el banco de pruebas que montó otra persona."},{"kicker":"Evita","body":"No regales tu decisión a «todos» para parecer humilde. No te comas el mérito ajeno con un «bajo mi liderazgo». No cierres con un elogio tan redondo que no haya un gesto dentro."}],"example":{"speaker":"Ane","role":"líder de equipo","script":"La prueba del viernes salió porque Nuria montó el banco el miércoles. Yo quité el informe extra para que ella tuviera esa tarde. Ander trajo el sensor de Hartmann un día antes. El fallo de medida lo vio Lena y paró, que era lo que tocaba. Yo me quedo la decisión de no salir el jueves. Si este relato sale de la sala, sale con esos nombres.","note":"Ane no dice «el equipo» como un bloque. Se queda una decisión que era suya y no se atribuye el banco ni el sensor."},"quiz":[{"q":"¿A quién nombra un relato de trabajo bien contado?","options":["Solo a quien habla, porque si no, no se ve el liderazgo.","A quien hizo el gesto y a quien tomó la decisión, cada uno en lo suyo.","A todo el equipo, que queda más humilde."],"answer":1,"why":"El gesto y la decisión son cosas distintas y las dos caben. El bloque «todo el equipo» no deja nada que copiar."},{"q":"¿Cuándo dices yo?","options":["En cada verbo, para que se note quién lleva el tema.","Nunca: el yo resta presencia.","En la decisión o en el error que sí eran tuyos."],"answer":2,"why":"El yo preciso no es vanidad. El yo en el trabajo ajeno, y el nosotros que esconde, son las dos formas de liar el mérito."},{"q":"«Lo hicimos entre todos» falla cuando…","options":["Nadie podría decir qué hizo cada persona.","El trabajo fue compartido y luego das el detalle.","Cierras dando las gracias."],"answer":0,"why":"Sin gesto, la frase es cortesía. Con detalle detrás, el «entre todos» ya no esconde a nadie."}],"exercise":{"prompt":"Cuenta un resultado reciente con tres nombres como máximo. Di qué hizo cada persona y qué decisión te quedas tú. Prohibido «el equipo» a secas.","seconds":60,"scaffold":["El resultado","Nombre y gesto","Otro nombre, si hace falta","La decisión que es tuya"],"focus":"structure"}},{"id":"m4-vulnerability","module":4,"title":"Vulnerabilidad con propósito","minutes":4,"framework":"Fallo y cambio","promise":"Vas a admitir un fallo con su coste y con el cambio ya en marcha, y vas a acabar en el cambio.","focus":"presence","free":false,"cards":[{"kicker":"Para qué sirve","body":"En el trabajo, una admisión útil es concreta: qué hiciste, qué costó y qué has cambiado. No es una confesión y no le pide a la sala que te cuide. Sirve para que la próxima persona no repita el mismo hueco."},{"kicker":"Un fallo","body":"Uno, no el catálogo de tus dudas. El coste en minutos, en dinero o en confianza, sin adjetivo de más. El cambio tiene que estar ya en marcha, no en un «habrá que pensar»."},{"kicker":"El final","body":"Acaba en la norma nueva. Si acabas en la culpa, la sala se queda contigo y no con el arreglo. Quien te oye tiene que salir sabiendo qué hacer con el próximo aviso."},{"kicker":"Evita","body":"No culpes al calendario y lo llames honestidad. No cuentes un fallo ajeno como si fuera tuyo para parecer modesto. No abras un fallo que no vas a cerrar en la misma intervención."}],"example":{"speaker":"Iker","role":"responsable de planta","script":"El martes la línea paró porque el módulo no estaba en el almacén, y el retraso del pedido es mío. Vi el aviso la semana anterior y lo dejé detrás de un informe. Esos cuarenta minutos salieron de esa espera, no del turno que estaba delante de la máquina. Desde ayer hay un repuesto en la estantería y el aviso me llega a mí. No pido que nadie adivine un hueco de almacén. Si falta una pieza que puede parar la línea, va a la pizarra el mismo día, aunque sobre.","note":"Iker se queda el fallo, dice el coste y acaba en la norma. No pide consuelo y no reparte la culpa con el turno."},"quiz":[{"q":"¿Qué admisión sirve delante de un equipo?","options":["Un fallo, su coste y un cambio que ya está en marcha.","Un repaso de cómo te sentó la semana.","Un fallo de otro turno, contado para quedar modesto."],"answer":0,"why":"El coste y el cambio convierten la admisión en una norma. El ánimo de la semana y la culpa ajena no dejan un siguiente paso."},{"q":"¿Dónde acaba ese relato?","options":["En la culpa, para que se note que te importa.","En la norma nueva, dicha de forma que otra persona pueda cumplirla.","En una pregunta al equipo sobre cómo lo habría hecho."],"answer":1,"why":"El final útil es la conducta que cambia. Quedarte en la culpa obliga a la sala a consolarte en vez de a copiar la norma."},{"q":"¿Qué no es este modo de hablar?","options":["Un parte con dueño.","Una norma que se puede copiar.","Una confesión que la sala tenga que cuidar."],"answer":2,"why":"Hay dueño y hay norma. No hay un rato de cuidado personal: el fallo se cierra con un cambio de trabajo."}],"exercise":{"prompt":"Admite un fallo real de tu oficio. Una frase para el fallo, una para el coste y una para el cambio que ya has puesto en marcha. Acaba en la norma.","seconds":60,"scaffold":["Qué hiciste o qué dejaste","Qué costó, en algo concreto","Qué has cambiado ya","La norma para la próxima vez"],"focus":"presence"}},{"id":"m4-vision","module":4,"title":"Relatos de visión","minutes":5,"framework":"Frase de visión","promise":"Vas a decir hacia dónde vais de forma que una persona nueva sepa qué hacer el jueves.","focus":"pitch","free":false,"cards":[{"kicker":"La frase","body":"Una visión que sirve cabe en un respiro. Nombra un estándar y a quién le importa. Si vale para cualquier empresa con solo cambiar el logo, no es tuya."},{"kicker":"El tono","body":"Puedes levantar un poco la voz en la imagen. Tienes que aterrizar en el estándar: la última palabra baja. Si acabas en uptalk, la visión pide permiso en vez de marcar un rumbo."},{"kicker":"Esta semana","body":"Tres hábitos de esta semana valen más que tres palabras de póster. Cuéntalo como si alguien hubiera entrado el mes pasado: qué vería en la pizarra o en el relevo. Cierra con el hábito que empiezas tú, no con un encargo al aire."},{"kicker":"Evita","body":"No abras con que sueñas un mundo mejor. No apiles cinco adjetivos donde hacía falta un estándar. No pidas un aplauso: pide una conducta."}],"example":{"speaker":"Lucía","role":"jefa de proyecto","script":"Quiero un relevo en el que la pizarra ya sea verdad antes de que hable nadie. Eso le importa a quien entra de noche y no debería tener que adivinar. El estándar es cinco minutos, tres líneas y un riesgo escrito aunque incomode. Esta semana se ve en tres hábitos: nota firmada, dueño antes de salir y el fallo dicho el mismo día. Esta frase es una decisión, no una pregunta. El hábito que empiezo yo es firmar mi nota hoy, no el mes que viene.","note":"La visión nombra el relevo, no la excelencia. Lucía aterriza en hábitos de esta semana y en uno que hace ella."},"quiz":[{"q":"¿Qué le pasa a un eslogan que serviría en cualquier empresa?","options":["Que inspira más, porque es amplio.","Que al comité le cuesta menos de discutir.","Que no le dice a una persona nueva qué hacer el jueves."],"answer":2,"why":"Sin estándar, no hay conducta. Lo amplio se aplaude y no se ejecuta."},{"q":"¿Dónde aterriza el tono de la frase de visión?","options":["Sube al final, para que suene a futuro.","Baja en el estándar concreto.","Se queda en una sola nota, para no influir."],"answer":1,"why":"El futuro se oye en el contenido, no en una pregunta disfrazada. Aterrizar marca que el estándar no está en duda."},{"q":"¿Con qué cierras?","options":["Con un hábito que empiezas tú esta semana.","Con la frase «yo sueño con un sitio mejor».","Con tres adjetivos y una pausa para el aplauso."],"answer":0,"why":"El hábito propio demuestra que la visión no es un encargo a los demás. El sueño y el aplauso no cambian el relevo del jueves."}],"exercise":{"prompt":"Di una frase de visión de tu equipo que no valga para la empresa de enfrente. Añade tres hábitos de esta semana y uno que empiezas tú. La última palabra, con el tono que baja.","seconds":75,"scaffold":["La frase, con estándar","A quién le importa","Tres hábitos de esta semana","El que empiezas tú","Aterriza"],"focus":"pitch"}},{"id":"m5-standup","module":5,"title":"El stand-up","minutes":4,"framework":"BLUF","promise":"Vas a decir el bloqueo en la primera frase y a dejar el stand-up en un minuto.","focus":"structure","free":true,"cards":[{"kicker":"Por qué importa","body":"La reunión de arranque no es un informe: es un filtro. Si hay bloqueo, el bloqueo va primero. Eso es BLUF metido en sesenta segundos."},{"kicker":"El minuto","body":"Bloqueo, qué haces hoy y qué necesitas, con un nombre. Ayer solo entra si cambia el día de hoy. Un bloqueo, no tres, y el parte largo se queda en la pizarra."},{"kicker":"Si no hay bloqueo","body":"Dilo y no inventes uno para tener tema. Habla de tu trabajo, no del de al lado, salvo que el bloqueo sea exactamente ese. Si te pasas del minuto, te comes el minuto de otra persona."},{"kicker":"Evita","body":"No cuentes la película de ayer. No digas que no hay bloqueo y luego sueltes uno disfrazado de comentario. No decidas aquí un tema que necesita media hora: aparcalo y ponle hora."}],"example":{"speaker":"Iker","role":"responsable de planta","script":"El bloqueo es el módulo de comunicación del puesto que apila palés: no está en el almacén. Hoy la línea dos arranca con ese puesto en manual y con Nuria de apoyo la primera hora. Ayer perdimos cuarenta minutos y no quiero otro relevo a ciegas. Llamo al proveedor a las nueve y media y dejo en la pizarra si el repuesto entra hoy. Si no entra, seguimos en manual y lo digo en el parte de las doce. Lo demás del turno va como está escrito en la pizarra.","note":"Iker abre el arranque de la planta por el bloqueo. Hay una hora de vuelta, las doce, y no hay crónica del turno anterior."},"quiz":[{"q":"Hay un bloqueo y tienes un minuto. ¿Qué va primero?","options":["El relato de ayer, para situar al turno.","El bloqueo, en la primera frase.","Una ronda de cómo llega el ánimo."],"answer":1,"why":"El bloqueo es lo único que puede cambiar el día de los demás. El ánimo y la película de ayer no desbloquean el repuesto."},{"q":"No hay bloqueo. ¿Qué dices?","options":["Que no lo hay, qué haces hoy, y paras.","Un bloqueo menor, inventado, para no quedar en blanco.","El histórico de la semana, ya que el minuto es tuyo."],"answer":0,"why":"Decir que no hay bloqueo es información. Inventar uno o alargar el histórico le roba el minuto al siguiente."},{"q":"¿Qué no se decide en el stand-up?","options":["Quién apoya el puesto la primera hora.","Si la línea arranca en manual.","Un asunto que necesita media hora: se aparca y se le pone hora."],"answer":2,"why":"La ronda corta admite un sí pequeño y un aparque. El debate de media hora revienta el formato y deja al resto sin hablar."}],"exercise":{"prompt":"Haz tu stand-up de un minuto. Si hay bloqueo, primera frase. Si no lo hay, dilo. Cierra con lo que necesitas y de quién, o con un silencio.","seconds":60,"scaffold":["Bloqueo o titular","Qué haces hoy","Qué necesitas y de quién","Para"],"focus":"structure"}},{"id":"m5-chair","module":5,"title":"Dirigir y medir el tiempo","minutes":5,"framework":"Reloj","promise":"Vas a repartir los minutos en voz alta y a guardar un tramo final para los nombres, con gente todavía sentada.","focus":"pace","free":false,"cards":[{"kicker":"El reloj","body":"Quien preside marca el ritmo. Si aceleras el cierre, el cierre no existe. Al entrar, di cuántos minutos hay, qué se decide y cuánto le das a cada punto."},{"kicker":"Aparca","body":"Un tema que se va se aparca en voz alta: queda al margen y hoy no se sigue. No hace falta un tono duro: hace falta decirlo antes de que el margen se coma la decisión. Pide que te avisen si te vas siempre con la primera persona que habla."},{"kicker":"El cierre","body":"Cierra con tiempo todavía en el reloj, no cuando la gente ya se levanta. Esos minutos son para repetir nombre y fecha. Acabar con el portátil cerrado no es cerrar: es terminar."},{"kicker":"Evita","body":"No corrijas el monólogo con un discurso sobre la participación: pasa el turno diciendo un nombre. No añadas un punto nuevo en el último minuto. No pidas perdón cada vez que cortas: cortar a tiempo es el encargo."}],"example":{"speaker":"Lucía","role":"jefa de proyecto","script":"Tenemos veinticinco minutos y tres decisiones. Doy seis a cada una y guardo siete al final para nombres y fechas. Si un tema interesa y no es una de las tres, lo apunto al margen y hoy no lo seguimos. Que alguien me avise si me dejo llevar por quien habla primero. Esta reunión sale bien si salimos con nombres, no si habló todo el mundo. A las diez y veinte, pase lo que pase en el tercer punto, cierro.","note":"Lucía dice el reloj al entrar y reserva el final. Cortar no viene con una disculpa."},"quiz":[{"q":"¿Qué dices al abrir si presides?","options":["Cuántos minutos hay, qué se decide y cuánto dura cada punto.","Que serás flexible con el reloj para que la conversación fluya.","El acta anterior, entera, por rigor."],"answer":0,"why":"El reparto dicho en voz alta permite que te ayuden a cumplirlo. La flexibilidad sin número es la forma educada de no presidir."},{"q":"Un tema interesante se sale de las tres decisiones. ¿Qué haces?","options":["Lo sigues, porque cortar queda feo.","Le das diez minutos más y recortas el cierre.","Lo apuntas al margen y dices que hoy no se sigue."],"answer":2,"why":"Aparcar en voz alta conserva el tema sin regalarle la reunión. Recortar el cierre es regalar los nombres y las fechas."},{"q":"¿Para qué guardas minutos al final?","options":["Para un turno abierto de comentarios generales.","Para repetir nombre y fecha con la gente todavía sentada.","Para adelantar el primer punto de la semana que viene."],"answer":1,"why":"El cierre necesita oyentes, no una sala que ya se va. Los comentarios abiertos y el punto nuevo se comen justo esos minutos."}],"exercise":{"prompt":"Abre una reunión que presidas de verdad o una que te toque. Di el tiempo, las decisiones y el minuto en el que cerrarás pase lo que pase. Aparca un tema imaginario en una frase.","seconds":75,"scaffold":["Minutos y decisiones","Cuánto dura cada una","Una frase para aparcar","A qué hora cierras"],"focus":"pace"}},{"id":"m5-disagree","module":5,"title":"Disentir y comprometerse","minutes":4,"framework":"Disentir y comprometerse","promise":"Vas a discrepar del punto, proponer otra vía y, si no sale la tuya, decir en voz alta que la vas a ejecutar.","focus":"structure","free":false,"cards":[{"kicker":"Por qué importa","body":"Un desacuerdo dicho a medias acaba en el pasillo. Decirlo una vez, sobre el punto y con otra vía, ahorra la segunda reunión. Comprometerse después es decir que lo vas a hacer, no callarte y cumplirlo a regañadientes."},{"kicker":"Haz esto","body":"Nombra el riesgo concreto, no a la persona. Di qué harías tú y qué coste tiene. Si pierdes, una frase: no es mi opción y la voy a ejecutar, con el riesgo escrito y con tu nombre."},{"kicker":"En el desacuerdo","body":"Discrepa de la fecha, del alcance o del dato. No acumules tres reproches viejos para ganar este. Una vez basta: repetirlo en la misma sala es campaña, no criterio."},{"kicker":"Evita","body":"No lo deshagas con una risa al final. No lo guardes para el café. No digas que te comprometes y luego lo cuentes fuera como una decisión en la que tú no estabas."}],"example":{"speaker":"Mateo","role":"líder de equipo","script":"Veo el atractivo de salir el viernes y no estoy de acuerdo. La prueba que nos saltaríamos es la que falló el mes pasado. Si salimos y vuelve a fallar, perdemos la fecha y la confianza. Propongo el lunes, con la prueba en medio. Si la sala elige el viernes, lo ejecuto y dejo el riesgo escrito en la nota, con mi nombre. No lo reabro en el pasillo.","note":"Mateo discrepa una vez y deja una alternativa. El compromiso no es un sí entusiasta: es ejecución, con el riesgo a la vista."},"quiz":[{"q":"¿De qué discrepas?","options":["De quien propone la fecha, si suele equivocarse.","Del tono con el que se está hablando.","Del punto: la fecha, el alcance o el dato."],"answer":2,"why":"El punto se puede cambiar con un argumento. La persona y el tono convierten el desacuerdo en una pelea que no decide nada."},{"q":"La sala elige lo contrario. ¿Qué frase cierra de verdad?","options":["No es mi opción y la voy a ejecutar, con el riesgo escrito.","Ya lo dije: que cada cual haga luego lo que quiera.","Vale, como se prefiera, dicho con una risa."],"answer":0,"why":"Ejecutar y dejar el riesgo por escrito cierra el tema. La risa y el «ya lo dije» lo dejan abierto para el pasillo."},{"q":"¿Cuántas veces hace falta repetir el desacuerdo en la misma reunión?","options":["Las que hagan falta hasta cambiar el voto.","Una, con alternativa. Repetirlo abre otra discusión.","Ninguna: se manda un correo al día siguiente y ya está."],"answer":1,"why":"Una vez, clara, cabe en el acta. La campaña dentro de la sala cansa y no añade un dato nuevo."}],"exercise":{"prompt":"Discrepa de una decisión reciente o inventa una creíble. Una vez, con alternativa. Cierra como si hubieras perdido: di que la ejecutas y qué riesgo dejas escrito.","seconds":60,"scaffold":["El punto del que discrepas","Tu alternativa","El coste de la otra","Si pierdes: lo ejecuto y dejo el riesgo"],"focus":"structure"}},{"id":"m5-quiet","module":5,"title":"Hacer hablar a quien calla","minutes":4,"framework":"La espera","promise":"Vas a preguntar a una persona por su nombre, callar dos tiempos y no contestar tú.","focus":"pauses","free":false,"cards":[{"kicker":"Por qué importa","body":"«¿Alguien añade algo?» se lo queda quien ya habla. Quien calla suele tener el dato del turno, de la prueba o del cliente. La pausa es la herramienta, no un hueco de quien preside."},{"kicker":"Haz esto","body":"Di el nombre y una pregunta que solo esa persona puede responder. Cierra la boca y cuenta dos tiempos. Si responde corto, pide un ejemplo y no le completes la frase."},{"kicker":"La pausa","body":"El silencio después del nombre es la invitación. No mires a otra persona mientras esperas: le quitas el turno. Si de verdad no tiene nada, te lo dirá, y entonces sigues sin castigarle el silencio."},{"kicker":"Evita","body":"No preguntes al aire. No encadenes tres preguntas antes de la primera respuesta. No uses la pausa para preparar tu siguiente monólogo."}],"example":{"speaker":"Ane","role":"líder de equipo","script":"Antes de cerrar el parte quiero oír a quien estuvo de noche. Ander, tú cerraste ese turno. Qué no dejarías tocar esta mañana. Lo que digas queda en la pizarra como no tocar, arrancar o parar. Irá con tu nombre, no con el mío. Cuando acabes, seguimos, y no te completo la frase.","note":"Entre la pregunta y cualquier otra frase de Ane hay dos tiempos de silencio. Ella no propone la respuesta ni mira al resto para que alguien la salve."},"quiz":[{"q":"¿A quién le hablas si quieres oír a quien calla?","options":["Al aire, con un «¿alguien tiene algo?».","A una persona, por su nombre, con una pregunta que le toca.","A quien ya tiene la mano levantada, para ir más rápido."],"answer":1,"why":"El nombre entrega el turno. La pregunta al aire se la queda la voz de siempre."},{"q":"¿Qué haces justo después de la pregunta?","options":["La contestas tú, para ayudar.","Haces otra, por si la primera no era clara.","Cierras la boca y cuentas dos tiempos."],"answer":2,"why":"Esos dos tiempos son el sitio donde cabe la respuesta. Ayudar con tu propia frase se la come."},{"q":"El silencio se alarga. ¿Qué no haces?","options":["Mirar a otra persona y contestar tú.","Mantener la mirada en quien nombraste.","Aceptar un «ahora no tengo nada» y seguir."],"answer":0,"why":"Cambiar de mirada anula la invitación. Aceptar un no breve es respetar el turno, no rendirse."}],"exercise":{"prompt":"Formula en voz alta una pregunta a una persona concreta de tu equipo, de las que hablan poco. Di la pregunta y calla dos tiempos de verdad. No la completes.","seconds":50,"scaffold":["El nombre","La pregunta concreta","Dos tiempos de silencio","Si acaso, pide un ejemplo"],"focus":"pauses"}},{"id":"m5-close","module":5,"title":"Cerrar con dueño y fecha","minutes":4,"framework":"Cierre","promise":"Vas a salir con una decisión, un nombre, una fecha y una frase de qué cuenta como hecho.","focus":"structure","free":false,"cards":[{"kicker":"Por qué importa","body":"Una decisión sin nombre es un deseo. Una fecha sin definición de hecho es la discusión de la semana que viene. El cierre es lo que se lleva quien no se llevó nada más."},{"kicker":"Haz esto","body":"Repite qué se decidió, quién lo hace, para cuándo y cómo se sabrá. Escríbelo donde se vea mientras lo dices. Pide a esa persona una frase de confirmación, no un gesto."},{"kicker":"Al cierre","body":"Si nadie acepta el nombre, no hay decisión: vuelve a la pregunta. Si la fecha es «cuando se pueda», pon una de verdad o di que queda abierto. Abierto y dicho es más honesto que una fecha de adorno."},{"kicker":"Evita","body":"No cierres con «luego lo pasamos a limpio» si no has dicho el contenido. No asignes a quien no está sin encargar, hoy, que se le avise. No abras un tema nuevo después del cierre."}],"example":{"speaker":"Lucía","role":"jefa de proyecto","script":"Queda decidido mover la entrega al día doce. La dueña es Nuria: confirma el banco el miércoles y me escribe a las tres. Hecho significa banco montado y sensor en la mesa, no un correo de intención. Lo escribo en la nota mientras lo digo. Nuria, ¿lo repites en una frase? Si el miércoles a las tres no hay nota, lo reabro yo el jueves por la mañana.","note":"Hay dueña, fecha y una definición de hecho que se puede comprobar. Lucía pide la frase y dice qué pasa si no llega."},"quiz":[{"q":"¿Qué lleva un cierre que se puede ejecutar?","options":["Decisión, nombre, fecha y qué cuenta como hecho.","Un resumen inspirador y las gracias.","El acta entera, leída otra vez."],"answer":0,"why":"Sin la definición de hecho, la fecha se discute cuando alguien crea que ya cumplió. Las gracias no asignan el trabajo."},{"q":"Nadie acepta el nombre. ¿Qué haces?","options":["Se lo asignas a quien no está, para poder irte.","Vuelves a la pregunta: sin nombre no hay decisión.","Lo dejas en «el equipo» y cierras igual."],"answer":1,"why":"Un nombre que nadie ha aceptado es un deseo con aspecto de acta. Parar ahí es más limpio que inventar un responsable."},{"q":"¿Para qué pides que la persona lo repita?","options":["Para examinar si prestaba atención.","Para alargar y que conste participación.","Para oír un sí con palabras, no un gesto que luego no recuerda nadie."],"answer":2,"why":"La frase dicha por quien se queda el tema es el compromiso. Un gesto se evapora en cuanto se apaga la sala."}],"exercise":{"prompt":"Cierra una reunión real o reciente. Di la decisión, el nombre, la fecha y qué cuenta como hecho. Pide, en voz alta, la frase de confirmación.","seconds":60,"scaffold":["Qué se decidió","Quién","Para cuándo","Qué es hecho","La frase que le pides"],"focus":"structure"}},{"id":"m6-sbii","module":6,"title":"Feedback SBI(I)","minutes":5,"framework":"SBI","promise":"Vas a comentar una conducta que se podría haber visto, con su efecto en el trabajo, y a preguntar la intención solo si hace falta.","focus":"structure","free":true,"cards":[{"kicker":"Por qué importa","body":"SBI es situación, comportamiento e impacto. La segunda I, si la usas, es una pregunta por la intención, no una sentencia. El mismo molde sirve para corregir y para reconocer: cambia el contenido, no la forma."},{"kicker":"La cámara","body":"Situación: cuándo y dónde, en concreto. Comportamiento: el gesto que una cámara o un correo mostrarían, no un rasgo. Una conducta por conversación."},{"kicker":"El impacto","body":"Di qué se torció o qué se salvó en el trabajo: el dato, el cliente, la decisión. Puedes nombrar que la sala se quedó sin la cifra. Pregunta qué buscaba solo cuando el gesto admite más de una lectura."},{"kicker":"Evita","body":"No abras con «no te lo tomes a mal» ni con un «siempre». No apiles tres conductas ya que estás. No diagnostiques el carácter: poco riguroso, poco comprometido, cerrado."}],"example":{"speaker":"Mateo","role":"líder de equipo","script":"El jueves mandaste el parte al cliente sin la cifra de la parada. En la reunión de las cuatro el cliente cerró el plazo con un parte al que le faltaba ese número. La cifra estaba en tu cuaderno y no estaba en el correo. No te atribuyo una intención: te describo lo que salió. Te pido que el parte no salga si le falta el número que cambia la decisión. Esta semana me lo enseñas antes de enviarlo, y el número va en la primera línea.","note":"Hay día, gesto e impacto en la decisión del cliente. Mateo no dice «eres descuidado» y el pedido es uno."},"quiz":[{"q":"¿Qué cuenta como comportamiento en un SBI?","options":["Un rasgo: eres poco riguroso.","La intención que tú supones.","Un gesto que se podría haber leído en el correo o visto en la sala."],"answer":2,"why":"El gesto se puede reconocer y cambiar. El rasgo se discute y no se puede practicar el jueves."},{"q":"¿Qué impacto merece la conversación?","options":["Cómo te sentó, como asunto principal.","Qué se torció en el trabajo: el dato, el cliente o la decisión.","Una lista de otras veces, para que se vea que no es la primera."],"answer":1,"why":"El impacto de trabajo le dice al otro qué proteger la próxima vez. La lista de veces convierte una conducta en un juicio."},{"q":"¿Cuándo preguntas por la intención?","options":["Cuando el gesto admite más de una lectura, y lo preguntas sin sentenciarlo.","Siempre, para suavizar, aunque el hecho ya sea claro.","Nunca: preguntarla es perder el tiempo."],"answer":0,"why":"La pregunta evita que te inventes el motivo. Usarla de adorno, o prohibirla siempre, las dos estorban."}],"exercise":{"prompt":"Prepara un SBI real, correctivo o de reconocimiento. Una conducta. Situación, gesto, impacto y un pedido. Sin adjetivos de carácter.","seconds":75,"scaffold":["Cuándo y dónde","Qué se vio o se leyó","Qué cambió en el trabajo","El pedido, uno","Si hace falta, la pregunta por la intención"],"focus":"structure"}},{"id":"m6-receive","module":6,"title":"Recibir feedback sin defenderse","minutes":4,"framework":"Primero el ejemplo","promise":"Tu primera frase no va a ser una defensa. Vas a poder repetir el gesto antes de discutir el contexto.","focus":"presence","free":false,"cards":[{"kicker":"Por qué importa","body":"La defensa inmediata enseña que no vale la pena volverte a comentar nada. El contexto casi siempre existe y casi nunca cabe en el primer aliento. Primero se demuestra que has oído el gesto."},{"kicker":"Haz esto","body":"Pide cuándo y qué se vio. Repite tú la conducta y el efecto, y pregunta si es eso. El contexto, o el desacuerdo, van en la segunda parte."},{"kicker":"Si es justo","body":"Di qué cambias y para cuándo. Si es vago, pide el gesto: sin gesto no hay nada que practicar. «Yo lo viví distinto» cabe cuando ya puedes repetir lo que el otro vio."},{"kicker":"Evita","body":"No abras con «es que». No expliques la semana entera. No lleves la conversación a cómo te lo dicen para no mirar lo que hiciste."}],"example":{"speaker":"Ane","role":"líder de equipo","script":"Quiero el ejemplo antes de contarte el contexto. ¿Cuándo fue y qué hice en ese momento? Si te oigo bien, la cifra no llegó a la pizarra porque hablé por encima. ¿Es eso, o hubo otro momento? El contexto lo doy cuando confirmes el gesto. Si es ese, el jueves dejo terminar la cifra y se puede ver en la sala.","note":"Ane no entra con el «es que el tiempo se nos iba». Repite el gesto y deja el contexto para cuando las dos personas hablen de lo mismo."},"quiz":[{"q":"¿Cuál es una primera frase útil?","options":["Es que el contexto era otro y, visto entero, se entiende.","Quiero el ejemplo: cuándo fue y qué viste.","Gracias, muchísimas gracias, tomo nota de todo en general."],"answer":1,"why":"El ejemplo permite hacer algo el jueves. El contexto por delante y el agradecimiento vago no fijan el gesto."},{"q":"¿Cuándo cabe decir que lo viviste de otra forma?","options":["Después de poder repetir la conducta y el efecto.","En la primera frase, para que no quede flotando.","Nunca: recibir es aceptar siempre el relato del otro."],"answer":0,"why":"Discrepar sin haber repetido suena a no haber oído. Aceptar siempre tampoco es oficio: a veces el gesto está mal contado."},{"q":"Te dicen «hay que ser más profesional». ¿Qué pides?","options":["Perdón, y cambias de tema.","Una nota general para la evaluación.","El gesto concreto, porque sin eso no hay nada que cambiar."],"answer":2,"why":"«Profesional» no se puede practicar. El gesto sí: una interrupción, un correo, una cifra que faltó."}],"exercise":{"prompt":"Imagina un comentario que te costaría encajar. Responde en voz alta sin defenderte. Pide el ejemplo, repítelo y solo después da una línea de contexto o de cambio.","seconds":60,"scaffold":["Pides cuándo y qué","Repites el gesto","Confirmas","Luego el contexto o el cambio con fecha"],"focus":"presence"}},{"id":"m6-recognition","module":6,"title":"Reconocimiento que mueve","minutes":4,"framework":"SBI","promise":"Vas a reconocer un gesto concreto, cerca del día en que ocurrió, de forma que se pueda repetir.","focus":"presence","free":false,"cards":[{"kicker":"Por qué importa","body":"«Buen trabajo» no dice qué copiar. El reconocimiento que mueve usa situación, conducta e impacto. El gesto tiene que ser uno que quieras volver a ver."},{"kicker":"Cerca del hecho","body":"Dilo cuando ha pasado, no lo archives para diciembre. En público, si marca un estándar para quien esté de turno la próxima vez. En privado, si el contenido es delicado o si a esa persona el escenario le estorba el mensaje."},{"kicker":"El efecto","body":"Nombra piezas, minutos o una decisión que salió bien por ese gesto. Deja la frase sola un momento: no le enganches un encargo nuevo. No lo uses de prólogo de una crítica: se aprende a no fiarse del elogio."},{"kicker":"Evita","body":"No elogies el carácter. No lo repartas tan parejo que nadie sepa por qué le tocó. No lo hagas tan largo que el gesto desaparezca."}],"example":{"speaker":"Lucía","role":"jefa de proyecto","script":"El martes, cuando la lectura se fue de rango, paraste la estación sin esperar a que alguien te autorizara. Perdimos dieciocho minutos y no salió una pieza mala. Esa es la parada que quiero en este proyecto cuando el dato no cuadra. Lo digo aquí porque el estándar es para quien esté la próxima vez, no solo para ti. En esta frase no te pido nada más. Si el dato vuelve a irse, quiero la misma parada.","note":"Lucía nombra el día, el gesto y las piezas. No lo engancha a una crítica ni a un encargo nuevo."},"quiz":[{"q":"¿Qué reconocimiento se puede repetir?","options":["El que dice cuándo, qué hizo la persona y qué cambió en el trabajo.","Un «buen trabajo» dicho con ganas.","Un elogio al carácter: eres de los que se implican."],"answer":0,"why":"El gesto se puede copiar el martes siguiente. El carácter no cabe en una instrucción de turno."},{"q":"¿Cuándo tiene sentido decirlo delante del equipo?","options":["Siempre, porque lo privado no cuenta.","Nunca, porque el elogio público estorba.","Cuando el gesto es el estándar que quieres que el resto copie."],"answer":2,"why":"El público sirve al estándar, no al lucimiento de quien elogia. Si el contenido es delicado, el privado protege el mensaje."},{"q":"¿Qué no pegas a esa frase?","options":["El día y el efecto en el trabajo.","Una crítica o un encargo nuevo.","El nombre de la persona."],"answer":1,"why":"La crítica pegada enseña a esperar el golpe detrás del elogio. El reconocimiento se queda un momento solo, y luego ya habrá otro hueco para el encargo."}],"exercise":{"prompt":"Reconoce un gesto real de esta semana. Día, qué hizo la persona, qué cambió. Sin «buen trabajo» a secas y sin encargo en la misma frase.","seconds":50,"scaffold":["Cuándo","El gesto","El efecto en el trabajo","Calla un segundo"],"focus":"presence"}},{"id":"m6-difficult","module":6,"title":"Conversaciones difíciles","minutes":5,"framework":"El punto primero","promise":"Vas a abrir lo incómodo con el punto en la primera frase, sin la pila de perdones y de es que.","focus":"fillers","free":false,"cards":[{"kicker":"Por qué importa","body":"Lo que se aplaza se llena de muletillas. «A ver, perdona, no sé si es el momento, es que» avisa de que tú tampoco quieres decirlo. La otra persona se prepara para defenderse antes de oír el hecho."},{"kicker":"Haz esto","body":"Primera frase: el punto. Luego un SBI corto, el pedido y silencio. El cuidado está en el dato preciso, no en el preámbulo."},{"kicker":"Antes de entrar","body":"Di la frase en voz alta a solas: si no te sale, no está lista. Un asunto por conversación. Prepara también qué aceptarás como siguiente paso, para no improvisar una amenaza."},{"kicker":"Evita","body":"No acumules perdona. No digas siempre ni nunca. No te rías al final para deshacer lo que acabas de pedir."}],"example":{"speaker":"Iker","role":"responsable de planta","script":"Quiero hablar de las tres últimas rondas de seguridad. La del jueves no está hecha y la del martes solo tiene la firma. Sin esa ronda no sé si alguien miró el portón sur. No te estoy diciendo que la planta te dé igual. Te digo que la ronda se firma cuando se ha andado, y esta semana la hacemos juntos a las ocho. Si a las ocho no puedes, lo dices hoy, y no se queda otra vez en blanco.","note":"Iker no abre con perdona ni con a ver. Hay un pedido con hora, y la última frase deja sitio para una alternativa en vez de una amenaza."},"quiz":[{"q":"¿Por dónde se abre una conversación que cuesta?","options":["Por tres disculpas, para preparar el terreno.","Por el contexto de todo el trimestre.","Por el punto, en la primera frase."],"answer":2,"why":"El punto temprano evita que el otro tenga que adivinar de qué va la charla. Las disculpas apiladas retrasan el hecho y suenan a culpa."},{"q":"¿Qué haces después del pedido?","options":["Callas y dejas que la otra persona entre.","Añades otro asunto, ya que estáis hablando.","Te ríes para quitarle hierro."],"answer":0,"why":"El silencio es el sitio de la respuesta. El segundo asunto y la risa deshacen el pedido."},{"q":"¿Qué delata que estás rodeando el punto?","options":["Una hora concreta.","La pila de a ver, es que, perdona y no sé si.","El nombre de la ronda o del parte."],"answer":1,"why":"Esas palabras ocupan el sitio de la primera frase. La hora y el nombre hacen lo contrario: fijan el hecho."}],"exercise":{"prompt":"Di en voz alta el principio de una conversación que estés aplazando. Primera frase, el punto. Luego el gesto, el efecto y el pedido. Sin perdona y sin es que.","seconds":75,"scaffold":["El punto","El gesto concreto","El efecto","El pedido con fecha","Silencio"],"focus":"fillers"}},{"id":"m7-interests","module":7,"title":"Intereses, no posiciones","minutes":5,"framework":"Intereses","promise":"Vas a decir para qué quieres lo que pides, y vas a preguntar para qué lo quiere la otra parte.","focus":"structure","free":true,"cards":[{"kicker":"Por qué importa","body":"Una postura es la solución ya cerrada: el viernes no se sale. Un interés es lo que esa solución intenta cuidar: no salir sin quien haya hecho el relevo. Se puede pelear la postura toda la tarde y no tocar el interés."},{"kicker":"Haz esto","body":"Di el tuyo antes de la exigencia. Pregunta el del otro: para qué, o qué quedaría resuelto. Ofrece dos caminos que cuiden los dos, no uno solo con otro nombre."},{"kicker":"En la mesa","body":"Enseñar el interés no es regalar la negociación. Es evitar una pelea sobre un día que a lo mejor ni siquiera es el problema. Si solo existe un camino, dilo, y sigue siendo más claro que una postura muda."},{"kicker":"Evita","body":"No inventes el interés del otro y lo des por cerrado. No vuelvas a tu fecha de salida en la frase siguiente, como si la pregunta hubiera sido un trámite. No trates de débil a quien explica para qué quiere lo que pide."}],"example":{"speaker":"Lucía","role":"jefa de proyecto","script":"Mi interés no es el viernes en sí. No quiero salir a producción sin una persona de guardia que haya hecho este relevo. Si eso queda cubierto el viernes, el viernes me sirve. Si no queda cubierto, prefiero el lunes a un sábado de improvisación. ¿Qué quedaría resuelto para ti si salimos el viernes sí o sí? Tengo dos caminos, y los dos cuidan la guardia: viernes con esa persona, o lunes con el turno ya previsto.","note":"Lucía suelta el interés antes de pelear el día. La pregunta deja el interés del otro en sus palabras, no en las de ella."},"quiz":[{"q":"¿Cuál de estas frases es un interés?","options":["El despliegue tiene que ser el viernes.","No quiero salir sin alguien que haya hecho este relevo.","O aceptas el viernes o no hay acuerdo."],"answer":1,"why":"El interés dice qué hay que proteger. Las otras dos ya traen la solución cerrada o la amenaza."},{"q":"¿Qué pregunta abre el interés de la otra parte?","options":["¿Por qué te pones tan rígido con la fecha?","¿Aceptas mi propuesta tal cual?","¿Qué quedaría resuelto si salimos el viernes?"],"answer":2,"why":"«Qué quedaría resuelto» pide el para qué. La pregunta por la rigidez pide una defensa, no un interés."},{"q":"¿Cuándo ofreces dos caminos?","options":["Cuando los dos cuidan los intereses que ya están dichos, y son distintos.","Cuando quieres parecer flexible y los dos dicen lo mismo.","Antes de saber qué te importa a ti."],"answer":0,"why":"Dos caminos de verdad amplían el acuerdo. Dos disfraces de la misma postura no negocian: adornan."}],"exercise":{"prompt":"Toma una postura que estés defendiendo estos días. Di el interés que hay debajo, pregunta el de la otra parte y ofrece dos caminos distintos.","seconds":90,"scaffold":["Tu interés, no la fecha","La pregunta de para qué","Camino uno","Camino dos","Qué no puedes soltar"],"focus":"structure"}},{"id":"m7-batna","module":7,"title":"BATNA","minutes":4,"framework":"BATNA","promise":"Vas a entrar sabiendo qué harás, de forma concreta, si hoy no hay acuerdo, sin inventártelo.","focus":"structure","free":false,"cards":[{"kicker":"Por qué importa","body":"BATNA es tu mejor alternativa real si esta conversación no cierra. Si no la conoces, cada cesión te sabe a pérdida. Se prepara antes de sentarte, no en el pasillo de salida."},{"kicker":"Haz esto","body":"Escríbela en concreto: con quién, en qué plazo, con qué coste. Puedes decirla sin amenaza, y decir también que prefieres cerrar aquí. Solo si existe: una reserva que no has pedido no es una alternativa."},{"kicker":"El límite","body":"Saber la tuya te evita ceder por educación por debajo de lo que ya puedes conseguir fuera. Intuir la del otro te evita dar prisa de regalo. No hace falta restregarla: hace falta no negociar contra tu propio suelo."},{"kicker":"Evita","body":"No la uses de farol. No la conviertas en un ultimátum de película. No la olvides a mitad porque el ambiente mejoró y te dio apuro nombrarla."}],"example":{"speaker":"Iker","role":"responsable de planta","script":"Si hoy no hay fecha, el lote de sensores sale con el proveedor de reserva de Vitoria. Esa vía está pedida y puede entrar en tres semanas. Prefiero cerrar contigo, porque ya conoces la línea dos. Lo que no firmo es un ya veremos que me deje sin las dos vías. Si mueves la mitad del lote a la semana trece, cancelo la reserva. Si no se puede mover, te lo digo ahora y no te hago perder la tarde.","note":"La alternativa tiene sitio y plazo, y ya está pedida. Iker la dice sin subir la voz y deja una puerta para quedarse."},"quiz":[{"q":"¿Qué es una BATNA que te sirve en la mesa?","options":["Lo que de verdad harás si hoy no hay acuerdo, ya comprobado.","Una amenaza que suena firme, aunque no la tengas preparada.","El deseo de que la otra parte acabe cediendo."],"answer":0,"why":"Tiene que poder ejecutarse el lunes. El deseo y el farol no aguantan una pregunta."},{"q":"¿Cómo se dice sin convertirla en un ultimátum?","options":["No se dice: se insinúa con un silencio.","Se dice el plan alternativo, concreto, y también que prefieres cerrar aquí.","Se grita la fecha tope al final, para que quede claro."],"answer":1,"why":"El plan concreto informa. Decir que prefieres cerrar aquí distingue la alternativa de una amenaza."},{"q":"Te preguntan un detalle de tu alternativa y no lo tienes. ¿Qué ha pasado?","options":["Que eres prudente y no conviene enseñar las cartas.","Que la negociación va bien y el detalle no importa.","Que era un farol, y a partir de ahí tu palabra pesa menos."],"answer":2,"why":"Una alternativa real se puede describir. El farol descubierto estropea esta mesa y la siguiente."}],"exercise":{"prompt":"Prepara tu alternativa para una negociación real. Dila en voz alta como se la dirías a la otra parte: concreta, sin amenaza, y con la puerta de quedarte si hay acuerdo.","seconds":75,"scaffold":["Qué harás si no hay acuerdo","En qué plazo y con quién","Por qué prefieres cerrar aquí","Qué sí movería tu plan"],"focus":"structure"}},{"id":"m7-anchor","module":7,"title":"Anclaje y concesiones","minutes":4,"framework":"Anclaje","promise":"Vas a decir el número, callar, y moverte solo a cambio de algo que puedas nombrar.","focus":"pace","free":false,"cards":[{"kicker":"Por qué importa","body":"El primer número serio tira del rango de la conversación. Si lo dices y enseguida lo rebajas, el ancla trabaja en tu contra. El ritmo es parte del número: más lento en la cifra, y silencio después."},{"kicker":"Después del número","body":"Dilo entero y cierra la boca. No te rías y no añadas un más o menos en la misma frase. El silencio no es un truco de feria: es no deshacer lo que acabas de decir."},{"kicker":"La concesión","body":"Pequeña, nombrada y cambiada por algo. Si adelantan una entrega, tú mueves un tramo del precio, y lo dices así. Si el supuesto en el que se apoya la cifra es falso, mueves la cifra por eso, no por nervio."},{"kicker":"Evita","body":"No hagas la primera concesión grande para crear clima. No regales un descuento que luego no puedes enseñar. No aceleres la frase de la cifra: es justo la que quieres que se oiga despacio."}],"example":{"speaker":"Mateo","role":"líder de equipo","script":"El mantenimiento de los tres puestos, un año, son sesenta y dos mil. Lo digo entero y me callo. El supuesto es una visita al mes y la pieza crítica ya en consigna. Si la visita pasa a ser cada semana, esta cifra no sirve. Puedo mover dos mil si la pieza llega antes del día diez, y hoy no muevo más. Si el supuesto de la visita está mal, lo corregimos antes de hablar de descuento.","note":"Mateo no se ríe ni rebaja la cifra en la misma frase. La cesión es pequeña y va atada a un día."},"quiz":[{"q":"¿Qué haces justo después de decir el número?","options":["Lo rebajas un poco, para que no suene agresivo.","Añades un más o menos, por si acaso.","Callas, sin risa y sin descuento instantáneo."],"answer":2,"why":"El silencio deja el número donde lo pusiste. Rebajarlo al momento enseña que el primero no iba en serio."},{"q":"¿Cómo es una concesión que no te deja vacío?","options":["Pequeña, nombrada y cambiada por algo concreto.","Grande y al principio, para crear clima.","Un descuento que no explicas, para que se note la buena voluntad."],"answer":0,"why":"Cambiar algo por algo mantiene el rango. La cesión grande de entrada dice que había margen de sobra."},{"q":"Te dicen que tu supuesto es falso. ¿Cuándo mueves la cifra?","options":["Enseguida, para no tensar la mesa.","Cuando el supuesto de verdad cambie, y lo dices en voz alta.","Nunca: el primer número no se toca."],"answer":1,"why":"Mover por un supuesto nuevo es rigor. Mover por el ambiente es regalar el ancla."}],"exercise":{"prompt":"Di un número que te toque negociar. Lento. Calla después. Luego ofrece una concesión pequeña a cambio de algo con nombre. Sin más o menos.","seconds":60,"scaffold":["El número, despacio","Silencio","El supuesto","La concesión a cambio de qué"],"focus":"pace"}},{"id":"m7-empathy","module":7,"title":"Empatía táctica y etiquetar","minutes":4,"framework":"Etiquetar","promise":"Vas a poner nombre a lo que se ve en la mesa, en una frase, y vas a callar para que te corrijan.","focus":"presence","free":false,"cards":[{"kicker":"Por qué importa","body":"Etiquetar es una hipótesis sobre la situación, no un retrato de la persona. «Parece que este plazo te deja sin margen de prueba» se puede corregir. Si aciertas, el otro se explica: si fallas, te corrige, y las dos cosas acercan al interés."},{"kicker":"Haz esto","body":"Una frase, tono llano, y silencio. Nombra lo que se ve: prisa, recelo a cerrar, cansancio con este tema. No digas que entiendes cómo se siente: no se puede comprobar y suena a fórmula."},{"kicker":"En la mesa","body":"Es un movimiento para negociar con más información, no una charla de cuidado personal. Tampoco es un truco para colar tu propuesta por la espalda. Si etiquetas con retintín, deja de ser hipótesis y pasa a ser reproche."},{"kicker":"Evita","body":"No etiquetes tres cosas a la vez. No llenes el silencio con tu solución. No uses la etiqueta para diagnosticar a la persona."}],"example":{"speaker":"Ane","role":"líder de equipo","script":"Parece que este viernes te deja sin tiempo de prueba. Lo digo como hipótesis, no como retrato. Si he fallado, corrígeme y sigo desde ahí. Si he acertado, el interés de verdad es la prueba y no el día. En ese caso tengo un lunes que mete la prueba dentro. Hasta que no me corrijas, no muevo la fecha.","note":"Ane etiqueta el plazo, no el carácter. No dice que entiende cómo se siente, y no mueve la fecha antes de la corrección."},"quiz":[{"q":"¿Qué es una etiqueta útil?","options":["Un diagnóstico: estás a la defensiva.","Una hipótesis de la situación: parece que este plazo te deja sin prueba.","La fórmula de que entiendes cómo se siente."],"answer":1,"why":"La hipótesis se puede corregir y habla del plazo. El diagnóstico y la fórmula hablan de la persona y no se pueden comprobar."},{"q":"¿Qué haces justo después?","options":["Callas y dejas que te corrijan.","Suelta la propuesta completa, para aprovechar.","Repites la etiqueta tres veces, con otras palabras."],"answer":0,"why":"El silencio es lo que convierte la frase en una pregunta. Llenarlo con la propuesta usa la etiqueta de gancho."},{"q":"¿Qué tono la deshace?","options":["Uno llano, como quien comprueba un dato.","Uno breve.","Uno con retintín, que en realidad es un reproche."],"answer":2,"why":"El retintín no pide corrección: acusa. El tono llano deja la frase a la altura de un dato."}],"exercise":{"prompt":"Etiqueta en una frase lo que está pasando en una negociación o en una reunión tensa. Sin diagnosticar a nadie. Di la frase y calla dos tiempos.","seconds":60,"scaffold":["Parece que… y el hecho","Sin adjetivo sobre la persona","Silencio","Solo después, tu camino"],"focus":"presence"}},{"id":"m7-no","module":7,"title":"Decir que no con gracia","minutes":4,"framework":"No y puerta","promise":"Vas a decir que no, la razón en una línea y una alternativa, sin tres disculpas y sin un sí escondido.","focus":"fillers","free":false,"cards":[{"kicker":"Por qué importa","body":"Un no claro cuida mejor la relación que un sí que no vas a cumplir. La gracia no está en el rodeo. Está en la razón breve y en una puerta que sí puedes abrir."},{"kicker":"Haz esto","body":"No, más la razón más fuerte, más la alternativa. Otra fecha, otro alcance u otra persona, si existen. Si no hay puerta, dilo también: un no limpio vale más que un quizá de tres semanas."},{"kicker":"Antes de la reunión","body":"Escribe la frase. Las muletillas salen cuando no quieres decepcionar: no sé, es que, a ver, en principio. Una disculpa basta si hace falta, y a veces no hace falta ninguna."},{"kicker":"Evita","body":"No des tres razones: las débiles se discuten y arrastran a la fuerte. No culpes a un jefe que no ha dicho eso. No dejes un «ya lo miro» si ya lo has mirado."}],"example":{"speaker":"Lucía","role":"jefa de proyecto","script":"No llego a tener el borrador el martes. Esa mañana está el comité y no lo voy a escribir de madrugada para rehacerlo después. Puedo entregarlo el jueves a las diez, con el alcance que ya cerramos. La sección nueva, si es imprescindible, sale la semana que viene. Te digo que no al martes para poder decir que sí al jueves. No lo dejo en un ya lo miro: la agenda ya está llena.","note":"Hay un no, una razón y una puerta con hora. Lucía no apila perdones ni convierte el no en un quizá."},"quiz":[{"q":"¿Qué lleva un no que no cierra la puerta de la relación?","options":["El no, una razón breve y una alternativa que sí puedes cumplir.","Tres disculpas y un ya lo miro, para no decepcionar.","Un jefe al que echarle la culpa."],"answer":0,"why":"La alternativa demuestra que el no es al plazo, no a la persona. La culpa prestada se descubre y deja peor el no."},{"q":"Dices «no sé» y la agenda, en realidad, no da. ¿Qué está pasando?","options":["Que eres prudente y falta un último dato.","Que la otra persona todavía no ha insistido bastante.","Que la muletilla está tapando un no."],"answer":2,"why":"«No sé» cabe cuando no sabes. Si la agenda ya está llena, el no sé es un rodeo."},{"q":"¿Cuántas razones conviene dar?","options":["Todas, para que no te rebatan ninguna.","La más fuerte. Las débiles se convierten en la discusión.","Ninguna: un no seco queda siempre mejor."],"answer":1,"why":"Una razón sólida se puede aceptar. Tres invitan a negociar la más floja y a olvidar la fuerte."}],"exercise":{"prompt":"Di un no que debas en el trabajo. Sin es que y sin ya lo miro. Razón en una frase y una alternativa con fecha, o di que no hay alternativa.","seconds":50,"scaffold":["El no","La razón fuerte","La puerta, con fecha","Calla"],"focus":"fillers"}}]'),q=[{id:"cap-vision",title:"Charla de visión de 3 minutos",minutes:8,brief:"Tienes tres minutos delante de tu equipo y ni una diapositiva. Sirve el arranque del turno, el lunes de producto o la reunión de proyecto. Ya han oído eslóganes que valen para cualquier empresa. Habla de un sitio que puedas señalar: una línea, un servicio, un mostrador, un cliente. Empieza por una escena corta de cómo se trabaja hoy y que no quieres repetir el mes que viene. Di luego una frase de visión que quepa en un respiro: un estándar concreto y la persona a quien le importa. Sigue con tres hábitos que harían esa frase verdad esta semana. No valen tres palabras de póster. Cierra con un pedido de este mes, con nombre y fecha. La presencia se juega al aterrizar. Termina cada frase. Mira a una persona cuando pidas el compromiso y deja un segundo quieto después de la frase de visión. No pidas perdón por usar el tiempo y no cuentes tu biografía. Si la frase la podría decir la competencia sin cambiar una palabra, cámbiala antes de abrir la boca.",scaffold:["Una escena de hoy que no quieres repetir","La frase de visión, en un respiro","Tres hábitos de esta semana","Un pedido con nombre y fecha","Un segundo de silencio después de la frase"],seconds:180,rubric:["La frase de visión nombra un estándar y a quién le importa","Los tres hábitos se pueden hacer esta semana","Hay un pedido con nombre y fecha","Terminas las frases y dejas caer la visión antes de seguir"],focus:"presence"},{id:"cap-board",title:"Actualización al comité",minutes:8,brief:"Tienes tres minutos con el comité. Detrás de ti hay más puntos y nadie ha venido a oír la crónica de las últimas seis semanas. Quieren el estado, el riesgo y lo que tienen que decidir. Empieza con BLUF: la primera frase dice si vas en fecha, qué se ha torcido y qué pides. Después, dos razones y ni una más. Un solo número, comparado con algo que la sala ya entienda: el turno anterior, el presupuesto, la promesa al cliente. Nombra un riesgo real y qué harás si se cumple. Cierra con dueño y fecha, y di qué contarás como hecho. Si no sabes una causa, dilo y di a qué hora volverás con ella. No leas la diapositiva. No recorras el calendario día por día. No pidas que confíen: enseña el límite de lo que sí puedes prometer. Elige un caso que conozcas, de planta, de software, de hospital o de un expediente, y habla con nombres de cosas, no con humo.",scaffold:["Primera frase: estado y petición","Dos razones","Un número comparado","Un riesgo y qué haces si ocurre","Dueño, fecha y qué es hecho"],seconds:180,rubric:["La primera frase ya dice el estado y la petición","Hay un solo número y está comparado","El riesgo tiene respuesta, no solo nombre","Cierras con dueño, fecha y un límite honesto"],focus:"structure"},{id:"cap-negotiation",title:"Roleplay de negociación",minutes:8,brief:"Tienes tres minutos para una negociación de verdad, no para un discurso. Al otro lado puede estar la comercial de un proveedor alemán, un cliente que quiere más alcance o un área interna que te niega a una persona. Entra sabiendo tu BATNA: qué harás, de forma concreta, si hoy no hay acuerdo. No hace falta amenazar. Sí hace falta no inventártela. Abre por intereses, no por la postura. Di para qué quieres la fecha, el precio o el alcance, y pregunta para qué lo quiere la otra parte. Pon luego tu propuesta en una frase y ancla un número. Después del número, calla. No te rebajes con una risa ni con un «más o menos». Lleva una concesión pequeña y dila solo a cambio de algo nombrado. Si notas tensión, etiquétala en una frase y vuelve al interés. Cierra con lo acordado, quién lo hace y para cuándo. Si el acuerdo no te sirve, di que te quedas con la alternativa y termina sin adornos.",scaffold:["Tu alternativa si no hay acuerdo","Tu interés y el interés del otro","Propuesta y número, luego pausa","Una concesión a cambio de algo","Cierre: qué, quién y cuándo, o te vas con la alternativa"],seconds:180,rubric:["Nombras intereses antes que posturas","El número queda solo, sin rebajarlo en la misma frase","La concesión se cambia por algo concreto","Cierras con acuerdo o con la alternativa, sin amenaza vacía"],focus:"structure"}],x={modules:v,lessons:k,capstones:q},T=JSON.parse(`[{"id":"en-meet-standup","category":"meetings","title":"Sixty-second stand-up","context":"Your squad ships software for clinic staff, and the stand-up has stretched toward twenty minutes. You are facilitating today. Model the turn you want: finished, today, and a blocker or a clean none, inside one minute.","framework":"BLUF","scaffold":["What you finished","What you are on today","The blocker, or none","Where a solve will happen"],"speakSeconds":60,"keywords":["finished","today","blocker"],"cta":["after this","the names"],"level":1,"free":true,"focus":"structure","checks":["Did finished, today, and the blocker land inside the minute?","Did you name a person, or say clearly that you need no one?","Did you keep the problem-solving out of the stand-up itself?"]},{"id":"en-meet-disagree","category":"meetings","title":"Disagree, then commit","context":"The product council wants to open a German-language flow next week, before the strings are signed off. You think that will create refunds you cannot unwind politely. Say the dissent once, then commit in the same breath if the room chooses to proceed.","framework":"Disagree and commit","scaffold":["I disagree, and the reason","The risk, in one line","Your alternative","The commit, including side meetings"],"speakSeconds":75,"keywords":["i disagree","the risk","alternative"],"cta":["i will support","side meetings"],"level":2,"free":true,"focus":"presence","checks":["Was the dissent one reason, not a stack?","Did you offer a real alternative before you stopped?","Did the commit include what you will not do in the corridor?"]},{"id":"en-meet-chair","category":"meetings","title":"Hold the clock","context":"You are chairing a city mobility meeting, and the bike-lane item has ten minutes left. A councillor has started on street lighting, which is a real issue and not this decision. Park it, name the time, and test a decision on the lane.","framework":"Timebox","scaffold":["The decision and the minutes left","The park, with a name","Who has not spoken","The decision, tested"],"speakSeconds":90,"keywords":["ten minutes","the decision","parking"],"cta":["before we close","any dissent"],"level":2,"free":false,"focus":"pace","checks":["Did you say the decision and the time near the start?","Did the tangent get a name and a place to go?","Did you test a decision before the item evaporated?"]},{"id":"en-meet-close","category":"meetings","title":"Close with owners and dates","context":"A hospital operations huddle has agreed, loosely, to move training off the drug round. People are already closing laptops. You have the last two minutes. Leave the room with names, verbs, and dates.","framework":"Owner and date","scaffold":["The decision, in one sentence","Name, verb, date","A spoken confirm","The sentence to repeat"],"speakSeconds":70,"keywords":["the decision","by wednesday","owner"],"cta":["the sentence","tomorrow morning"],"level":1,"free":false,"focus":"structure","checks":["Does every action have a name and a date?","Did the named person get a chance to confirm?","Could someone who missed the meeting repeat your last sentence?"]},{"id":"en-meet-recap","category":"meetings","title":"What we decided","context":"An agency workshop with a retail client has produced three ideas and one actual decision. The client lead is tired and about to leave for a train. Recap only what was decided, what was parked, and who sends the note.","framework":"BLUF","scaffold":["What we decided","What we parked","Who sends the note, and when"],"speakSeconds":60,"keywords":["we decided","we parked","i will send"],"cta":["by tomorrow","the note"],"level":1,"free":false,"focus":"structure","checks":["Did you separate decisions from ideas that were only discussed?","Is the parked item named, not lost?","Does the note have an owner and a time?"]},{"id":"en-meet-handover","category":"meetings","title":"Shift handover at Bilbao","context":"You are handing the Bilbao line to the incoming shift after a short stop on the infeed. The next crew has four minutes before they start. Tell them the state of the line, the check you want, and what not to rediscover at midnight.","framework":"BLUF","scaffold":["The state of the line","What caused the stop, in one line","The check before they start","Where it is written"],"speakSeconds":90,"keywords":["line","handover","before you start"],"cta":["on the sheet","tonight"],"level":2,"free":false,"focus":"structure","checks":["Could the incoming shift act without your longer story?","Is the check specific enough to do, not just to remember?","Did you say where the instruction is written?"]},{"id":"en-meet-steer","category":"meetings","title":"Steering update in six minutes","context":"The steering group for a payments platform has six minutes for your item. Spend is inside the envelope, and a partner interface is two weeks late. They do not want a tour of the backlog. Give status, the risk, and the decision you need.","framework":"BLUF","scaffold":["Status in one sentence","The risk that can still move the date","The decision you need","What you are not asking them to reopen"],"speakSeconds":120,"keywords":["status","the risk","the decision"],"cta":["this week","i need"],"level":2,"free":false,"focus":"structure","checks":["Did status, risk, and the ask appear before the detail?","Is the decision something this group can actually make?","Did you say what you are not reopening?"]},{"id":"en-meet-blocker","category":"meetings","title":"Name the blocker","context":"A school is rolling out new laptops to year seven, and the image fails on the older docking stations. You are in the project stand-up with IT and the facilities lead. Name the blocker without blaming the school, and say who you need.","framework":"BLUF","scaffold":["The blocker, in one sentence","The impact on the date","The name you need","What you will do by Friday"],"speakSeconds":60,"keywords":["blocker","the date","i need"],"cta":["by friday","the name"],"level":2,"free":false,"focus":"clarity","checks":["Is the blocker observable, rather than a judgement of the school?","Did you name a person, not a department-shaped cloud?","Is there a Friday action you own?"]},{"id":"en-meet-agenda","category":"meetings","title":"Pull the agenda back","context":"A creative review at the agency has drifted into a debate about last year's campaign. The decision on the table is which of two concepts goes to the client on Thursday. You are not the most senior person, and you do need the decision. Bring the room back without a lecture.","framework":"Timebox","scaffold":["The decision still in front of you","What you are parking","The question, restated","How you will close"],"speakSeconds":50,"keywords":["the decision","thursday","parking"],"cta":["back to","before we leave"],"level":2,"free":false,"focus":"pace","checks":["Did you name the decision before you criticised the drift?","Did the tangent get parked rather than shamed?","Could the room answer your restated question?"]},{"id":"en-meet-hybrid","category":"meetings","title":"The remote half of the room","context":"Half the maintenance leads are on the line at the plant, and half are on a video call from headquarters. The people on site have gone quiet since the headquarters voices sped up. You are chairing. Bring one remote or on-site voice in before you close the item.","framework":"Invitation pause","scaffold":["Name who you want to hear","A narrow question","Two beats","Their point, kept in their words"],"speakSeconds":75,"keywords":["on site","the question","a second"],"cta":["before we close","your point"],"level":2,"free":false,"focus":"pauses","checks":["Did you name a person rather than ask if anyone had thoughts?","Did you actually leave a pause?","Did you keep their wording when you wrote it down?"]},{"id":"en-meet-golive","category":"meetings","title":"Go or no-go","context":"A hospital is due to switch on a bed-management view tomorrow at six in the morning. One ward has not finished training, and the vendor says the defect is cosmetic. You have to recommend go or no-go to the operations director. Make the call, with the risk named.","framework":"BLUF","scaffold":["Go or no-go, in the first sentence","The reason","The risk you are accepting or refusing","The owner of the next check"],"speakSeconds":90,"keywords":["no-go","the risk","tomorrow"],"cta":["the call is","the owner"],"level":3,"free":false,"focus":"structure","checks":["Was the call in the first sentence?","Did you name the risk instead of calling the defect cosmetic and moving on?","Is there an owner for whatever happens next?"]},{"id":"en-pres-hook","category":"presentations","title":"Open with a hook","context":"You have forty-five seconds at the start of a city all-hands about a hotter summer and a bus network that already runs late. People have heard vision language before. Open with a scene or a number they can picture, then the stake, then what you are asking this quarter.","framework":"Opening hook","scaffold":["A scene or a number","The stake this year","The ask this quarter"],"speakSeconds":45,"keywords":["this summer","the stake","this quarter"],"cta":["this quarter","the ask"],"level":1,"free":true,"focus":"pitch","checks":["Did a concrete scene or number arrive before any slogan?","Could a listener say the stake back?","Is the ask small enough for a quarter, not a lifetime?"]},{"id":"en-pres-plc","category":"presentations","title":"The PLC downtime","context":"The plant director has five minutes between meetings and has asked what happened on the night shift. Line two lost time because the filler PLC faulted, and the handover sheet had no reset steps. Explain the downtime, the cause, and what you want on the sheet before Friday.","framework":"BLUF","scaffold":["The downtime and the line, first","The cause, in plain words","What you want on the sheet","The owner and the day"],"speakSeconds":90,"keywords":["downtime","line","plc","reset","night shift"],"cta":["by friday","the sheet"],"level":2,"free":true,"focus":"clarity","checks":["Did downtime and the line appear in the opening?","Could a director repeat the cause without the jargon?","Is there an owner for the sheet before Friday?"]},{"id":"en-pres-scqa","category":"presentations","title":"Pitch it in SCQA","context":"You are pitching a narrower first release of a scheduling tool to an executive group that likes the full vision. They already believe the current tool is slow. They do not yet believe you should cut scope. Build situation, complication, question, and answer before you show a roadmap.","framework":"SCQA","scaffold":["Situation they already accept","The complication","The question","Your answer","One piece of evidence"],"speakSeconds":120,"keywords":["right now","what changed","i recommend"],"cta":["the decision","approve"],"level":2,"free":false,"focus":"structure","checks":["Did the situation sound like something they already believe?","Was the question explicit before the answer?","Is the recommendation one choice, not a menu?"]},{"id":"en-pres-technical","category":"presentations","title":"Explain it without the jargon","context":"A non-technical chief operating officer wants to know why checkout failed for an hour on Tuesday. You know it was a retry storm against a slow ledger. They need the effect, one picture, and the decision, not the architecture diagram.","framework":"Plain words first","scaffold":["The effect a customer felt","One picture","The real term, once","The decision you recommend"],"speakSeconds":90,"keywords":["customers","picture","i recommend"],"cta":["this week","the decision"],"level":2,"free":false,"focus":"clarity","checks":["Did the effect come before the specialist term?","Did you use the real term once, tied to a picture?","Does the last line ask for a decision?"]},{"id":"en-pres-data","category":"presentations","title":"One chart, one decision","context":"An agency is showing a client that cost per qualified lead fell, while brand search did not move. The client will stare at the chart and invent a story. You have one minute to say what changed, why it matters, and what you will do next month.","framework":"Data to decision","scaffold":["What changed, with the window","Why it matters","What you will do","The limit of the number"],"speakSeconds":70,"keywords":["fell","because","next month"],"cta":["the owner","next month"],"level":2,"free":false,"focus":"structure","checks":["Is there one story, not a tour of every line?","Did you say the limit of the number?","Is the next action owned?"]},{"id":"en-pres-qna","category":"presentations","title":"The hostile number","context":"In a budget preview, a finance director asks why your overrun is small on the slide and larger in the appendix. You have the reconciliation, and you do not have a prettier story. Answer at the same pace you were already using, with the limit included.","framework":"Steady state","scaffold":["The figure they asked for","Where it lives","The limit","When you will send the bridge"],"speakSeconds":60,"keywords":["the figure","the source","the limit"],"cta":["i will send","tomorrow"],"level":3,"free":false,"focus":"presence","checks":["Did you answer the number before you explained the history?","Did your pace stay ordinary?","Did you give a time for the fuller bridge, rather than a new number?"]},{"id":"en-pres-close","category":"presentations","title":"Land the ask","context":"You have recommended a Thursday launch of a smaller release, and the room has enjoyed the discussion enough to avoid deciding. You have forty-five seconds left. Close on the decision, the risk you are accepting, and what you need before people stand up.","framework":"Opening frame","scaffold":["The decision, again","The risk","What you need before they leave"],"speakSeconds":45,"keywords":["the decision","the risk","before we leave"],"cta":["before we leave","a yes"],"level":1,"free":false,"focus":"structure","checks":["Is the ask a decision, not a theme?","Did you name the risk you are asking them to accept?","Did you stop after the ask?"]},{"id":"en-pres-demo","category":"presentations","title":"The demo breaks","context":"You are midway through a live demo for a logistics client when the status screen spins and does not recover. The point of the demo was a shorter handover, not the screen itself. Keep the room, say what they would have seen, and name the next step.","framework":"Steady state","scaffold":["What you were showing","What they would have seen","What you will send today","The question you still want"],"speakSeconds":75,"keywords":["the point","you would have seen","today"],"cta":["i will send","today"],"level":3,"free":false,"focus":"presence","checks":["Did you stay on the point rather than narrating the failure?","Was your pace steady?","Is there a same-day follow-up?"]},{"id":"en-pres-allhands","category":"presentations","title":"Two minutes at the all-hands","context":"You have two minutes at a company all-hands after a quarter of incident pages. People do not need another value word. Describe one Tuesday that should look different, the standard you will hold, and the part you want from this room.","framework":"Concrete vision","scaffold":["The scene","The standard","The part this room plays"],"speakSeconds":80,"keywords":["on a tuesday","the standard","this quarter"],"cta":["this quarter","one change"],"level":2,"free":false,"focus":"pitch","checks":["Could someone picture the Tuesday?","Did the standard land as a decision, not a wish?","Is there a part for people who are not on your team?"]},{"id":"en-pres-safety","category":"presentations","title":"Start-up briefing","context":"A line is about to start after maintenance, and contractors are new to the cell. You have a short briefing before anyone removes a guard. Say what would make you stop the start, the check, and who calls it.","framework":"Plain words first","scaffold":["What a safe start looks like","The check before the guard comes off","Who can stop the start","What you will not improvise"],"speakSeconds":80,"keywords":["stop","the check","before we start"],"cta":["before we start","the owner"],"level":2,"free":false,"focus":"clarity","checks":["Are the words plain enough for someone on their first day?","Is the stop condition specific?","Did you name who is allowed to halt the start?"]},{"id":"en-pres-budget","category":"presentations","title":"The variance, in one pass","context":"A city finance board wants the variance on a street-works programme. You are over on traffic management and under on materials. They have seen rounded comfort before. Give the number, the source, the limit, and the decision you recommend.","framework":"Claim, evidence, limit","scaffold":["The variance","The source","What the number does not include","The decision"],"speakSeconds":90,"keywords":["variance","the source","the limit"],"cta":["the decision","this month"],"level":2,"free":false,"focus":"structure","checks":["Did the number come with a source?","Did you state the limit before someone else found it?","Is the recommendation matched to that limit?"]},{"id":"en-lead-sbi-plus","category":"leadership","title":"Praise the specific act","context":"A nurse on your ward rewrote the night handover so the incoming shift could see unresolved meds in the first three lines. You want that repeated, including on quiet nights. Give the praise in SBI, and do not attach a request for something else.","framework":"SBI","scaffold":["When and where","The act","The impact","Keep doing this"],"speakSeconds":60,"keywords":["last night","you","the impact"],"cta":["keep doing","including"],"level":1,"free":true,"focus":"presence","checks":["Is the behaviour something a camera would have seen?","Did you name the effect on the next shift?","Did the praise end without a but?"]},{"id":"en-lead-no","category":"leadership","title":"Say no and leave a path","context":"A head of department wants your team to add a second school site to this month's device rollout. The year-seven delivery already owns the crew. Decline it, give the reason, and offer one alternative that has a date.","framework":"A useful no","scaffold":["The request, briefly","No, early","One reason","A real alternative with a date"],"speakSeconds":60,"keywords":["i cannot","because","instead"],"cta":["the twentieth","next month"],"level":2,"free":true,"focus":"fillers","checks":["Did the no arrive before a long warm-up?","Is the reason a commitment, not a ghost policy?","Could they act on the alternative without chasing you?"]},{"id":"en-lead-sbi-fix","category":"leadership","title":"Correct it in private","context":"Twice this month a contractor started work on the filler without the lock-out note signed. You are speaking to the supervisor in private, not on the shop floor. Use SBI, one behaviour, and one invitation. Then stop.","framework":"SBI","scaffold":["The situation","The behaviour a camera saw","The impact","One invitation"],"speakSeconds":70,"keywords":["twice","the note","the impact"],"cta":["next time","before"],"level":2,"free":false,"focus":"structure","checks":["Is the behaviour observable, with no motive attached?","Did you stay with one behaviour?","Did you stop after the invitation?"]},{"id":"en-lead-delegate","category":"leadership","title":"Hand off the vendor chase","context":"A supplier in Germany has slipped a firmware date, and you cannot make every call yourself. You are asking a project coordinator to own the chase. Be clear about the outcome, the date, and what they may decide without you.","framework":"Owner and date","scaffold":["The outcome you want","What they can decide alone","What they must bring back","The date"],"speakSeconds":60,"keywords":["you own","by friday","the outcome"],"cta":["come back","with the date"],"level":2,"free":false,"focus":"structure","checks":["Is the outcome a result, not a list of tasks?","Did you say what they may decide without you?","Is the return date explicit?"]},{"id":"en-lead-change","category":"leadership","title":"Announce the change","context":"Your agency is moving client status meetings from weekly slide reviews to a one-page written note, with a live meeting only when a decision is needed. Some people hear this as a loss of airtime. Announce what changes, what stays, and when it starts.","framework":"BLUF","scaffold":["What changes","What stays","When it starts","Where questions go"],"speakSeconds":90,"keywords":["what changes","what stays","starting"],"cta":["questions","the date"],"level":2,"free":false,"focus":"presence","checks":["Did what changes and what stays both get said?","Is the start date specific?","Did you leave a real place for questions?"]},{"id":"en-lead-vision","category":"leadership","title":"The vision in a minute","context":"Your team can describe the ticket queue and cannot describe a good ordinary day. You have a minute at the start of a planning meeting. Give them one scene, one standard, and one thing you will stop.","framework":"Concrete vision","scaffold":["The scene","The standard","What you will stop","What you need this quarter"],"speakSeconds":90,"keywords":["on a tuesday","the standard","we will stop"],"cta":["this quarter","one thing"],"level":2,"free":false,"focus":"pitch","checks":["Is the scene a working day, not a slogan?","Did you name something the team will stop?","Could someone repeat the standard after the meeting?"]},{"id":"en-lead-skipstatus","category":"leadership","title":"Skip the status","context":"Your one-to-one with a strong engineer has become a recital of tickets you could have read. You want the real question: where they are stuck, or what they want to take next. Open by retiring the status, and ask one question worth their time.","framework":"Invitation pause","scaffold":["What you will not spend the time on","The real question","A pause","One thing you will do after"],"speakSeconds":50,"keywords":["not the status","the question","where you are stuck"],"cta":["one thing","i will"],"level":2,"free":false,"focus":"presence","checks":["Did you actually retire the status recital?","Was the question specific?","Did you leave room for an answer?"]},{"id":"en-lead-priority","category":"leadership","title":"Reset what is first","context":"Your team is treating three projects as equally first, and the clinic release is the one with a date a customer already has. You need to say what is first, what stops, and why, without a hedge stack. People have planned around the ambiguity.","framework":"Clean recommendation","scaffold":["What is first","What stops or waits","The reason","The date you will revisit"],"speakSeconds":60,"keywords":["first","stops","because"],"cta":["this sprint","the cut"],"level":2,"free":false,"focus":"fillers","checks":["Is there one first, not three?","Did you say what stops?","Did you avoid a stack of maybe and just?"]},{"id":"en-lead-credit","category":"leadership","title":"Give the credit in the room","context":"A junior scheduler caught a clash between training and a drug round, and the install date moved because of her note. She is in the room. Give the credit in one specific act, with your own part in a single clause.","framework":"Hero shift","scaffold":["Who was on the spot","The act","Your part, one clause","What is different now"],"speakSeconds":45,"keywords":["she","the note","because of"],"cta":["the standard","in writing"],"level":1,"free":false,"focus":"presence","checks":["Is she the centre, not you?","Is the act specific?","Would she be comfortable hearing it in public?"]},{"id":"en-lead-skip","category":"leadership","title":"Skip-level, plainly","context":"You have twenty minutes with a director who does not run your team. You can spend it on good news, or you can name one risk they will not hear in the polished pack. Bring the risk, the ask, and what you have already tried.","framework":"BLUF","scaffold":["The risk, first","What you have already done","The ask","What you are not asking them to do"],"speakSeconds":80,"keywords":["the risk","i have already","the ask"],"cta":["a decision","this month"],"level":3,"free":false,"focus":"presence","checks":["Did the risk come before the good news?","Did you show what you have already tried?","Is the ask something a director can actually grant?"]},{"id":"en-lead-standard","category":"leadership","title":"Raise the bar with an example","context":"Incident notes on your team bury the customer impact under a timeline. You want the impact in the first line from Monday. Use one recent example, name the standard, and say how you will check it. This is a standard, not a scolding.","framework":"SBI","scaffold":["The example, without a name if it would shame","The standard","How you will check","When it starts"],"speakSeconds":60,"keywords":["the standard","for example","from monday"],"cta":["from monday","the first line"],"level":2,"free":false,"focus":"structure","checks":["Is the standard specific enough to meet on Monday?","Did the example teach, rather than expose someone?","Did you say how you will notice whether it happened?"]},{"id":"en-int-yourself","category":"interviews","title":"Tell me about yourself","context":"A hiring panel has asked you to introduce yourself for a product lead role. They have your CV. They do not need your childhood or a list of every employer. Use present, past, and future, and land on why this role, inside ninety seconds.","framework":"Present, past, future","scaffold":["What you do now","The past that makes it credible","What you want next","Why this role"],"speakSeconds":90,"keywords":["right now","before that","next"],"cta":["this role","because"],"level":1,"free":true,"focus":"structure","checks":["Did present, past, and future each get a beat?","Did you leave out the tour of every job?","Does the last line say why this role, not why you want a change in general?"]},{"id":"en-int-star","category":"interviews","title":"A conflict, in STAR","context":"The interviewer has asked for a time you disagreed with a stakeholder and still shipped. They want the situation, what you were responsible for, what you did, and the result. Pick one real conflict, not a slogan about being collaborative.","framework":"STAR","scaffold":["The situation","Your responsibility","The action you took","The result, including the relationship after"],"speakSeconds":90,"keywords":["the situation","i","the result"],"cta":["afterwards","we still"],"level":2,"free":false,"focus":"structure","checks":["Is the conflict specific, with a real stake?","Are the actions yours, not the team's in the abstract?","Does the result include what happened after the decision?"]},{"id":"en-int-miss","category":"interviews","title":"The deadline you missed","context":"They ask about a deadline you missed. A polished near-miss will sound like a dodge. Choose a real one, name the cause you owned, and say the check you run now so the same miss is harder.","framework":"STAR","scaffold":["What you missed","The cause you owned","What you changed","The evidence it stuck"],"speakSeconds":80,"keywords":["i missed","the cause","since then"],"cta":["the check","now"],"level":2,"free":false,"focus":"presence","checks":["Did you own a cause, rather than a vague we?","Is the change something you still do?","Did you skip the costume of a failure that was secretly a triumph?"]},{"id":"en-int-weakness","category":"interviews","title":"A weakness you are working","context":"The question is the classic weakness question. They have heard I work too hard. Give a real limit that matters in the role, the step you practise, and a sign it is shifting. Keep it to one limit.","framework":"Purposeful vulnerability","scaffold":["The limit, plainly","Why it matters in the work","The step you practise","A recent sign"],"speakSeconds":70,"keywords":["the limit","i practise","recently"],"cta":["the evidence","now"],"level":2,"free":false,"focus":"presence","checks":["Is the weakness real enough that the role would notice it?","Did you describe a practice, not a personality makeover?","Did you stop at one limit?"]},{"id":"en-int-failure","category":"interviews","title":"A failure you owned","context":"A panel wants a failure, not a humble-brag. You shipped a change that increased failed payments for a week. Tell the impact, what you did in the first day, and what the customer saw afterwards.","framework":"STAR","scaffold":["What failed","The impact","What you did in the first day","What changed for the customer"],"speakSeconds":80,"keywords":["i owned","the impact","the first day"],"cta":["afterwards","the customer"],"level":2,"free":false,"focus":"structure","checks":["Is the failure a real one, with a cost?","Did you say what you did, not only what you learned?","Is the afterwards visible to a customer or a user?"]},{"id":"en-int-why","category":"interviews","title":"Why this role","context":"You are interviewing for an operations lead in a city transport team. They ask why this role, and why now. Tie it to work you have already done and to a scene you want this team to be able to run.","framework":"Concrete vision","scaffold":["The work you have done that rhymes","What this team is actually for","A scene of the job going well","Why now"],"speakSeconds":60,"keywords":["this team","because","the work"],"cta":["in a year","the scene"],"level":1,"free":false,"focus":"pitch","checks":["Did you talk about their work, not only your ambition?","Is there a scene, not a list of values?","Is the why-now believable?"]},{"id":"en-int-stakeholder","category":"interviews","title":"The stakeholder you opposed","context":"They want a time you disagreed with someone senior and then committed. Use a real stakeholder, one reason, and what you did after the decision went against you or with you. Include the relationship afterwards.","framework":"Disagree and commit","scaffold":["Who, and the decision","Your dissent","What was decided","How you behaved after"],"speakSeconds":80,"keywords":["i disagreed","we decided","afterwards"],"cta":["the relationship","after"],"level":2,"free":false,"focus":"presence","checks":["Is the stakeholder specific?","Did you show the commit, not only the courage?","Does the story end with the working relationship, not a victory lap?"]},{"id":"en-int-lead","category":"interviews","title":"A time you led","context":"The question is about leadership without a formal title, or with one. Pick a moment where people were stuck and your move changed the work. Keep yourself as the person who cleared a path, and name who did the work.","framework":"STAR","scaffold":["The stake","Who was stuck","What you did","The result they could see"],"speakSeconds":90,"keywords":["the team","the stake","the result"],"cta":["what changed","afterwards"],"level":2,"free":false,"focus":"structure","checks":["Is there a stake a stranger could understand?","Are your actions distinct from the team's?","Is the result observable?"]},{"id":"en-int-gap","category":"interviews","title":"The gap in your experience","context":"The role wants hospital operations experience, and yours is mostly industrial planning. They have noticed. Do not pretend. Say what you have not done, what you have done that transfers, and how you would close the gap in the first months.","framework":"Claim, evidence, limit","scaffold":["What you have not done","What transfers, with an example","How you would close the gap","A question back, if useful"],"speakSeconds":50,"keywords":["i have not","i have","the first months"],"cta":["in the first","months"],"level":2,"free":false,"focus":"presence","checks":["Did you name the gap plainly?","Is the transfer a real example, not a trait?","Is the plan for the first months specific?"]},{"id":"en-int-question","category":"interviews","title":"The question you ask them","context":"They have offered you the last few minutes for your questions. A question about holidays wastes the moment. Ask something that shows you understand the work and that you want to know what good looks like in the first six months.","framework":"Opening frame","scaffold":["The question","Why you are asking","What you will listen for"],"speakSeconds":45,"keywords":["the question","because","good looks like"],"cta":["in six months","what good"],"level":1,"free":false,"focus":"structure","checks":["Would the answer change how you do the job?","Did you say why you are asking?","Did you avoid a question you could have read on the website?"]},{"id":"en-int-start","category":"interviews","title":"When you can start","context":"They ask when you could start. You have a notice period and a handover you will not abandon. Give the date, the constraint, and what you can do before day one. Do not apologise for having a current job.","framework":"BLUF","scaffold":["The earliest honest date","The constraint","What you can do before day one"],"speakSeconds":40,"keywords":["notice","start","handover"],"cta":["the date","before day one"],"level":1,"free":false,"focus":"structure","checks":["Is the date one you can keep?","Did you name the handover as a professional constraint?","Did you offer something useful before day one, if that is real?"]},{"id":"en-neg-interests","category":"negotiation","title":"Ask for the interest","context":"A vendor wants a three-year lock in exchange for any discount on night cover. You want uptime, and you do not yet know what the lock does for them. Restate their position, ask for the interest, and share one of yours before you offer a package.","framework":"Interests versus positions","scaffold":["Their position, fairly","One interest question","Your interest","A pause before any package"],"speakSeconds":90,"keywords":["your position","what you need","my interest"],"cta":["if that is the need","one option"],"level":2,"free":true,"focus":"structure","checks":["Did you restate their position before you countered it?","Was there a real question about the need underneath?","Did you share an interest of your own at the same level?"]},{"id":"en-neg-salary","category":"negotiation","title":"The salary conversation","context":"You have an offer for a product role, and the base is below the band you can defend with your current scope. You like the team. Ask for a number, give a reason a hiring manager can repeat, and name one non-cash item you would trade only if you choose to.","framework":"Anchor and concession","scaffold":["The number","The reason, tied to scope","What you are glad about in the offer","One trade you might consider"],"speakSeconds":120,"keywords":["the number","because","the scope"],"cta":["i am asking","the base"],"level":3,"free":false,"focus":"structure","checks":["Did a reasoned number appear, rather than a hope they will guess?","Could their boss repeat your reason?","Did you avoid apologising for asking?"]},{"id":"en-neg-anchor","category":"negotiation","title":"Put the anchor down","context":"You are renewing a support contract. Scope is flat and night cover has got heavier. Open with a number you can defend, give the reason, and wait. Have one smaller concession ready, traded for the response time, and do not use it in the first breath.","framework":"Anchor and concession","scaffold":["The number","The reason","A silence","The concession, only if you need it"],"speakSeconds":80,"keywords":["the number","the reason","the term"],"cta":["if you can","i can move"],"level":2,"free":false,"focus":"pace","checks":["Is the opening number one you could explain to your own director?","Did you leave a silence after it?","Is the concession smaller, and tied to something you want?"]},{"id":"en-neg-label","category":"negotiation","title":"Label what you hear","context":"A counterpart has gone quiet after you asked for four-hour on-site cover. You suspect their boss will question the travel cost. Label the pressure in one clause, wait, and do not solve it in the same breath.","framework":"Labelling","scaffold":["It sounds like","A pause","Room for a correction","A question, not a package yet"],"speakSeconds":60,"keywords":["it sounds like","the pressure","your boss"],"cta":["which matters","more"],"level":2,"free":false,"focus":"presence","checks":["Is the label about the pressure, not their character?","Did you pause instead of adding but?","Did you leave them able to correct you?"]},{"id":"en-neg-batna","category":"negotiation","title":"Name your alternative","context":"The vendor will not leave a three-year lock, and your alternative is a second firm that can start in nine weeks at last year's rate, with weaker on-site cover. You would rather stay. Say the alternative once, calmly, and name the condition under which you would still sign today.","framework":"BATNA","scaffold":["The interest, briefly","The alternative, once","The condition for staying","A dated next step"],"speakSeconds":90,"keywords":["alternative","nine weeks","uptime"],"cta":["today","the other firm"],"level":3,"free":false,"focus":"structure","checks":["Is the alternative real enough to survive a practical question?","Did you say it once, without a sneer?","Is there a condition under which you would stay?"]},{"id":"en-neg-scope","category":"negotiation","title":"Scope against price","context":"A supplier in Stuttgart wants a higher rate and is offering extra reporting you did not ask for. You need the firmware date and the on-site clause, not a thicker slide pack. Trade scope for price, and keep the term at one year.","framework":"Interests versus positions","scaffold":["What you actually need","What you will not pay extra for","The trade","The term"],"speakSeconds":100,"keywords":["scope","the price","one year"],"cta":["the date","the cover"],"level":2,"free":false,"focus":"pace","checks":["Did you separate the scope you need from the scope they added?","Is the trade explicit?","Did you keep the term where you wanted it?"]},{"id":"en-neg-deadline","category":"negotiation","title":"Is that deadline real","context":"The other side says the price expires on Friday. You suspect the date is a push, not a real constraint. Ask what happens if you miss it, and what a date next week would cost them. Stay curious, and do not call them liars.","framework":"Interests versus positions","scaffold":["The date they named","What happens if you miss it","What a later date costs","Your own real date, if you have one"],"speakSeconds":70,"keywords":["the date","what happens","if we miss"],"cta":["a real date","the cost"],"level":3,"free":false,"focus":"structure","checks":["Did you test the deadline with a practical question?","Did you avoid accusing them of inventing it?","Do you know your own real date?"]},{"id":"en-neg-trade","category":"negotiation","title":"The concession you planned","context":"You decided before the meeting that you could move a small amount on price if the on-site response stayed inside four hours and the term stayed one year. The moment has come. Make that concession slowly, write it down, and do not add a second gift.","framework":"Anchor and concession","scaffold":["The move","What you need in exchange","A pause","The note you will write"],"speakSeconds":70,"keywords":["i can move","in exchange","the term"],"cta":["written down","before i agree"],"level":2,"free":false,"focus":"pace","checks":["Was the concession one you planned, not a panic?","Did it buy something named?","Did you refuse to add a second concession in the same breath?"]},{"id":"en-neg-headcount","category":"negotiation","title":"The headcount ask","context":"You need one coordinator for a city programme that is currently run on goodwill and late nights. Finance wants a hiring freeze story. Ask for the role by naming the interest, the cost of not having it, and the decision you need this quarter.","framework":"Interests versus positions","scaffold":["The interest, not the job title first","The cost of the gap","The role, plainly","The decision and the quarter"],"speakSeconds":80,"keywords":["the interest","the cost","one role"],"cta":["this quarter","a decision"],"level":2,"free":false,"focus":"structure","checks":["Did the interest come before the org-chart request?","Is the cost of the gap concrete?","Is the ask one role, with a time?"]},{"id":"en-neg-renewal","category":"negotiation","title":"Open the renewal","context":"You are opening a renewal conversation with the firm that already knows your night shift. You do not want to lead with a complaint about last quarter's invoice. Open on uptime, last year's scope, and the cover you need to keep.","framework":"Interests versus positions","scaffold":["The shared interest","What stayed the same in the scope","What you need kept","An invitation for their constraint"],"speakSeconds":90,"keywords":["uptime","last year","the cover"],"cta":["one year","the term"],"level":2,"free":false,"focus":"presence","checks":["Did you open on a shared interest?","Did you avoid spending the first minute on the invoice?","Did you invite their constraint?"]},{"id":"en-neg-silence","category":"negotiation","title":"Silence after the number","context":"You have just said the number. The other side is quiet, and the quiet feels rude. Your job is to let the reason stand. Practise the number, the reason, and the silence, and say what you will not do while you wait.","framework":"Anchor and concession","scaffold":["The number","The reason","The silence","What you will not add"],"speakSeconds":45,"keywords":["the number","the reason","i can wait"],"cta":["i can wait","your figure"],"level":2,"free":false,"focus":"pauses","checks":["Did you say the number once?","Did the reason stand without a discount attached?","Did you name the silence as a choice?"]},{"id":"en-imp-prep","category":"impromptu","title":"Answer with PREP","context":"In a leadership meeting someone asks, without warning, whether you would delay a launch to widen a sample. You have no slide. Answer with a point, one reason, one recent example, and the point again, inside forty-five seconds.","framework":"PREP","scaffold":["The point","One reason","One example","The point again"],"speakSeconds":45,"keywords":["the point","because","for example"],"cta":["so i would","again"],"level":1,"free":true,"focus":"structure","checks":["Did the point come first, with a verb?","Was there one example, not three reasons?","Did you end on the point rather than on the story?"]},{"id":"en-imp-table","category":"impromptu","title":"Table topic","context":"You are given a table topic with no preparation: a meeting you would delete from the calendar, and what you would keep in its place. You have one minute. Take a position, give a reason, and end with a change you could make on Monday.","framework":"Table topic","scaffold":["The meeting you would delete","Why","What you would keep or replace it with","The Monday change"],"speakSeconds":60,"keywords":["i would delete","because","i would keep"],"cta":["on monday","one change"],"level":1,"free":true,"focus":"presence","checks":["Did you take a position in the first sentence?","Was the reason concrete?","Did you land on a change, not a shrug?"]},{"id":"en-imp-unknown","category":"impromptu","title":"When you do not know","context":"A director asks for a figure you do not have: how many night calls missed the four-hour cover last quarter. Guessing would be worse than the gap. Say that you do not know, say what you can check, and name when you will send it.","framework":"Steady state","scaffold":["I do not know","What you do know, if anything","Where you will look","When you will send it"],"speakSeconds":40,"keywords":["i don't know","i will check","by"],"cta":["by tomorrow","i will send"],"level":2,"free":false,"focus":"presence","checks":["Did you say you do not know, without a costume?","Did you avoid inventing a number?","Is there a time when the real figure will exist?"]},{"id":"en-imp-lift","category":"impromptu","title":"Thirty seconds with the director","context":"You step into a lift with the director who funds your headcount. You have the ride, not a meeting. Give the point, the stake, and one ask they could grant this week. Leave the history of the project in the lobby.","framework":"Opening frame","scaffold":["The point","The stake","The ask this week"],"speakSeconds":40,"keywords":["the point","the stake","this week"],"cta":["this week","a decision"],"level":1,"free":false,"focus":"structure","checks":["Did the point arrive before any biography?","Is the ask small enough for this week?","Did you stop when the doors would open?"]},{"id":"en-imp-toast","category":"impromptu","title":"A short thank-you","context":"A colleague is leaving the project, and someone has asked you to say a few words before the next item. You have under a minute. Name one act, the effect it had, and what you hope the team keeps. Skip the roast.","framework":"Specific recognition","scaffold":["One act","The effect","What the team should keep"],"speakSeconds":40,"keywords":["you","because","we keep"],"cta":["we keep","thank you"],"level":1,"free":false,"focus":"presence","checks":["Is the act specific?","Did you skip a generic you will be missed and nothing else?","Is there something the team can keep?"]},{"id":"en-imp-corridor","category":"impromptu","title":"Bad news in the corridor","context":"You meet the operations lead in the corridor, and they ask if the morning start went cleanly. It did not: twenty minutes down, cause known, line now running. Give the result, the cause, and when the fuller note will arrive. Do not make them pull it out of you.","framework":"BLUF","scaffold":["The result","The cause, short","The current state","When the note arrives"],"speakSeconds":50,"keywords":["the result","the cause","running"],"cta":["by noon","the note"],"level":3,"free":false,"focus":"presence","checks":["Did the bad number come first?","Did you give the cause you actually know?","Is there a time for the written note?"]},{"id":"en-imp-reframe","category":"impromptu","title":"Turn a complaint into a request","context":"A ward clerk says your training notes arrive too late to change the rota. The sentence is a complaint, and it contains a real request. Reframe it as the impact, the request, and an owner, and check you heard them right.","framework":"Labelling","scaffold":["The impact, in their terms","The request underneath","The owner and the day","A check that you heard it"],"speakSeconds":50,"keywords":["the impact","the request","by friday"],"cta":["by friday","did i hear"],"level":2,"free":false,"focus":"structure","checks":["Did you name the impact before you defended the team?","Is there a request someone could fulfil?","Did you check that you heard them?"]},{"id":"en-imp-which","category":"impromptu","title":"Which one first","context":"A sponsor stops you and asks which of two projects should go first this week: the clinic release with a public date, or the internal dashboard a director likes. You have under a minute. Choose, say why, and say what happens to the other one.","framework":"Clean recommendation","scaffold":["Which one first","The reason","What happens to the other","When you would revisit"],"speakSeconds":45,"keywords":["first","because","the other"],"cta":["this week","the cut"],"level":2,"free":false,"focus":"fillers","checks":["Did you choose, rather than say both?","Is the reason a commitment someone already has?","Did the other project get a fate, not a vague later?"]},{"id":"en-imp-intro","category":"impromptu","title":"Introduce your colleague","context":"A client has joined a call early, and your colleague, who will lead the technical questions, is about to speak. Introduce them in a few sentences: who they are, the work they own, and the question they can answer better than you.","framework":"Hero shift","scaffold":["Their name and role","The work they own","The question to put to them"],"speakSeconds":40,"keywords":["this is","she owns","the question"],"cta":["ask her","the question"],"level":1,"free":false,"focus":"presence","checks":["Did you give them a real ownership, not a compliment?","Did you hand over a question, rather than keep the floor?","Would they recognise themselves in what you said?"]},{"id":"en-imp-risk","category":"impromptu","title":"Say the risk out loud","context":"A start-up briefing is about to end, and nobody has mentioned that the spare sensor is not on the night shift. You can see the gap. Name the risk, the sign that would tell you it is happening, and the check you want before the line starts.","framework":"BLUF","scaffold":["The risk","The sign","The check","Who can stop the start"],"speakSeconds":50,"keywords":["the risk","the sign","before we start"],"cta":["before we start","the check"],"level":2,"free":false,"focus":"clarity","checks":["Is the risk specific enough to picture?","Did you say the sign, not only the worry?","Is there a check before the start?"]},{"id":"en-imp-mic","category":"impromptu","title":"You are handed the microphone","context":"At a customer dinner, your sponsor says you should say a few words about the quarter. You had no warning. Thank them for a specific piece of work, tell one short turn from the quarter, and name the next step you share.","framework":"Story spine","scaffold":["Thanks, specific","One turn from the quarter","What is different now","The next step you share"],"speakSeconds":60,"keywords":["thank you","this quarter","next"],"cta":["the next step","together"],"level":2,"free":false,"focus":"pace","checks":["Did you thank them for something specific?","Was there one turn, not a quarterly report?","Did you keep the pace conversational, and stop?"]}]`),S=JSON.parse('[{"id":"es-meet-standup","category":"meetings","title":"El minuto del stand-up","context":"El stand-up del equipo de la clínica se ha ido a veinte minutos. Hoy lo facilitas tú. Enseña el turno que quieres: qué quedó, qué es hoy, y un bloqueo o un ninguno limpio.","framework":"BLUF","scaffold":["Qué terminaste","En qué estás hoy","El bloqueo, o ninguno","Dónde se resuelve"],"speakSeconds":60,"keywords":["terminé","hoy","bloqueo"],"cta":["después","nombres"],"level":1,"free":true,"focus":"structure","checks":["¿Cupo en un minuto?","¿Hay una persona, o dijiste que no necesitas a nadie?","¿Dejaste la solución fuera del stand-up?"]},{"id":"es-meet-disagree","category":"meetings","title":"Disentir y comprometerse","context":"El consejo quiere abrir el flujo en alemán la semana que viene, antes de cerrar los textos. Tú crees que eso fabrica devoluciones. Dilo una vez, y comprométete en el mismo aliento si la sala sigue.","framework":"Disagree and commit","scaffold":["Disiento, y la razón","El riesgo, en una línea","Tu alternativa","El compromiso"],"speakSeconds":75,"keywords":["disiento","alemán","riesgo"],"cta":["sigo","nota"],"level":2,"free":true,"focus":"presence","checks":["¿Lo dijiste una vez?","¿Hay un riesgo concreto?","¿Dijiste cómo ayudas si pierdes?"]},{"id":"es-meet-chair","category":"meetings","title":"Sujetar el reloj","context":"La reunión de operaciones de la planta de Bilbao tiene cuarenta minutos y cuatro decisiones. La gente trae un quinto tema. Tú presides.","framework":"Timebox","scaffold":["El reloj y las decisiones","Qué pasa con lo que no está","Los minutos del cierre"],"speakSeconds":90,"keywords":["minutos","decisiones"],"cta":["nombres","fechas"],"level":2,"free":false,"focus":"pace","checks":["¿Dijiste el reloj?","¿Aparcaste el tema extra?","¿Protegiste el cierre?"]},{"id":"es-meet-close","category":"meetings","title":"Cerrar con dueño y fecha","context":"La conversación fue buena y borrosa. Tienes un minuto antes de que se levanten las sillas.","framework":"Owner and date","scaffold":["Qué decidimos","Quién","Para cuándo","Qué no hacemos"],"speakSeconds":70,"keywords":["decidimos","dueño"],"cta":["viernes","fecha"],"level":1,"free":false,"focus":"structure","checks":["¿Una decisión, no un tema?","¿Un nombre?","¿Una fecha?"]},{"id":"es-meet-recap","category":"meetings","title":"Lo que decidimos","context":"Estuviste callado. Quien preside te pide el recuento antes de que la gente se vaya.","framework":"BLUF","scaffold":["La decisión","El dueño","La fecha","Una pregunta abierta, si queda"],"speakSeconds":60,"keywords":["decidimos"],"cta":["para","dueño"],"level":1,"free":false,"focus":"structure","checks":["¿Lo repetiría quien acaba de entrar?","¿Te saltaste el debate?","¿Como mucho una pregunta abierta?"]},{"id":"es-meet-handover","category":"meetings","title":"Relevo en Bilbao","context":"El turno de tarde hereda una bomba tibia y dos tareas. Estás en la pizarra, dos minutos.","framework":"BLUF","scaffold":["Lo que no se puede adivinar","Las dos tareas","El disparador para llamar"],"speakSeconds":90,"keywords":["bomba","turno"],"cta":["llamar","pizarra"],"level":2,"free":false,"focus":"structure","checks":["¿El riesgo va delante?","¿Hay un disparador, no una sensación?","¿Hay nombres?"]},{"id":"es-meet-steer","category":"meetings","title":"Parte de seis minutos","context":"El comité de dirección te da seis minutos sobre el paro de la línea. No quieren el mes. Quieren la decisión.","framework":"BLUF","scaffold":["El estado en una frase","Una cifra","Lo que pides"],"speakSeconds":120,"keywords":["línea","minutos"],"cta":["martes","comprar"],"level":2,"free":false,"focus":"structure","checks":["¿El punto fue el primero?","¿Una cifra?","¿Una petición?"]},{"id":"es-meet-blocker","category":"meetings","title":"Nombra el bloqueo","context":"Todo el mundo dice que va bien. Tú sabes que el rodamiento no ha llegado. Dilo sin teatro.","framework":"BLUF","scaffold":["El bloqueo","Desde cuándo","Quién lo desbloquea"],"speakSeconds":60,"keywords":["rodamiento","bloqueo"],"cta":["hoy","proveedor"],"level":2,"free":false,"focus":"clarity","checks":["¿Lo nombraste?","¿Hay una persona?","¿Sin dramatizar?"]},{"id":"es-meet-agenda","category":"meetings","title":"Devolver el orden del día","context":"Lleváis doce minutos en un tema que no era la reunión. Tú presides y tienes que cortar sin humillar.","framework":"Timebox","scaffold":["Dónde estamos","A qué volvemos","Dónde vive lo otro"],"speakSeconds":50,"keywords":["orden","volvemos"],"cta":["margen","luego"],"level":2,"free":false,"focus":"pace","checks":["¿Cortaste con calma?","¿Nombraste el tema real?","¿El otro tema tiene un sitio?"]},{"id":"es-meet-hybrid","category":"meetings","title":"La mitad remota","context":"La mitad de la sala está en un portátil con el micro cerrado. Necesitas su cifra antes de decidir.","framework":"Invitation pause","scaffold":["Nómbralos","La pregunta estrecha","La espera"],"speakSeconds":75,"keywords":["remoto","cifra"],"cta":["espero","pizarra"],"level":2,"free":false,"focus":"pauses","checks":["¿Usaste un nombre?","¿Dejaste la pausa?","¿No llenaste el silencio?"]},{"id":"es-meet-golive","category":"meetings","title":"Vamos o no vamos","context":"El go-live es el jueves. La prueba de fuga falló anoche. La sala quiere un ánimo. Tú tienes que decir si se sale o no.","framework":"BLUF","scaffold":["La recomendación","La prueba","La fecha que sí sostienes"],"speakSeconds":90,"keywords":["jueves","prueba"],"cta":["no","lunes"],"level":3,"free":false,"focus":"structure","checks":["¿Recomendaste?","¿La prueba está en la frase?","¿Hay una fecha alternativa?"]},{"id":"es-pres-hook","category":"presentations","title":"Abrir con un gancho","context":"Tienes cuarenta y cinco segundos en una reunión cansada. Ayer un sensor convirtió un portón en una pared. El punto es el rearranque, no la parada.","framework":"Opening hook","scaffold":["Una escena","El punto en la frase siguiente","Qué vas a enseñar"],"speakSeconds":45,"keywords":["ayer","rearranque"],"cta":["este mes","dueño"],"level":1,"free":true,"focus":"pitch","checks":["¿Hubo escena?","¿El punto llegó enseguida?","¿Sin gracias de entrada?"]},{"id":"es-pres-plc","category":"presentations","title":"La parada del PLC","context":"La línea tres paró a las 10:14 porque el PLC perdió el sensor del portón. No hiciste un puente. Arreglaste el soporte. Cuarenta y dos minutos, cero chatarra. Dirección quiere la causa, el coste y el paso.","framework":"BLUF","scaffold":["La causa","El tiempo y la chatarra","La acción, el dueño, la fecha"],"speakSeconds":90,"keywords":["parada","línea","plc"],"cta":["jueves","mantenimiento"],"level":2,"free":true,"focus":"clarity","checks":["¿Dijiste parada y línea pronto?","¿El puente no es el héroe?","¿Hay fecha?"]},{"id":"es-pres-scqa","category":"presentations","title":"El pitch en SCQA","context":"El mejor cliente pide cambios en la misma semana. El plan sigue con dos semanas de congelación. Pides una puerta estrecha, no una religión nueva.","framework":"SCQA","scaffold":["Situación","Complicación","Pregunta","Respuesta"],"speakSeconds":120,"keywords":["cliente","congelación"],"cta":["puerta","semana"],"level":2,"free":false,"focus":"structure","checks":["¿La situación antes de la respuesta?","¿Una pregunta?","¿Una respuesta que se puede pagar?"]},{"id":"es-pres-technical","category":"presentations","title":"Sin la jerga","context":"Explica la red de promesas entre el sensor, el PLC y el brazo. Sin números de pieza. Una consecuencia de presupuesto.","framework":"Plain words first","scaffold":["La imagen","Qué se rompió","Qué cuesta y qué no"],"speakSeconds":90,"keywords":["sensor","promesa"],"cta":["soporte","presupuesto"],"level":2,"free":false,"focus":"clarity","checks":["¿Se puede repetir la imagen?","¿Sin sopa de letras?","¿Un coste?"]},{"id":"es-pres-data","category":"presentations","title":"Un gráfico, una decisión","context":"Tienes un gráfico de paradas. La cifra que importa es once minutos, desde veintiséis. No recorras las barras.","framework":"Data to decision","scaffold":["La cifra","El sentido","La decisión"],"speakSeconds":70,"keywords":["once","minutos"],"cta":["regla","rearranque"],"level":2,"free":false,"focus":"structure","checks":["¿La cifra primero?","¿Un sentido?","¿Una decisión?"]},{"id":"es-pres-qna","category":"presentations","title":"La cifra hostil","context":"Alguien pregunta por qué no puenteaste y ahorraste veinte minutos. Responde y para.","framework":"Steady state","scaffold":["La respuesta directa","El coste de la otra opción","Parar"],"speakSeconds":60,"keywords":["puente","parar"],"cta":["mano","protección"],"level":3,"free":false,"focus":"presence","checks":["¿La respuesta en la primera frase?","¿Sin gira de disculpas?","¿Paraste?"]},{"id":"es-pres-close","category":"presentations","title":"Aterrizar la petición","context":"Llevas el contenido. Te quedan cuarenta y cinco segundos y todavía no has pedido nada.","framework":"Opening frame","scaffold":["La petición","El dueño","La fecha"],"speakSeconds":45,"keywords":["necesito","sí"],"cta":["viernes","hoy"],"level":1,"free":false,"focus":"structure","checks":["¿Hay un verbo?","¿Un nombre?","¿Una fecha?"]},{"id":"es-pres-demo","category":"presentations","title":"La demo se rompe","context":"En la demo, la pantalla se queda en blanco. Hay doce personas. No vas a narrar el pánico.","framework":"Steady state","scaffold":["Qué ven","Qué haces ahora","Cuándo vuelves al hilo"],"speakSeconds":75,"keywords":["pantalla","sigo"],"cta":["dos minutos","pizarra"],"level":3,"free":false,"focus":"presence","checks":["¿Calma concreta?","¿Un siguiente paso?","¿Sin culpar al aparato durante un minuto?"]},{"id":"es-pres-allhands","category":"presentations","title":"Dos minutos en el all-hands","context":"Te dan dos minutos delante de toda la planta. Quieren una imagen del mes que viene, no un organigrama.","framework":"Concrete vision","scaffold":["El lunes que quieres","Un hábito","Tu primer paso"],"speakSeconds":80,"keywords":["lunes","pizarra"],"cta":["esta semana","notas"],"level":2,"free":false,"focus":"pitch","checks":["¿Una imagen?","¿Un hábito?","¿Empiezas tú?"]},{"id":"es-pres-safety","category":"presentations","title":"Parte de arranque","context":"Es el primer día de un operario nuevo. Tienes un minuto antes de que toque la línea. Tres cosas, no doce.","framework":"Plain words first","scaffold":["Leer","Recorrer","Llamar"],"speakSeconds":80,"keywords":["tres","hora"],"cta":["parar","llamar"],"level":2,"free":false,"focus":"clarity","checks":["¿Exactamente tres?","¿Son acciones?","¿Paraste?"]},{"id":"es-pres-budget","category":"presentations","title":"La desviación, de una pasada","context":"Hay un sobrecoste. Es el motor de repuesto. El resto del presupuesto va en fecha. Pide la decisión.","framework":"Claim, evidence, limit","scaffold":["La cifra","Por qué esta y no otra","Lo que pides"],"speakSeconds":90,"keywords":["motor","coste"],"cta":["comprar","martes"],"level":2,"free":false,"focus":"structure","checks":["¿Una cifra?","¿El límite de lo que sabes?","¿Una petición?"]},{"id":"es-lead-sbi-plus","category":"leadership","title":"Elogiar el acto concreto","context":"Ayer, con la alarma, un técnico llamó la parada, señaló el sensor y esperó. Quieres que el equipo copie eso, no un «buen trabajo».","framework":"SBI","scaffold":["La situación","La conducta","El efecto y el estándar"],"speakSeconds":60,"keywords":["alarma","parada","sensor"],"cta":["estándar","otra vez"],"level":1,"free":true,"focus":"presence","checks":["¿Nombraste la conducta?","¿El efecto?","¿Se puede copiar mañana?"]},{"id":"es-lead-no","category":"leadership","title":"Decir que no y dejar un camino","context":"Dirección quiere un relato semanal nuevo. La hora que cuesta es la hora en que recorres la línea. Ya dijiste que no el mes pasado.","framework":"A useful no","scaffold":["El no, pronto","La razón que no ha cambiado","La oferta más pequeña, si es real"],"speakSeconds":60,"keywords":["no","línea","informe"],"cta":["viernes","foto"],"level":2,"free":true,"focus":"fillers","checks":["¿El no en la primera frase?","¿Sin un colchón de perdón?","¿La oferta es concreta?"]},{"id":"es-lead-sbi-fix","category":"leadership","title":"Corregir en privado","context":"Tres relevos decían «revisar la bomba» y el turno siguiente arrancó una bomba aislada. Hablas con quien escribió las notas. El cuidado no está en duda. La frase, sí.","framework":"SBI","scaffold":["Cuándo y dónde","La frase que falló","La línea nueva"],"speakSeconds":70,"keywords":["nota","bomba"],"cta":["esta noche","arrancar"],"level":2,"free":false,"focus":"structure","checks":["¿Conducta, no carácter?","¿El efecto?","¿Una frase que pueden usar hoy?"]},{"id":"es-lead-delegate","category":"leadership","title":"Soltar la persecución del proveedor","context":"Conocen la pieza mejor que tú. Quieres un sí, un no o una condición. No un quizá.","framework":"Owner and date","scaffold":["El objetivo","La autoridad","Cómo los cubres"],"speakSeconds":60,"keywords":["proveedor","fecha"],"cta":["sí","condición"],"level":2,"free":false,"focus":"structure","checks":["¿El objetivo está claro?","¿La autoridad está clara?","¿Hay una vuelta si la llamada se tuerce?"]},{"id":"es-lead-change","category":"leadership","title":"Anunciar el cambio","context":"El informe del viernes llega tarde a la reunión del jueves. Desde el lunes, el informe es el miércoles. Una página.","framework":"BLUF","scaffold":["Qué cambia","Por qué","Qué se hace más difícil","Cómo acompañas las dos primeras semanas"],"speakSeconds":90,"keywords":["miércoles","informe"],"cta":["página","leo"],"level":2,"free":false,"focus":"presence","checks":["¿El cambio en la primera frase?","¿Una razón?","¿Un apoyo, no un encogimiento de hombros?"]},{"id":"es-lead-vision","category":"leadership","title":"La visión en un minuto","context":"El equipo está harto de pósters. Di el futuro en una frase que se pueda repetir en la máquina del café.","framework":"Concrete vision","scaffold":["La imagen","La conducta","Parar"],"speakSeconds":90,"keywords":["relevo","quieto"],"cta":["copiar","semana"],"level":2,"free":false,"focus":"pitch","checks":["¿Una frase?","¿Una conducta, no una palabra de valor?","¿La podrían repetir?"]},{"id":"es-lead-skipstatus","category":"leadership","title":"Saltarse el estado","context":"Tu gente empieza cada uno a uno recitando el estado. Tú quieres el atasco, no el parte.","framework":"Invitation pause","scaffold":["Para el recital","La pregunta","La pausa"],"speakSeconds":50,"keywords":["atasco","qué"],"cta":["espera","nombre"],"level":2,"free":false,"focus":"presence","checks":["¿Cortaste el recital con respeto?","¿Una pregunta?","¿Una pausa?"]},{"id":"es-lead-priority","category":"leadership","title":"Volver a poner lo primero","context":"Hay tres fuegos. El cliente grita y la bomba está tibia. Alguien tiene que oír qué va primero.","framework":"Clean recommendation","scaffold":["Lo primero","Lo que espera","El disparador para cambiar el orden"],"speakSeconds":60,"keywords":["primero","bomba"],"cta":["cliente","tres"],"level":2,"free":false,"focus":"fillers","checks":["¿Un orden?","¿Un nombre?","¿Un disparador?"]},{"id":"es-lead-credit","category":"leadership","title":"Dar el crédito en la sala","context":"El arreglo fue de Lena. Un visitante te felicita a ti. Devuélvelo en público.","framework":"Hero shift","scaffold":["Su nombre","Lo que hizo","Tu parte, más pequeña"],"speakSeconds":45,"keywords":["lena"],"cta":["ella","llamó"],"level":1,"free":false,"focus":"presence","checks":["¿Su nombre primero?","¿Concreto?","¿No lo recuperaste?"]},{"id":"es-lead-skip","category":"leadership","title":"El skip-level, en llano","context":"Tu dirección quiere saber cómo está el turno de noche, sin el filtro de los partes bonitos. Tienes un minuto.","framework":"BLUF","scaffold":["Lo que es verdad","Lo que te preocupa","Lo que ya estás haciendo"],"speakSeconds":80,"keywords":["noche","verdad"],"cta":["brida","viernes"],"level":3,"free":false,"focus":"presence","checks":["¿Sin adorno?","¿Una preocupación concreta?","¿Un paso que ya es tuyo?"]},{"id":"es-lead-standard","category":"leadership","title":"Subir el listón con un ejemplo","context":"Quieres que el relevo quepa en cinco minutos. No des un discurso. Da un ejemplo de uno que ya cupo.","framework":"SBI","scaffold":["El ejemplo","Qué tenía","Qué pides a partir de mañana"],"speakSeconds":60,"keywords":["relevo","cinco"],"cta":["mañana","primera línea"],"level":2,"free":false,"focus":"structure","checks":["¿Un ejemplo real?","¿Una conducta?","¿Una fecha de inicio?"]},{"id":"es-int-yourself","category":"interviews","title":"Preséntate","context":"Te entrevistan para llevar una línea. Quieren presente, pasado y futuro, no la infancia ni una lista de herramientas.","framework":"Present, past, future","scaffold":["Qué haces ahora","Una prueba","Qué quieres después"],"speakSeconds":90,"keywords":["línea","equipo","después"],"cta":["puesto","primero"],"level":1,"free":true,"focus":"structure","checks":["¿El presente primero?","¿Un relato, no cinco?","¿Un futuro que encaja con este trabajo?"]},{"id":"es-int-star","category":"interviews","title":"Un conflicto, en STAR","context":"Cuéntales un desacuerdo con diseño sobre una protección. Situación, tarea, acción, resultado. Incluye el coste.","framework":"STAR","scaffold":["Situación","Tarea","Acción","Resultado, con el coste"],"speakSeconds":90,"keywords":["protección","diseño"],"cta":["retraso","norma"],"level":2,"free":false,"focus":"structure","checks":["¿Las cuatro partes?","¿Tu acción?","¿Un resultado con coste?"]},{"id":"es-int-miss","category":"interviews","title":"El plazo que no cumpliste","context":"Llegaste tarde a un plazo que habías dicho en voz alta. No lo disfraces de aprendizaje luminoso. Di el fallo y la hora nueva que sí cumpliste.","framework":"STAR","scaffold":["El plazo","Qué hiciste al ver que no llegabas","Qué es distinto ahora"],"speakSeconds":80,"keywords":["plazo","tarde"],"cta":["dije","antes"],"level":2,"free":false,"focus":"presence","checks":["¿El fallo primero?","¿Sin villano?","¿Un cambio concreto?"]},{"id":"es-int-weakness","category":"interviews","title":"Una debilidad en la que trabajas","context":"Te preguntan en qué no eres bueno. No digas perfeccionismo. Di una debilidad de oficio y el ejercicio.","framework":"Purposeful vulnerability","scaffold":["La debilidad","Lo que costó","El ejercicio de ahora"],"speakSeconds":70,"keywords":["debilidad","ejercicio"],"cta":["ahora","sigo"],"level":2,"free":false,"focus":"presence","checks":["¿Una debilidad real?","¿Un coste?","¿Una práctica actual?"]},{"id":"es-int-failure","category":"interviews","title":"Un fallo que te quedaste","context":"La nota del sensor era ambigua y el turno siguiente arrancó la bomba. La escribiste tú.","framework":"STAR","scaffold":["Qué hiciste","El efecto","La regla de ahora"],"speakSeconds":80,"keywords":["nota","bomba"],"cta":["primera línea","ahora"],"level":2,"free":false,"focus":"structure","checks":["¿Te lo quedaste?","¿Un efecto?","¿Una regla?"]},{"id":"es-int-why","category":"interviews","title":"Por qué este puesto","context":"Te preguntan por qué quieres este trabajo, en esta planta. Nada de pasión genérica.","framework":"Concrete vision","scaffold":["Qué viste de su problema","Qué has hecho que rima","Qué quieres aprender aquí"],"speakSeconds":60,"keywords":["línea","aquí"],"cta":["primero","aprender"],"level":1,"free":false,"focus":"pitch","checks":["¿Específico de ellos?","¿Una prueba?","¿Un aprendizaje?"]},{"id":"es-int-stakeholder","category":"interviews","title":"La parte a la que te opusiste","context":"Te opusiste a un director y luego ejecutaste su decisión. Quieren ver el desacuerdo y el compromiso, no la venganza.","framework":"Disagree and commit","scaffold":["El desacuerdo","La razón","Cómo lo ejecutaste"],"speakSeconds":80,"keywords":["disiento","ejecuté"],"cta":["nota","riesgo"],"level":2,"free":false,"focus":"presence","checks":["¿Una vez?","¿Sin humillar?","¿Un compromiso visible?"]},{"id":"es-int-lead","category":"interviews","title":"Una vez que lideraste","context":"No buscan un cargo. Buscan un momento en que la gente hizo algo distinto porque tú estabas.","framework":"STAR","scaffold":["La escena","Qué pediste","Qué cambió"],"speakSeconds":90,"keywords":["pedí","cambiamos"],"cta":["nombre","fecha"],"level":2,"free":false,"focus":"structure","checks":["¿Una escena?","¿Tu petición?","¿Un cambio?"]},{"id":"es-int-gap","category":"interviews","title":"El hueco de tu experiencia","context":"No has llevado una planta de este tamaño. No lo tapes. Di el hueco y cómo lo cubrirías los primeros noventa días.","framework":"Claim, evidence, limit","scaffold":["El hueco","Lo que sí traes","El plan de los noventa días"],"speakSeconds":50,"keywords":["hueco","noventa"],"cta":["aprender","acompañar"],"level":2,"free":false,"focus":"presence","checks":["¿El hueco en voz alta?","¿Sin disfraz?","¿Un plan corto?"]},{"id":"es-int-question","category":"interviews","title":"La pregunta que les haces","context":"Se acaba la entrevista. Haz una pregunta que demuestre que entendiste el trabajo.","framework":"Opening frame","scaffold":["La observación","La pregunta","Parar"],"speakSeconds":45,"keywords":["turno","relevo"],"cta":["cómo","quién"],"level":1,"free":false,"focus":"structure","checks":["¿Una pregunta?","¿Apoyada en algo real?","¿Paraste después?"]},{"id":"es-int-start","category":"interviews","title":"Cuándo puedes empezar","context":"Te preguntan la fecha. Tienes un relevo que no quieres dejar a medias. Di una fecha que puedas cumplir.","framework":"BLUF","scaffold":["La fecha","Lo que cierras antes","Lo que no prometes"],"speakSeconds":40,"keywords":["empiezo","relevo"],"cta":["lunes","cierro"],"level":1,"free":false,"focus":"structure","checks":["¿Una fecha?","¿Un cierre honesto?","¿Sin un quizá?"]},{"id":"es-neg-interests","category":"negotiation","title":"Pedir el interés","context":"El proveedor quiere bajar el precio. Tú quieres una fecha que puedas decir en voz alta. La prueba se queda. Busca el interés debajo de su cifra.","framework":"Interests versus positions","scaffold":["Su interés","El tuyo","El intercambio"],"speakSeconds":90,"keywords":["fecha","precio","prueba"],"cta":["mantengo","muevo"],"level":2,"free":true,"focus":"structure","checks":["¿Nombraste su interés?","¿Separaste precio y fecha?","¿La prueba sigue en pie?"]},{"id":"es-neg-salary","category":"negotiation","title":"La conversación del salario","context":"El alcance es mayor que el anuncio: la línea, los proveedores, una nota semanal a dirección. Di la banda.","framework":"Anchor and concession","scaffold":["El alcance que oíste","La banda","La otra palanca si la banda no se mueve"],"speakSeconds":120,"keywords":["alcance","banda"],"cta":["revisión","arriba"],"level":3,"free":false,"focus":"structure","checks":["¿El alcance antes de la cifra?","¿Una banda, no una disculpa?","¿Una segunda palanca?"]},{"id":"es-neg-anchor","category":"negotiation","title":"Dejar el ancla","context":"Antes de los descuentos: ochenta y cuatro mil, tres pagos, atados a la prueba, la instalación y un mes tranquilo.","framework":"Anchor and concession","scaffold":["La cifra","Lo que supone","La única razón para moverla"],"speakSeconds":80,"keywords":["ochenta","prueba"],"cta":["planta","mover"],"level":2,"free":false,"focus":"pace","checks":["¿La cifra pronto?","¿Los supuestos en voz alta?","¿Una regla para moverla?"]},{"id":"es-neg-label","category":"negotiation","title":"Etiquetar lo que oyes","context":"Están cansados del tema y tienen miedo de cerrarlo. Dícelo sin burla. Luego recomienda.","framework":"Labelling","scaffold":["La etiqueta","La recomendación","La culpa que te quedas"],"speakSeconds":60,"keywords":["cansados","cerrar"],"cta":["piloto","semanas"],"level":2,"free":false,"focus":"presence","checks":["¿Una etiqueta, no una acusación?","¿Una recomendación?","¿Ofreciste quedarte el error?"]},{"id":"es-neg-batna","category":"negotiation","title":"Nombrar la alternativa","context":"Quieren una cláusula de penalización que tu seguro no cubre. Puedes terminar lo que ya hay y volver el trimestre que viene con menos alcance. Dícelo sin voz de amenaza.","framework":"BATNA","scaffold":["La limitación","La otra opción real","La puerta que sigue abierta"],"speakSeconds":90,"keywords":["cláusula","seguro"],"cta":["trimestre","me quedo"],"level":3,"free":false,"focus":"structure","checks":["¿La limitación antes de irte?","¿Sin teatro?","¿Una forma de seguir?"]},{"id":"es-neg-scope","category":"negotiation","title":"Alcance contra precio","context":"Quieren el mismo alcance por menos dinero. Tú puedes quitar una entrega, no fingir que el mismo trabajo cabe en la cifra nueva.","framework":"Interests versus positions","scaffold":["Qué sale del alcance","Qué se queda","La cifra que corresponde"],"speakSeconds":100,"keywords":["alcance","quito"],"cta":["entrega","cifra"],"level":2,"free":false,"focus":"pace","checks":["¿Un recorte real?","¿Sin humo?","¿Una cifra coherente?"]},{"id":"es-neg-deadline","category":"negotiation","title":"¿Esa fecha es real?","context":"Te exigen el viernes. Sospechas que el viernes es una costumbre, no una necesidad. Pregúntalo sin acusar.","framework":"Interests versus positions","scaffold":["La fecha que oíste","La pregunta por el interés","Lo que sí puedes prometer"],"speakSeconds":70,"keywords":["viernes","real"],"cta":["lunes","prueba"],"level":3,"free":false,"focus":"structure","checks":["¿Preguntaste el interés?","¿Sin acusar?","¿Una promesa que cumplirías?"]},{"id":"es-neg-trade","category":"negotiation","title":"La concesión que planeaste","context":"Puedes mover el calendario de pagos y el día de formación. No puedes quitar la prueba de aceptación.","framework":"Anchor and concession","scaffold":["Lo que puedes cambiar","Lo que no","Invitar su cambio"],"speakSeconds":70,"keywords":["prueba","pagos"],"cta":["mantengo","cambio"],"level":2,"free":false,"focus":"pace","checks":["¿Una lista que puedes cumplir?","¿La prueba se queda?","¿Hay sitio para que ellos se muevan?"]},{"id":"es-neg-headcount","category":"negotiation","title":"Pedir la persona","context":"El trabajo nuevo no cabe en el turno. Pides una persona, no «recursos». Di qué deja de pasar si no llega.","framework":"Interests versus positions","scaffold":["La persona","El trabajo que no cabe","Qué se cae si dices que no"],"speakSeconds":80,"keywords":["persona","turno"],"cta":["contrato","fecha"],"level":2,"free":false,"focus":"structure","checks":["¿Una persona, no un recurso?","¿El trabajo concreto?","¿La consecuencia?"]},{"id":"es-neg-renewal","category":"negotiation","title":"Abrir la renovación","context":"El contrato vence en seis semanas. Quieres hablar antes de que sea una urgencia de ellos o tuya.","framework":"Interests versus positions","scaffold":["La fecha del contrato","Qué quieres conservar","Qué estás dispuesto a revisar"],"speakSeconds":90,"keywords":["contrato","semanas"],"cta":["renovar","revisar"],"level":2,"free":false,"focus":"presence","checks":["¿La fecha pronto?","¿Un interés, no un ultimátum?","¿Un sitio para revisar?"]},{"id":"es-neg-silence","category":"negotiation","title":"El silencio después de la cifra","context":"Has dicho el número. Ellos callan. No regales un descuento para tapar el silencio.","framework":"Anchor and concession","scaffold":["La cifra","Callar","La siguiente frase, solo si preguntan"],"speakSeconds":45,"keywords":["cifra","callo"],"cta":["espero","pregunta"],"level":2,"free":false,"focus":"pauses","checks":["¿Dejaste el silencio?","¿No bajaste la cifra solo?","¿La siguiente frase espera una pregunta?"]},{"id":"es-imp-prep","category":"impromptu","title":"Responder con PREP","context":"Te toca: «las mejores reuniones son las cortas». No hay diapositivas. Punto, razón, ejemplo, punto.","framework":"PREP","scaffold":["Punto","Razón","Ejemplo de tu semana","Punto otra vez"],"speakSeconds":45,"keywords":["reuniones","cortas"],"cta":["punto","otra vez"],"level":1,"free":true,"focus":"structure","checks":["¿Abriste con el punto?","¿El ejemplo es tuyo?","¿Volviste al punto?"]},{"id":"es-imp-table","category":"impromptu","title":"Tema de improvisación","context":"Tema: una luz roja en una máquina es un regalo. Sesenta segundos. Sin notas después del primer aire.","framework":"Table topic","scaffold":["La afirmación","Por qué","Una imagen","Parar"],"speakSeconds":60,"keywords":["roja","parar"],"cta":["regalo","parar"],"level":1,"free":true,"focus":"presence","checks":["¿Empezaste antes de que el silencio se volviera incómodo?","¿Una sola idea?","¿Un final limpio?"]},{"id":"es-imp-unknown","category":"impromptu","title":"Cuando no lo sabes","context":"Te preguntan la causa y no la tienes. No regales una adivinanza.","framework":"Steady state","scaffold":["Lo que sabes","Lo que no sabes","Cuándo vuelves"],"speakSeconds":40,"keywords":["no sé","causa"],"cta":["y media","paro"],"level":2,"free":false,"focus":"presence","checks":["¿Dijiste que no lo sabes?","¿Sin precisión falsa?","¿Una hora de vuelta?"]},{"id":"es-imp-lift","category":"impromptu","title":"Treinta segundos con dirección","context":"Te cruzas con dirección en el ascensor. Tienes el paro de ayer y una petición.","framework":"Opening frame","scaffold":["El hecho","La petición","Callar"],"speakSeconds":40,"keywords":["ayer","parada"],"cta":["jueves","brida"],"level":1,"free":false,"focus":"structure","checks":["¿El hecho primero?","¿Una petición?","¿Callaste después?"]},{"id":"es-imp-toast","category":"impromptu","title":"Un agradecimiento corto","context":"Alguien se va del turno. Tienes cuarenta segundos. Nada de «ha sido un placer» vacío.","framework":"Specific recognition","scaffold":["Un acto concreto","El efecto en el equipo","Un deseo que no sea humo"],"speakSeconds":40,"keywords":["gracias","turno"],"cta":["concreto","efecto"],"level":1,"free":false,"focus":"presence","checks":["¿Un acto?","¿Un efecto?","¿Sin adjetivos vacíos?"]},{"id":"es-imp-corridor","category":"impromptu","title":"Mala noticia en el pasillo","context":"Te paran entre dos reuniones. La chatarra no fue cero. Tienes cincuenta segundos y no vas a esconderlo.","framework":"BLUF","scaffold":["El hecho","A quién afecta","El siguiente paso"],"speakSeconds":50,"keywords":["chatarra","fuga"],"cta":["lunes","cambio"],"level":3,"free":false,"focus":"presence","checks":["¿El hecho primero?","¿Sin colchón?","¿Un paso?"]},{"id":"es-imp-reframe","category":"impromptu","title":"Volver una queja una petición","context":"Alguien se queja de la reunión. No te defiendas. Convierte la queja en una petición que se pueda hacer.","framework":"Labelling","scaffold":["Lo que oíste","La petición que podría ser","Si la entendiste"],"speakSeconds":50,"keywords":["queja","petición"],"cta":["entonces","concreto"],"level":2,"free":false,"focus":"structure","checks":["¿Sin defenderte primero?","¿Una petición posible?","¿Comprobaste que era esa?"]},{"id":"es-imp-which","category":"impromptu","title":"Cuál va primero","context":"Te dan dos fuegos y preguntan cuál. Elige. No los narres los dos con el mismo peso.","framework":"Clean recommendation","scaffold":["El primero","Por qué","Qué pasa con el otro"],"speakSeconds":45,"keywords":["primero","porque"],"cta":["el otro","después"],"level":2,"free":false,"focus":"fillers","checks":["¿Elegiste?","¿Una razón?","¿El otro no desapareció del mapa?"]},{"id":"es-imp-intro","category":"impromptu","title":"Presentar a tu colega","context":"Te piden que presentes a quien hizo el arreglo. No te presentes tú de paso.","framework":"Hero shift","scaffold":["Su nombre y el acto","Por qué importa hoy","Callar"],"speakSeconds":40,"keywords":["presento","hizo"],"cta":["ella","él"],"level":1,"free":false,"focus":"presence","checks":["¿Su nombre es el sujeto?","¿Un acto?","¿No te colaste?"]},{"id":"es-imp-risk","category":"impromptu","title":"Decir el riesgo en voz alta","context":"Todo el mundo quiere oír que se llega. Tú ves un riesgo que todavía no está en la nota.","framework":"BLUF","scaffold":["El riesgo","Qué lo dispararía","Qué pides que quede escrito"],"speakSeconds":50,"keywords":["riesgo","si"],"cta":["nota","escrito"],"level":2,"free":false,"focus":"clarity","checks":["¿El riesgo concreto?","¿Un disparador?","¿Pediste que se escriba?"]},{"id":"es-imp-mic","category":"impromptu","title":"Te pasan el micrófono","context":"No toca, y te pasan el micrófono. Tienes un minuto. Una historia con espinazo, no un agradecimiento.","framework":"Story spine","scaffold":["El problema","La elección","El coste o el cambio"],"speakSeconds":60,"keywords":["problema","elegimos"],"cta":["ahora","coste"],"level":2,"free":false,"focus":"pace","checks":["¿Hay un problema?","¿Una elección?","¿Un final?"]}]'),j="The harbour briefing",E="At six the harbour is quiet, and the yellow crane waits over the black water. A thin mist sits on the river. The night crew left three notes and one open question about the south pump. Please read this as you would brief a new team. The first shift checks the gate, the gauge, and the spare belt. Then they walk the line from the red cabinet to the blue door. If the pressure holds, they start. If it drops, they stop and call. Clear speech keeps the choice small: start, stop, or wait. We owe the room a short path, not a long story. Say the numbers once, then the name of the person who owns the next hour.",L="Introduce yourself as if to a new team. Who you are, what you are here to do, and what you want from the first week.",A=60,I=30,z={readTitle:j,readText:E,speakPrompt:L,readSeconds:A,speakSeconds:I},D="El parte del muelle",P="A las seis el muelle está quieto y la grúa amarilla espera sobre el agua negra. Una niebla fina cubre la ría. El turno de noche dejó tres notas y una pregunta abierta sobre la bomba sur. Lee esto como si informaras a un equipo nuevo. El primer turno revisa el portón, el manómetro y la correa de repuesto. Luego recorre la línea desde el armario rojo hasta la puerta azul. Si la presión aguanta, arrancan. Si cae, paran y avisan. Hablar claro deja la decisión pequeña: arrancar, parar o esperar. Le debemos a la sala un camino corto, no un relato largo. Di las cifras una vez, y después el nombre de quien se queda la próxima hora.",W="Preséntate como si llegaras a un equipo nuevo. Quién eres, a qué vienes y qué quieres de la primera semana.",N=60,U=30,C={readTitle:D,readText:P,speakPrompt:W,readSeconds:N,speakSeconds:U},Q=["you know","i mean","kind of","sort of","okay so","basically","actually","literally","like"],Y=["so","okay so"],B=["right"],O={phrases:Q,sentenceInitial:Y,trailing:B},H=["o sea","en plan","a ver","digamos","este","eh","pues","bueno","tipo","vale"],R=["pues","bueno","a ver","este"],M=["no","vale","sabes"],F={phrases:H,sentenceInitial:R,trailing:M},V=["i think maybe","sort of","kind of","just","maybe","perhaps","a bit","i guess","sorry but"],G=["creo que quizas","un poco","solo","solamente","quiza","tal vez","a lo mejor","no se si"];function o(e,t,n,s,a,r,i,l,c){return{lang:e,twisters:t,passages:n,warmups:s,modules:a.modules,lessons:a.lessons,capstones:a.capstones,scenarios:r,baseline:i,fillers:l,hedging:c}}const J={en:o("en",d,h,m,b,T,z,O,V),es:o("es",u,p,f,x,S,C,F,G)};function K(e){return J[e]}export{K as g};
